// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 은신
// 암살자 · 자객 · 그림자술사 · 첩자 · 좀도둑
// 은신: 보는 쪽이 늘 이쪽이었다 — 여기서는 저쪽이 먼저 본다
// ==========================================

// ── 암살자 (assassin) · 무력 ──
kJob('assassin', 'A', [

{ at:'A', t:'복도 — 등 뒤의 높이',
  x:`등에 무게 없는 것이 얹힌다. 시선이다.<br><br>
    암살자는 그 무게를 안다. 늘 주는 쪽이었다. 남의 등에, 남의 목덜미에.<br>
    받는 쪽이 되면 처음 알게 되는 것이 있다. 시선은 따뜻하다. 숨처럼.<br><br>
    일행은 모른다. 다섯이 다 앞만 보고 걷는다. 시선은 이쪽 하나에게만 얹혀 있다.`,
  o:[
    { l:'① 돌아보지 않고 시선이 얹힌 높이를 잰다.', k:'hide', dc:22, wake:1,
      ok:`걸음을 늦췄다. 어깨를 조금씩 낮췄다. 시선이 따라 내려온다. 목덜미, 견갑골, 허리.<br><br>허리 높이에서 시선이 멈췄다. 더 내려오지 않는다. 그 높이에 눈이 있다. 아이 키다.<br>복도 모퉁이에서 갑자기 옆으로 비켜섰다. 시선이 허공에 남는다. 한참 머물다 흩어졌다.<br><br>보는 눈의 높이를 등으로 재는 법. 늘 남의 목을 노리던 손이 제 등에도 눈을 하나 달았다.`,
      ng:`어깨를 낮추는데 시선이 같이 내려오지 않는다. 대신 다가온다.<br><br>목덜미에 숨이 닿는다. 따뜻하다. 아주 가깝다. 발소리는 한 번도 안 났다.<br>돌아보지 않았다. 돌아보면 끝이라는 걸 몸이 안다. 다음 불빛까지 그 숨을 업고 걸었다. 목덜미 살갗이 그 자리만 젖었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-24 } },
    { l:'② 무력을 실어 뒤로 한 번만 벤다.', k:'break', dc:23, cost:{ might:28 },
      ok:`칼을 거꾸로 쥐고 몸을 돌리지 않은 채 뒤로 그었다. 한 번.<br><br>무언가 베였다. 천이다. 젖은 천. 칼끝에 실 한 가닥이 감겨 나왔다.<br>시선이 등에서 떨어졌다. 뒤에서 아주 작게, 아픈 소리가 아니라 놀란 소리가 났다.<br><br>실을 떼어 버렸다. 실은 바닥에 떨어져서도 이쪽 발 쪽으로 조금 기어 왔다.`,
      ng:`그었다. 칼이 허공을 갔다. 아무것도 없다.<br><br>그런데 시선은 그대로다. 오히려 웃는다. 등으로 그게 느껴진다.<br>칼을 휘두른 쪽 팔꿈치를 무엇이 잡았다. 작은 손. 아주 세게. 뼈가 울렸다. 놓고 나서도 팔꿈치가 펴지지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 일행 맨 뒤로 가 시선을 혼자 받는다.', k:'steady', dc:22,
      ok:`손짓으로 일행을 앞세우고 맨 뒤에 섰다. 등이 이제 복도 전체를 향한다.<br><br>시선이 얹힌다. 무겁다. 하나가 아니다. 셋쯤.<br>버티며 걸었다. 앞 사람들 목덜미에는 아무것도 안 얹혔다. 이쪽이 다 받았다.<br><br>복도를 빠져나오자 등이 축축했다. 땀이 아니다. 숨 자국이다.`,
      ng:`맨 뒤에 서자 시선이 셋이 됐다. 그리고 다섯.<br><br>등이 무거워 허리가 굽는다. 걸음이 늦어진다. 일행과 사이가 벌어진다. 벌어진 사이로 무언가 들어온다.<br>일행이 돌아와 팔을 잡아끌 때까지 무릎이 펴지지 않았다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A1', t:'방청석 — 박수 사이',
  x:`방청석 계단을 내려가야 무대 옆 문이 나온다.<br><br>
    빈 의자들이 줄지어 있다. 스피커에서 박수가 난다. 녹음이다. 박수가 날 때마다 의자 방석이 하나씩 눌린다. 아무도 안 앉았는데.<br>
    박수가 멎으면 눌린 방석들이 이쪽을 향해 조금 돈다.<br><br>
    이쪽은 생각한다. 큰 소리는 덮개다. 박수만큼 큰 덮개는 없다.<br>
    맨 앞줄에 바람잡이가 서 있다. 줄무늬 옷. 등이 이쪽이다. 두 팔을 들고 박수를 이끈다.`,
  o:[
    { l:'① 박수가 날 때만 한 칸씩 내려간다.', k:'hide', dc:22, wake:1,
      ok:`짝짝짝. 한 칸. 멈춤. 짝짝짝짝. 두 칸. 멈춤.<br><br>박수는 고르지 않다. 바람잡이의 팔이 오르는 걸 보고 미리 알았다. 팔이 오르기 직전에 발을 들었다.<br>무대 옆 문까지 열두 칸. 박수가 멎었을 때 이쪽은 한 번도 계단 위에 서 있지 않았다.<br><br>소리를 기다리지 않고 소리를 만드는 팔을 보는 것. 덮개가 오기 전에 덮개 밑에 들어가 있는 법을 알았다.`,
      ng:`세 칸째에 박수가 예정보다 일찍 멎었다.<br><br>발이 허공에 떠 있다. 내려놓았다. 툭. 방청석 전체에서 방석이 한꺼번에 이쪽으로 돈다.<br>바람잡이가 돌아보지 않고 말한다. 우리 친구, 벌써 나오고 싶구나. 박수가 다시 났다. 이쪽 쪽에서만 더 크게. 귀에서 피가 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 바람잡이 등 뒤로 다가가 목을 노린다.', k:'hide', dc:23,
      doom:{ title:'바람잡이', what:'방청석 손에서 손으로 무대 위로 실려 갑니다', dc:18, sec:50,
        text:`박수에 섞여 맨 앞줄까지 내려갔다. 줄무늬 등이 한 걸음 앞이다.<br><br>칼을 쥐었다. 목을 봤다. 목이 없다. 줄무늬 옷깃 위로 바로 웃는 얼굴이 얹혀 있다. 등 쪽으로. 처음부터 이쪽을 보고 있었다.<br>바람잡이가 손가락으로 이쪽을 가리킨다. 박수가 터진다.<br><br>뒤에서 손이 이쪽을 들어 올린다. 방석에서 올라온 손들이다. 등과 허리와 발목을 받쳐 앞으로 넘긴다. 손에서 손으로. 무대 쪽으로.`,
        dieText:`박수가 오래 났다. 앞으로 나와 볼 친구가 생겼다.<br><br>방청석 맨 앞줄에 방석이 하나 더 눌렸다.<br>바람잡이가 팔을 든다. 그 자리 방석이 가장 먼저 박수를 친다.` },
      ok:`박수에 섞여 내려가다 다섯 칸 앞에서 멈췄다. 줄무늬 옷깃 위에 목이 없다. 얼굴이 뒤를 향해 얹혀 있다.<br><br>이쪽을 처음부터 보고 있었다. 다만 웃는 얼굴은 눈을 깜빡이지 않는다. 깜빡이지 않는 눈은 움직이는 것만 본다.<br>박수가 멎을 때까지 멈춰 있었다. 그리고 의자 사이로 기어서 문까지 갔다. 얼굴은 끝까지 빈 계단을 보고 웃었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'기숙사 — 침대 밑의 점호',
  x:`밤 아홉 시가 가깝다. 복도 끝에서 열쇠 소리가 난다. 찰랑, 찰랑. 사감이다.<br><br>
    호실 안에 침대가 열둘. 침대 밑은 물이다. 무릎 깊이로 고였다.<br>
    숨을 데는 침대 밑뿐이다. 물속에.<br><br>
    이쪽은 숨는 걸 안다. 다만 숨는 자리는 늘 이쪽이 골랐다. 여기는 자리가 이쪽을 골랐다.`,
  o:[
    { l:'① 침대 밑 물에 엎드려 숨을 늦춘다.', k:'hide', dc:22,
      ok:`물에 엎드렸다. 얼굴만 침대 틀 밑 틈에 댔다. 숨을 한 번에 아주 조금씩.<br><br>문이 열린다. 검은 치맛단이 물 위로 미끄러진다. 열쇠 소리. 침대마다 멈춘다. 이름을 부른다. 대답이 침대 밑 물에서 올라온다. 옆 침대 밑에서, 그 옆에서.<br>이쪽 침대 앞에서 치맛단이 멈췄다. 이름은 안 불렀다. 이 침대는 원래 비어 있는 침대다.<br><br>치맛단이 지나갔다. 그제야 옆 침대 밑을 봤다. 물속에 머리카락이 떠 있었다.`,
      ng:`숨을 늦추는데 물이 귀로 들어온다. 차다. 기침이 목까지 왔다.<br><br>삼켰다. 대신 물을 한 모금 마셨다. 비리다.<br>열쇠 소리가 이쪽 침대 앞에서 오래 멈춰 있었다. 이름은 안 불렸다. 그 대신 침대 틀을 손톱으로 두 번 두드렸다. 다 안다는 듯이. 몸이 한참 떨렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 문 뒤에 서서 사감이 들어오면 등 뒤로 빠진다.', k:'evade', dc:23,
      ok:`문 경첩 쪽 벽에 등을 붙였다. 문이 열리면 문짝이 이쪽을 가린다.<br><br>문이 열렸다. 문짝이 코앞에 섰다. 문짝 너머로 열쇠 소리가 침대 쪽으로 간다.<br>문짝 가장자리를 돌아 복도로 나왔다. 물을 안 흔들려고 발을 들지 않고 밀었다.<br><br>복도에 나와 돌아봤다. 문짝 안쪽 면에 손톱 자국이 줄지어 있다. 이쪽 키 높이에. 여기 숨었던 것이 이쪽이 처음이 아니다.`,
      ng:`문이 열리지 않았다. 사감은 문을 안 연다. 문을 지나 들어온다.<br><br>검은 치맛단이 문짝을 그대로 통과해 이쪽 무릎에 닿았다. 젖은 천이 다리를 감았다가 풀린다.<br>사감은 침대 쪽으로 갔다. 이쪽 다리에 물이 얼음처럼 남았다. 한참 걷지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 숨 여섯',
  x:`일행이 잠들었다. 다섯이다. 암살자는 깨어 있다.<br><br>
    잠든 사람의 숨은 길다. 이쪽은 숨으로 사람을 센다. 문 너머에서도, 어둠 속에서도. 그게 일이다.<br>
    세었다. 하나, 둘, 셋, 넷, 다섯. 그리고 여섯.<br><br>
    여섯째 숨은 다른 숨보다 조금 얕다. 깬 사람의 숨이다. 깬 척을 안 하는 숨.`,
  o:[
    { l:'① 숨을 하나씩 짚어 남는 숨의 자리를 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`눈을 감고 숨마다 방향을 쟀다. 왼쪽 벽 둘, 가운데 둘, 문가 하나.<br><br>여섯째는 방 한가운데다. 일행들 사이. 아무도 안 누운 자리다. 바닥에 먼지가 사람 모양으로 비어 있다.<br>칼끝으로 그 자리 바닥을 톡 쳤다. 숨이 멎었다. 먼지 위에 아이 손자국 하나가 찍히고, 그 뒤로는 숨이 다섯이었다.<br><br>숨을 세던 귀가 숨의 자리를 그린다. 어둠 속에 사람을 하나씩 세워 놓는 법을 알았다.`,
      ng:`짚다가 숨이 헷갈렸다. 여섯째가 움직인다. 이 사람 숨에서 저 사람 숨으로.<br><br>누구 숨인지 모르게 됐다. 일행 다섯 숨이 다 조금씩 얕아진다.<br>날이 샐 때까지 일행 얼굴을 하나씩 들여다봤다. 아무도 눈을 뜨지 않았다. 아무도 깊이 자지도 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 남는 숨 쪽에 칼을 눕혀 두고 지킨다.', k:'steady', dc:22,
      ok:`칼을 뽑아 일행과 어둠 사이에 눕혀 놓았다. 날이 위로.<br><br>밤새 칼날이 몇 번 운다. 아주 작게. 무언가 넘어오려다 날에 닿고 물러나는 소리.<br>아침에 보니 날 위에 물기가 줄지어 있다. 작은 발바닥 모양이다. 넘어오지는 않았다.`,
      ng:`칼을 눕혔다. 숨이 칼 쪽으로 다가와 칼 위에 멈췄다.<br><br>칼이 무거워진다. 무엇이 날 위에 앉아 있다. 날을 들어 올리려 했다. 꿈쩍 않는다.<br>새벽까지 칼을 붙잡고 있었다. 손바닥에 날 자국이 깊게 남았다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A1', t:'의상실 — 숨 쉬는 탈',
  x:`옷걸이 레일에 인형탈이 줄줄이 걸려 있다. 노란 해, 갈색 털, 파란 새.<br><br>
    탈은 속이 비어야 한다. 하나가 조금 부풀었다 줄어든다. 숨이다.<br>
    이쪽은 사람 몸의 자리를 안다. 탈을 씌워도 목은 목 자리에 있다.<br><br>
    부푼 것은 갈색 털 탈이다. 등 지퍼가 반쯤 열렸다. 안쪽이 어둡다.`,
  o:[
    { l:'① 무력을 실어 털 너머 목 자리를 한 번에 찌른다.', k:'break', dc:23, cost:{ might:30 },
      ok:`탈 머리 밑, 어깨 솔기 사이. 사람이 들었다면 목이 오는 자리다. 칼을 밀어 넣었다.<br><br>털 속에서 무언가 딱딱한 데 닿았다. 칼이 반쯤 들어가 멈췄다. 숨이 끊겼다. 탈이 천천히 줄어든다. 바람 빠지듯.<br>칼을 뺐다. 날에 솜이 묻어 나왔다. 솜 사이에 머리카락이 섞였다.<br><br>찌른 것이 사람이었는지는 모른다. 다시 부풀지 않았다. 그거면 됐다.`,
      ng:`목 자리를 찔렀다. 칼이 그냥 들어간다. 솜뿐이다.<br><br>숨은 다른 데서 났다. 이쪽 뒤에 걸린 탈에서.<br>뒤의 털 팔이 이쪽 어깨를 감는다. 안에 팔이 들었다. 좀약 냄새에 숨이 막힌다. 칼자루로 수없이 친 뒤에야 풀렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 탈 사이에 서서 같이 걸린 척한다.', k:'hide', dc:23,
      doom:{ title:'옷걸이 줄', what:'열린 지퍼 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`탈 둘 사이에 섰다. 팔을 늘어뜨리고 숨을 늦췄다. 걸린 옷처럼.<br><br>레일이 움직인다. 덜컹. 탈들이 한 칸씩 간다. 이쪽 어깨도 같이 밀린다. 옆 탈의 털이 볼에 닿는다.<br>지퍼 열리는 소리가 난다. 등 뒤에서. 이쪽 등에 닿은 탈의 지퍼다.<br><br>안쪽에서 팔이 나와 이쪽 허리를 안는다. 뒤로 당긴다. 털 속 어둠으로. 지퍼가 다시 올라간다. 이쪽 목덜미까지.`,
        dieText:`레일이 끝까지 갔다가 멈췄다.<br><br>갈색 털 탈이 둘이 됐다. 하나는 조금 크다. 지퍼가 끝까지 닫혔다.<br>둘 다 숨을 쉰다. 같은 박자로.` },
      ok:`서기 전에 레일 끝을 봤다. 레일이 벽 속으로 들어간다. 걸린 것은 다 저리로 간다.<br><br>탈 사이에 서지 않고 탈 뒤 벽에 붙었다. 레일이 덜컹 움직였다. 탈들이 줄지어 지나간다. 지퍼마다 안쪽이 이쪽을 향해 벌어졌다 닫힌다.<br>마지막 탈이 지나가자 문이 보였다. 걸린 것들이 가려 두던 문이다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 탈마다 지퍼 안쪽 이름표를 읽는다.', k:'gaze', dc:22,
      ok:`지퍼를 손가락 하나로 벌리고 안쪽 목깃을 봤다. 이름표가 있다. 입는 사람 이름.<br><br>노란 해 탈에는 이름이 셋. 줄이 그어진 둘, 안 그어진 하나. 갈색 털 탈에는 하나. 그 하나 위에 새 이름표가 덧대어져 있다. 비어 있다.<br>빈 이름표를 뜯어냈다. 숨 쉬던 탈이 조용해졌다. 입을 사람이 없으면 숨도 없다.`,
      ng:`이름표를 읽는데 글씨가 바뀐다. 읽는 동안 한 자씩.<br><br>이쪽 이름이 된다. 손을 빼려는데 지퍼가 손등을 물었다. 이빨이 손등 살을 집는다.<br>억지로 뺐다. 손등에 지퍼 자국이 줄지어 났다. 피가 났다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'교실동 — 물결의 주인',
  x:`교실동 복도는 허리까지 물이다. 물이 탁하다. 발이 안 보인다.<br><br>
    걸으면 물결이 퍼진다. 물결은 이쪽이 어디 있는지 사방에 알린다.<br>
    앞쪽 물에서도 물결이 온다. 이쪽 것이 아니다. 작은 물결이 여럿. 다가온다.<br><br>
    암살자는 발소리를 지우는 법을 안다. 물결을 지우는 법은 아직 모른다.`,
  o:[
    { l:'① 남의 물결이 올 때만 그 골에 발을 넣는다.', k:'hide', dc:22, wake:1,
      ok:`앞에서 오는 물결을 봤다. 마루와 골이 있다. 골이 지나갈 때 발을 밀어 넣었다.<br><br>이쪽 물결이 남의 물결 골에 묻힌다. 밖에서 보면 물결은 하나다. 저쪽 것.<br>한 걸음, 기다리고, 한 걸음. 작은 물결들이 이쪽 허리 옆을 지나간다. 그 밑에서 무언가 무릎을 스쳤다. 머리카락이다. 멈추지 않고 갔다.<br><br>소리 뒤에 숨던 발이 물결 뒤에도 숨는다. 덮개는 소리만이 아니었다. 움직이는 것은 다 덮개가 된다.`,
      ng:`골을 기다리다 마루에 발을 넣었다. 물결이 둘로 갈라진다. 이쪽 모양으로.<br><br>작은 물결들이 일제히 멈춘다. 그리고 갈라진 쪽으로 온다.<br>물 밑에서 손가락이 종아리를 하나씩 짚고 올라온다. 무릎, 허벅지. 뿌리치며 교실 문으로 뛰어들었다. 다리에 손가락 자국이 줄지어 시퍼렇다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 무력을 실어 다가오는 물결 한가운데를 찌른다.', k:'break', dc:23, cost:{ might:28 },
      ok:`물결이 모이는 한가운데를 노렸다. 칼을 물에 꽂아 내리찍었다.<br><br>무언가 맞았다. 무르다. 칼끝에서 물결이 한꺼번에 흩어진다. 작은 것들이 사방으로 도망친다. 물 밑을 기어서.<br>칼을 뺐다. 끝에 명찰이 꿰여 나왔다. 젖어서 이름이 다 번졌다.<br><br>명찰은 물에 다시 놓아 주었다. 물이 그걸 받아 바로 가라앉혔다.`,
      ng:`찔렀다. 칼이 물만 갈랐다. 물결은 이미 이쪽 등 뒤에 와 있었다.<br><br>허리를 감는 팔이 여럿이다. 작고 차갑다. 아래로 당긴다. 가슴까지 잠겼다.<br>칼을 거꾸로 쥐고 아래를 수없이 그었다. 풀렸을 때는 턱까지 물이었다. 물을 많이 먹었다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'문 — 일행의 목소리',
  x:`문 저쪽에서 이쪽 이름을 부른다. 일행 목소리다. 다급하다.<br><br>
    여기, 여기 좀 열어 줘.<br>
    돌아보니 일행은 다섯 다 이쪽에 있다. 다들 얼굴이 하얗다. 부르는 목소리의 주인도 이쪽 옆에 서 있다. 입을 다문 채.<br><br>
    이쪽은 이름이 끈이라는 걸 안다. 부르는 쪽이 끈을 쥐고 있다. 대답하면 당겨진다.`,
  o:[
    { l:'① 대답하지 않고 문 경첩 옆에 붙는다.', k:'hide', dc:22,
      ok:`입을 다물었다. 일행에게도 손가락을 입술에 대 보였다. 문 경첩 쪽 벽에 몸을 붙였다.<br><br>목소리가 계속 부른다. 이쪽 이름을. 점점 낮게. 점점 가깝게. 문틈에 입을 댄 소리다.<br>오래 지나 목소리가 멈췄다. 문 밑 틈으로 젖은 손가락 끝이 나와 바닥을 더듬는다. 이쪽 신발 한 뼘 앞까지.<br><br>손가락이 거둬졌다. 문 저쪽에서 다른 이름을 부르기 시작했다. 멀어지면서.`,
      ng:`붙어 있는데 목소리가 바뀐다. 이번엔 이쪽 목소리다.<br><br>이쪽 목소리가 일행 이름을 하나씩 부른다. 일행 하나가 대답할 뻔했다. 입을 막아 주느라 이쪽이 벽에서 떨어졌다.<br>문이 쿵 하고 이쪽 쪽으로 휜다. 문짝에 부딪혀 쓰러졌다. 목소리는 밤새 이쪽 목소리였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 문을 열자마자 벤다.', k:'break', dc:23,
      doom:{ title:'열어 줘', what:'문 너머 어둠으로 끌려갑니다', dc:18, sec:50,
        text:`빗장을 빼고 문을 확 당기며 칼을 그었다.<br><br>칼이 무엇에 닿기 전에 손목이 잡혔다. 문틈에서 나온 손이다. 일행의 손이다. 손등의 흉터까지 같다.<br>여기, 여기. 목소리가 이번엔 바로 귓가에서 난다.<br><br>손이 당긴다. 문틈으로. 문틈은 사람 하나 들어갈 너비가 아니다. 그래도 어깨가 들어간다.`,
        dieText:`문이 닫혔다. 빗장이 저절로 걸렸다.<br><br>문 저쪽에서 이름을 부른다. 다급하다. 여기, 여기 좀 열어 줘.<br>이번엔 이쪽 목소리다. 일행 중 아무도 대답하지 않았다.` },
      ok:`빗장을 빼고 문을 반만 당겼다. 칼은 문틈 높이가 아니라 바닥 쪽으로 그었다.<br><br>문틈으로 나오던 손이 손목에서 베였다. 손이 문틈에 떨어져 바닥을 기어 다닌다. 손등에 일행과 같은 흉터가 있다.<br>문을 도로 밀어 닫았다. 문 저쪽에서 목소리가 일행 목소리로 울었다. 그러다 이쪽 목소리로 웃었다.<br><br>바닥의 손은 문틈으로 기어 돌아갔다. 손가락 넷으로.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'계단 — 반 박자',
  x:`계단을 오른다. 아래에서 발소리가 따라온다.<br><br>
    이쪽이 디디면 반 박자 늦게 디딘다. 이쪽이 서면 반 박자 늦게 선다.<br>
    처음엔 메아리인 줄 알았다. 메아리는 점점 작아진다. 이건 점점 커진다. 가까워진다.<br><br>
    이쪽은 남의 걸음에 박자를 맞춰 숨는다. 지금 저쪽이 이쪽에게 그걸 하고 있다.`,
  o:[
    { l:'① 서는 척하고 반 박자 안에 한 칸 더 오른다.', k:'sense', dc:22, wake:1,
      ok:`멈췄다. 그리고 반 박자가 오기 전에 한 칸을 더 디뎠다. 소리 없이.<br><br>아래 발소리가 멈췄다. 반 박자 늦게. 그런데 이쪽은 한 칸 위다. 저쪽은 이쪽이 아까 서 있던 자리를 기준으로 섰다.<br>그 반 박자로 거리를 쟀다. 열한 칸 아래. 난간 쪽.<br><br>따라오는 것을 박자로 속이는 법. 맞추는 쪽은 언제나 맞춰지는 쪽보다 반 박자 뒤에 산다. 그 반 박자가 이쪽 것이 됐다.`,
      ng:`한 칸 더 디뎠다. 아래 발소리가 반 박자 늦게 따라오지 않았다. 같이 디뎠다.<br><br>이제 늦지 않는다. 이쪽 발과 같은 때 난다. 그리고 다음에는 반 박자 먼저 났다.<br>이쪽이 따라가는 쪽이 됐다. 꼭대기까지 오르는 동안 발이 제 뜻대로 안 디뎌졌다. 무릎이 다 까졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 계단참 모퉁이에 숨어 올라오기를 기다린다.', k:'hide', dc:23,
      ok:`계단참 모퉁이 그늘에 몸을 접었다. 숨을 끊었다.<br><br>발소리가 올라온다. 반 박자 늦는 걸음. 기다리는 이쪽에게 박자를 맞추려다 박자를 잃었다. 걸음이 비틀거린다.<br>모퉁이 앞에서 멈췄다. 아무것도 안 보인다. 발소리만 있다. 몸이 없는 걸음이다.<br><br>그 걸음은 거기서 오래 서 있다 아래로 내려갔다. 계단마다 젖은 발자국이 거꾸로 남았다.`,
      ng:`숨어 기다리는데 발소리가 모퉁이 직전에서 멈췄다. 한참.<br><br>그리고 이쪽 숨을 맞추기 시작했다. 이쪽이 들이쉬면 반 박자 늦게 들이쉰다.<br>숨을 참았다. 저쪽도 참았다. 먼저 터진 건 이쪽이었다. 가슴이 찢어질 듯 아팠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-24 } }
  ] },

{ at:'A1', t:'스튜디오 — 빨간 불',
  x:`카메라 세 대가 스튜디오 바닥에 서 있다. 아무도 안 잡았는데 고개를 돌린다.<br><br>
    카메라 머리에 빨간 불이 있다. 켜진 카메라가 지금 찍는 카메라다.<br>
    빨간 불이 이쪽을 향한 채 켜지면 저 너머 모니터마다 이쪽 얼굴이 뜬다. 생방송이다.<br><br>
    암살자는 찍히는 일이 없었다. 보는 눈이 하나도 없는 데서 일했다. 여기는 눈이 셋이다. 셋 다 기계다.`,
  o:[
    { l:'① 빨간 불이 다른 카메라로 넘어가는 틈만 걷는다.', k:'hide', dc:22, wake:1,
      ok:`불이 넘어가는 박자를 셌다. 하나에서 둘로, 둘에서 셋으로. 넘어가는 사이 아주 짧게 셋 다 꺼진다.<br><br>그 짧은 데마다 두 걸음. 빨간 불이 켜지면 섰다. 켜진 카메라의 등 뒤에만 섰다.<br>스튜디오를 가로질렀다. 모니터 어디에도 이쪽이 안 떴다.<br><br>눈의 등 뒤를 고르는 버릇이 기계 눈 앞에서도 통한다. 보는 것이 무엇이든 등은 있다. 어디가 등인지 먼저 찾는 눈이 하나 늘었다.`,
      ng:`셋째 틈이 없었다. 둘째에서 셋째로 넘어갈 때 불이 꺼지지 않고 동시에 켜졌다.<br><br>셋 다 이쪽이다. 머리 위 스피커에서 박수가 터진다. 오늘의 친구.<br>모니터마다 이쪽 얼굴이 크게 떴다. 웃고 있다. 이쪽은 안 웃었다. 한참 동안 얼굴 근육이 제 마음대로 당겼다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 무력을 실어 카메라 선을 한 번에 끊는다.', k:'break', dc:23, cost:{ might:28 },
      ok:`카메라 뒤로 바닥에 굵은 선이 기어 나간다. 칼을 세워 내리쳤다. 한 번에.<br><br>빨간 불이 꺼졌다. 카메라 고개가 툭 꺾였다. 잘린 선 끝에서 물이 흐른다. 전기가 아니라 물이 흐르던 선이다.<br>남은 둘이 한꺼번에 꺼진 쪽으로 고개를 돌렸다. 그사이 반대편으로 지났다.`,
      ng:`선을 내리쳤다. 칼이 선에 박혀 안 빠진다. 선이 움찔하며 감긴다. 칼째 손목을.<br><br>카메라가 이쪽을 향한다. 빨간 불이 켜진다. 선이 당긴다. 카메라 앞으로.<br>손목을 비틀어 뺐다. 살갗이 같이 벗겨졌다. 칼은 겨우 건졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'③ 카메라 뒤에 누가 서 있는지 본다.', k:'gaze', dc:22,
      ok:`카메라 뒤 손잡이를 봤다. 손잡이 고무가 닳아 있다. 손 모양으로. 지금은 아무도 안 잡았다.<br><br>닳은 자국이 셋 다 낮다. 아이 키다. 카메라를 돌리는 건 키 작은 손이다.<br>셋 다 고개가 아래로 기울어지지 않는다. 낮은 데는 못 찍는다. 바닥에 배를 대고 기어서 지났다.`,
      ng:`손잡이를 보는데 고무가 움찔한다. 쥐는 모양으로 눌린다.<br><br>카메라가 이쪽을 향해 돈다. 손잡이를 쥔 무엇이 바로 이쪽 앞에 있다. 안 보인다. 숨만 있다.<br>코앞에서 빨간 불이 켜졌다. 눈이 한참 하얗게 탔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'수영장 — 다이빙대 위',
  x:`수영장 물은 검다. 레인 줄이 수면에 떠 있다.<br><br>
    다이빙대 꼭대기에 아이 하나가 서 있다. 수영모. 물 쪽을 내려다본다. 등이 이쪽이다.<br>
    젖지 않았다. 이 학교에서 처음 본 마른 것이다.<br><br>
    다이빙대 사다리가 이쪽 발밑에서 시작한다. 등 뒤로 오르기 좋다. 이쪽에게 등은 언제나 길이다.`,
  o:[
    { l:'① 사다리를 소리 없이 올라 등 뒤에 선다.', k:'hide', dc:23,
      doom:{ title:'다이빙대', what:'검은 물속으로 함께 끌려 들어갑니다', dc:18, sec:50,
        text:`한 칸씩 올랐다. 쇠가 차다. 꼭대기에 닿았다. 등이 한 뼘 앞이다.<br><br>아이가 돌아보지 않고 말한다. 같이 뛰자. 셋 세면.<br>하나. 아이 손이 뒤로 와서 이쪽 손목을 잡는다. 마른 손이다. 아주 세다. 둘.<br><br>발판 끝으로 끌려 나간다. 아래 검은 물에 얼굴들이 떠올라 올려다본다. 다 수영모를 썼다. 셋.`,
        dieText:`물이 한 번 크게 튀었다. 그리고 잔잔해졌다.<br><br>다이빙대 꼭대기에 아이가 서 있다. 마른 채로. 물 쪽을 내려다본다.<br>그 옆에 하나가 더 서 있다. 젖은 채로. 둘 다 등이 이쪽이다.` },
      ok:`사다리 중간에서 멈췄다. 꼭대기 발판 틈으로 아이의 발이 보인다. 발끝이 발판 끝에 걸쳐져 있다. 물 쪽이 아니라 이쪽을 향해.<br><br>등이 이쪽이 아니었다. 발이 거꾸로다. 처음부터 사다리를 보고 서 있었다.<br>소리 없이 내려왔다. 내려와서 올려다보니 아이가 사다리 쪽으로 고개를 숙이고 있다. 웃고 있었다.<br><br>오르지 않은 사다리 칸마다 젖은 손자국이 위를 향해 찍혀 있었다. 먼저 오른 사람들 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 물에 비친 다이빙대로 그것의 자리를 잰다.', k:'gaze', dc:22,
      ok:`물가에 쪼그려 검은 수면을 봤다. 다이빙대가 비친다. 꼭대기의 아이도.<br><br>비친 아이는 수영모가 젖었다. 그리고 뒤를 보고 있다. 진짜는 물을 보는데.<br>둘 중 하나는 사다리를 지키는 것이다. 사다리를 안 쓰고 수영장 가장자리로 돌아갔다. 둘 다 끝까지 한 번도 움직이지 않았다.`,
      ng:`비친 아이를 오래 봤다. 비친 아이가 수면 안에서 고개를 든다. 이쪽을 본다.<br><br>수면이 이쪽 쪽으로 볼록하게 솟는다. 얼굴 모양으로.<br>물러서다 미끄러져 수영장 모서리에 정강이를 찧었다. 뼈가 울렸다. 수면은 한참 그 모양을 하고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'복도 — 쓰러지지 않는 것',
  x:`복도 한가운데 그것이 서 있다. 사람 키. 젖은 머리카락이 얼굴을 덮었다.<br><br>
    이쪽은 등 뒤로 돌아가 한 번 그었다. 정확했다. 목이 반쯤 열렸다.<br>
    그것은 쓰러지지 않았다. 고개가 열린 쪽으로 천천히 기운다. 그리고 웃는다. 열린 목으로.<br><br>
    한 번이면 된다. 두 번이면 실패다. 칼이 손 안에서 두 번째를 원한다.`,
  o:[
    { l:'① 칼을 거두고 그것 옆을 지나간다.', k:'steady', dc:22, wake:1,
      ok:`칼을 칼집에 넣었다. 손이 떨린다. 두 번째를 원하는 손이다. 주먹을 쥐어 눌렀다.<br><br>그것 옆을 지났다. 어깨가 거의 닿았다. 그것은 웃는 채로 이쪽 쪽으로 고개를 돌렸다. 따라오지는 않았다. 두 번째를 기다리는 얼굴이었다.<br>복도 끝에서 돌아보니 그것의 발밑에 칼이 여러 자루 꽂혀 있다. 먼저 온 사람들 칼이다. 다 두 번째 칼이다.<br><br>베지 않을 것을 아는 손. 한 번이 끝이 아닐 때 칼을 거두는 법. 칼을 쥔 손보다 칼을 놓는 손이 더 무겁다는 걸 알았다.`,
      ng:`칼을 거두는 사이 손이 먼저 움직였다. 두 번째가 나갔다.<br><br>칼이 그것의 몸에 들어가 안 나온다. 그것이 칼을 몸에 품은 채 이쪽 손을 잡는다. 칼자루째.<br>당긴다. 열린 목이 가까워진다. 속이 비었다. 칼자루를 놓고서야 떨어졌다. 칼은 그것 몸에 남았다. 손목에 젖은 손자국이 깊다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-24 } },
    { l:'② 열린 목 안을 들여다본다.', k:'gaze', dc:23,
      ok:`그것이 고개를 기울인 쪽으로 같이 몸을 기울였다. 열린 목 안이 보인다.<br><br>안에 물이 차 있다. 물 위에 작은 얼굴이 떠서 이쪽을 올려다본다. 웃는 것은 바깥 얼굴이 아니라 안의 얼굴이다.<br>바깥은 옷이다. 칼이 안 통하는 게 당연하다. 일행에게 손짓했다. 닿지 말고 지나가라고.`,
      ng:`들여다보는데 안의 물이 차오른다. 열린 목 가장자리까지. 넘친다.<br><br>넘친 물이 이쪽 발등에 쏟아진다. 차다. 발이 바닥에 얼어붙는다.<br>그것이 웃는 채로 기다린다. 일행이 바닥 물을 깨서 발을 빼낼 때까지 한참 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A1', t:'분장실 — 거울 속 등',
  x:`분장실 거울에 전구가 둘러 박혔다. 다 켜져 있다. 뜨겁다.<br><br>
    거울에 이쪽이 비친다. 앞모습이 아니라 뒷모습이다. 이쪽 등과 뒤통수.<br>
    그 등 뒤에 무언가 서 있다. 거울 속에서만. 노란 손이 이쪽 어깨 위로 천천히 올라온다.<br><br>
    암살자는 남의 등을 보는 사람이다. 제 등을 보는 일은 없었다. 처음 보는 제 등이 생각보다 비어 있다.`,
  o:[
    { l:'① 거울을 보며 거울 속 등 뒤를 친다.', k:'break', dc:23,
      ok:`거울 속 노란 손이 어깨에 닿기 직전. 거울을 보면서 팔꿈치를 뒤로 쳤다. 거울 속 이쪽이 그 동작을 한다.<br><br>거울 속에서 노란 것이 휘청 물러났다. 진짜 등 뒤에는 아무것도 없다. 그런데 팔꿈치 끝이 무르다. 무엇에 닿았다.<br>거울 속 그것이 웃는 입을 손으로 가린다. 그리고 거울 가장자리 밖으로 나갔다.<br><br>팔꿈치에 노란 실밥 하나가 붙어 있었다.`,
      ng:`쳤다. 거울 속 이쪽은 안 쳤다. 가만히 서 있다.<br><br>거울 속 이쪽이 이쪽을 보고 웃는다. 뒷모습인 채로. 뒤통수가 웃는다.<br>노란 손이 거울 속 이쪽 어깨를 잡는다. 진짜 어깨가 그 모양으로 눌렸다. 전구가 하나씩 터졌다. 파편이 얼굴에 박혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 전구를 하나씩 빼 거울을 어둡게 한다.', k:'hide', dc:22,
      ok:`뜨거운 전구를 소매로 감싸 하나씩 돌려 뺐다. 하나 뺄 때마다 거울이 조금씩 어두워진다.<br><br>어두워질수록 거울 속 그것이 흐려진다. 노란 손이 어깨 위에서 멈춘다. 더듬는다. 이쪽이 안 보이는 것이다.<br>마지막 전구를 뺐다. 거울이 까맣다. 까만 거울 앞을 기어서 지났다.<br><br>소매가 탔다. 손가락 끝에 물집이 잡혔다. 그 값이면 싸다.`,
      ng:`전구를 빼는데 빠진 자리마다 불이 다시 켜진다. 빼낸 전구는 손에서 아직 뜨겁다.<br><br>거울이 점점 더 밝아진다. 거울 속 그것이 또렷해진다. 얼굴이 보인다. 동그란 노란 해. 웃는 입이 거울을 가로지른다.<br>눈을 감고 뒷걸음질 쳤다. 손바닥이 다 데었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A2', t:'식당 — 배식 줄',
  x:`식당 물은 가슴까지 온다. 배식대 앞에 줄이 서 있다. 보이지 않는 줄이다.<br><br>
    물이 거기서만 일정한 간격으로 무겁다. 줄 맨 끝에 빈자리가 하나 있다. 물이 거기만 가볍다.<br>
    배식대 뒤에서 국자 소리가 난다. 탁, 탁. 한 사람에 한 번.<br><br>
    줄은 앞으로 간다. 빈자리가 이쪽 쪽으로 온다. 이쪽은 줄에 서 본 적이 없다.`,
  o:[
    { l:'① 빈자리가 오기 전에 기둥 뒤로 빠진다.', k:'hide', dc:22,
      ok:`기둥 뒤에 몸을 붙였다. 물속에서 발을 끌지 않고 들어서 옮겼다.<br><br>빈자리가 기둥 옆까지 왔다. 멈췄다. 한참 거기 있다. 물이 기둥 둘레를 돌며 이쪽을 찾는다.<br>국자 소리가 났다. 탁. 빈자리가 다시 앞으로 갔다. 이쪽 없이.<br><br>기둥에 손자국이 있다. 이쪽 손 옆에, 같은 높이로. 여기 숨은 게 이쪽이 처음이 아니다.`,
      ng:`빠지는데 물이 무겁다. 옷이 물을 먹어 느리다.<br><br>빈자리가 이쪽 등에 닿았다. 등 뒤가 가벼워진다. 이쪽을 끼운 줄이 앞으로 간다. 발이 저절로 따라간다.<br>국자 소리 셋 앞에서 겨우 기둥을 붙잡았다. 손톱이 기둥에 박혀 두 개가 깨졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 무력을 실어 배식대 뒤를 먼저 친다.', k:'break', dc:23, cost:{ might:30 },
      ok:`물을 가르며 배식대를 넘었다. 국자를 든 팔이 있다. 팔만. 하얀 소매.<br><br>팔꿈치를 한 번에 쳤다. 국자가 떨어진다. 팔이 물속으로 미끄러져 사라진다.<br>국자 소리가 멎자 줄이 흩어졌다. 무겁던 물이 한꺼번에 풀린다. 배식대 밑 찬장에 봉한 소금 단지가 하나 있었다.`,
      ng:`쳤다. 팔이 국자를 놓지 않는다. 국자가 이쪽 손등을 친다. 탁.<br><br>한 사람에 한 번. 이쪽 몫이다. 손등이 국자 모양으로 하얗게 언다.<br>줄 전체가 이쪽을 향해 무거워진다. 배식대를 넘어 도망치는 동안 물이 등을 몇 번이고 밀었다.`,
      win:{ exp:20, dream:2, item:'소금 덩이' }, lose:{ hp:-32, mind:-14 } },
    { l:'③ 줄이 지나간 배식대에서 남은 것을 집는다.', k:'luck', dc:22,
      ok:`줄이 다 지나갈 때까지 기다렸다. 배식대 위 쟁반이 하나 남았다. 마른 쟁반이다.<br><br>위에 말린 고기 한 줄. 비닐에 싸였다. 비닐 위에 이름표가 붙어 있다. 결석.<br>결석한 아이 몫이다. 고맙게 챙겼다. 쟁반 밑에 연필 글씨가 있다. 나 대신 먹어.`,
      ng:`쟁반을 집는데 쟁반 위에 물이 차오른다. 쟁반 높이를 넘어서.<br><br>물 위로 손이 하나 올라와 쟁반 가장자리를 잡는다. 이쪽 몫이 아니라는 듯이.<br>놓았다. 손이 쟁반째 물 밑으로 가져갔다. 놓는 사이 손가락이 물에 얼어 붙었다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A', t:'어둠 — 먼저 본 쪽',
  x:`불이 꺼졌다. 완전한 어둠이다.<br><br>
    어둠에서는 먼저 본 쪽이 산다. 이쪽은 늘 먼저 봤다.<br>
    이번에는 늦었다. 저쪽 눈이 이미 이쪽에 와 있다. 눈이 둘. 어둠 속에서 하얗게. 깜빡이지 않는다.<br><br>
    그리고 또 둘. 또 둘. 사방에서.`,
  o:[
    { l:'① 눈을 감고 이쪽도 안 보는 쪽이 된다.', k:'hide', dc:22, wake:1,
      ok:`눈을 감았다. 보는 것을 그만뒀다. 보려는 마음까지.<br><br>보는 마음은 빛처럼 샌다. 저쪽은 그걸 보고 있었다. 이쪽 눈이 아니라 이쪽이 보려는 것을.<br>감고 섰다. 오래. 사방의 눈이 하나씩 흩어진다. 볼 것이 없어진 것이다.<br><br>먼저 보지 않아도 사는 법. 보지 않으면 보이지도 않는 어둠이 있다. 칼이 처음으로 눈을 버리는 법을 배웠다.`,
      ng:`눈을 감았는데 눈꺼풀 안쪽에 하얀 눈이 있다. 바깥과 같은 자리에.<br><br>감아도 보인다. 보이니까 보는 마음이 안 멎는다.<br>눈꺼풀 안쪽 눈들이 가까워진다. 일행이 불을 다시 켤 때까지 그 눈이 이쪽 눈 바로 앞에 있었다. 불빛에 눈이 한참 아팠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 무력을 실어 가장 가까운 눈 사이를 찌른다.', k:'break', dc:23, cost:{ might:28 },
      ok:`가장 가까운 두 눈 사이로 곧장 칼을 넣었다.<br><br>닿았다. 단단하다. 유리다. 쨍. 눈 둘이 깨져 떨어진다. 단추 눈이다.<br>나머지 눈들이 일제히 감겼다. 어둠이 그냥 어둠이 됐다.<br><br>바닥에 단추 두 개가 굴러 있다. 실이 달려 있다. 실 끝이 젖었다.`,
      ng:`찔렀다. 눈 사이가 비었다. 칼이 깊이 들어간다. 손목까지. 팔꿈치까지.<br><br>안이 따뜻하다. 무언가 칼을 문다. 당긴다.<br>칼을 놓고 팔을 뺐다. 팔에 침 같은 것이 묻었다. 눈들이 다 웃는 모양으로 휘었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 대답하는 숫돌',
  x:`쉬는 동안 칼을 간다. 물을 묻히고 날을 눕혀 소리 없이.<br><br>
    한 번 밀었다. 어디선가 같은 소리가 난다. 스윽. 한 번 더 밀었다. 스윽.<br>
    벽 너머다. 누가 같은 박자로 칼을 간다.<br><br>
    암살자는 칼 가는 소리로 칼을 안다. 저쪽 칼은 길다. 그리고 아주 오래 갈았다.`,
  o:[
    { l:'① 박자를 바꿔 저쪽이 따라오는지 본다.', k:'sense', dc:22,
      ok:`세 번 빨리, 한 번 느리게 밀었다.<br><br>벽 너머도 세 번 빨리, 한 번 느리게. 따라 한다. 따라 하는 쪽은 이쪽을 듣고 있다.<br>숫돌을 내려놓았다. 벽 너머도 멈췄다. 그리고 다시 혼자 갈기 시작했다. 아주 빠르게.<br><br>그 소리가 멎을 때까지 일행을 깨워 자리를 옮겼다. 옮긴 자리까지는 소리가 오지 않았다.`,
      ng:`박자를 바꾸자 벽 너머가 따라오지 않는다. 제 박자로 간다. 점점 빠르게.<br><br>그 소리가 귀에 박힌다. 이쪽 손이 저쪽 박자를 따라간다. 날이 숫돌에서 미끄러져 손가락을 갈랐다.<br>피가 숫돌에 번졌다. 벽 너머 소리가 그 순간 멎었다. 냄새를 맡는 것처럼.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 소리 없이 끝까지 갈아 날을 어둠에 맞춘다.', k:'hide', dc:23,
      ok:`저쪽 박자 사이사이에 갈았다. 저쪽 소리가 이쪽 소리를 덮는다.<br><br>다 갈고 보니 날이 안 보인다. 어둠과 같은 색이다.<br>벽 너머 소리가 문득 멎었다. 이쪽 소리를 찾는 것이다. 이쪽에는 이제 소리가 없다.<br><br>한참 뒤 벽 너머에서 칼을 칼집에 넣는 소리가 났다. 찾기를 그만둔 소리다.`,
      ng:`사이사이에 갈다가 한 번 겹쳤다. 두 소리가 하나로 났다.<br><br>벽 너머가 웃는다. 숨으로. 그리고 칼 가는 소리가 벽을 타고 이쪽 등 뒤로 옮겨 왔다.<br>돌아보지 않았다. 등 뒤에서 아주 가깝게, 날 하나가 어깨 위 공기를 갈랐다. 머리카락이 한 줌 잘려 떨어졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다 밑',
  x:`알록달록한 공이 방 하나를 가득 채웠다. 무릎 높이, 허리 높이. 가운데는 더 깊다.<br><br>
    건너편에 문이 있다. 공을 건너야 한다.<br>
    공 하나가 혼자 굴러 떨어진다. 밑에서 무언가 지나간 것이다. 공 표면이 길게 출렁인다. 뱀이 지나가는 모양으로.<br><br>
    이쪽은 밑에서 노리는 것을 안다. 이쪽도 늘 밑에서, 그늘에서 노렸다. 위에 서는 쪽이 처음이다.`,
  o:[
    { l:'① 공 위에 배를 대고 무게를 나눠 기어 간다.', k:'hide', dc:22,
      ok:`엎드렸다. 팔다리를 넓게 벌려 공 위에 몸을 펼쳤다. 무게가 흩어지면 공이 안 꺼진다.<br><br>천천히 밀었다. 출렁임이 지나갈 때마다 멈췄다. 밑의 것은 무게를 찾는다. 펼친 몸은 무게가 없다.<br>한가운데에서 바로 밑으로 무언가 지나갔다. 공 너머로 등이 느껴진다. 길다. 끝이 없다.<br><br>문 앞에 닿았다. 돌아보니 이쪽이 기어 온 자리에 공이 한 줄 꺼져 있다. 밑에서 따라오며 맛을 본 자리다.`,
      ng:`팔 하나가 공 사이로 빠졌다. 무게가 한 점에 몰렸다.<br><br>밑에서 손이 그 팔을 잡았다. 작은 손이 여럿. 손가락마다 차다.<br>뿌리치는 사이 공이 얼굴 위로 쏟아진다. 숨이 막혔다. 문까지 공을 헤치고 나왔을 때 팔에 손자국이 수십 개였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 출렁임이 오는 길에 칼을 꽂아 기다린다.', k:'break', dc:23,
      doom:{ title:'공 바다', what:'공 바다 밑으로 끌려 가라앉습니다', dc:18, sec:50,
        text:`칼을 거꾸로 쥐고 공 사이로 꽂았다. 출렁임이 다가온다. 칼끝 쪽으로.<br><br>칼이 무엇에 박혔다. 단단하다. 그리고 칼을 문 채 돈다. 칼자루가 손에서 비틀린다.<br>놓으려는데 손이 칼자루에 붙었다. 밑에서 당긴다. 팔꿈치까지 공 속이다. 어깨까지.<br><br>공 사이로 끌려 들어간다. 위에서 공이 덮인다. 알록달록한 빛이 하나씩 가려진다. 밑은 생각보다 깊다.`,
        dieText:`공 바다 표면이 잔잔해졌다.<br><br>한참 뒤 공 하나가 혼자 굴러 떨어졌다. 그리고 또 하나.<br>출렁임이 둘이 됐다. 나란히, 같은 박자로 지나간다.` },
      ok:`칼을 꽂았다가 출렁임이 칼끝에 닿기 직전에 뽑았다. 꽂힌 자리를 비워 두었다.<br><br>밑의 것이 빈자리로 고개를 내민다. 공이 갈라지고 머리가 보인다. 아이 수영모 같은 매끈한 머리. 눈이 없다.<br>그 정수리에 칼을 한 번 내렸다. 머리가 공 속으로 가라앉았다. 출렁임이 멎었다.<br><br>공 위를 걸어서 건넜다. 한 번도 꺼지지 않았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'강당 — 관람석 맨 뒷줄',
  x:`강당 관람석에 줄줄이 앉아 있다. 물에 잠긴 머리들. 다 무대를 본다. 미동이 없다.<br><br>
    무대 옆 문으로 가려면 관람석 맨 뒷줄 뒤를 지나야 한다.<br>
    맨 뒷줄 가운데 자리가 하나 비었다. 의자에 명찰이 놓였다. 젖지 않은 새 명찰.<br><br>
    이쪽은 줄지어 앉은 등 뒤를 지나는 일이 익숙하다. 이렇게 많은 등은 처음이다.`,
  o:[
    { l:'① 맨 뒷줄 등받이 아래로 낮게 지난다.', k:'hide', dc:22, wake:1,
      ok:`등받이 높이보다 낮게 몸을 접었다. 물이 턱에 찬다. 숨을 코로만 아주 조금.<br><br>지나가는 동안 등받이 너머로 머리들이 하나씩 아주 조금 기운다. 뒤를 보려는 게 아니다. 소리를 듣는 것이다.<br>이쪽은 소리를 안 냈다. 물이 흐르는 쪽으로만 움직였다. 이쪽 움직임이 물결 속에 녹았다.<br><br>문 앞에서 돌아보니 기운 머리들이 다시 무대로 돌아간다. 수백의 등 뒤를 하나의 그늘로 지나는 법. 숨을 줄이는 게 아니라 이쪽을 줄이는 법을 알았다.`,
      ng:`가운데 빈자리 뒤를 지날 때 의자가 덜컹 내려왔다. 접이 의자다. 앉으라는 듯이.<br><br>의자 끝이 이쪽 무릎 뒤를 친다. 무릎이 꺾인다. 앉혀지기 직전에 등받이를 붙잡고 버텼다.<br>양옆 머리들이 이쪽으로 돌아본다. 물속에서 하얀 얼굴. 무릎 뒤가 멍으로 시퍼렇다. 그 시선들이 오래 등에 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-26 } },
    { l:'② 빈자리의 명찰을 슬쩍 집어 간다.', k:'luck', dc:23,
      ok:`지나가면서 손만 뻗어 명찰을 집었다. 소매에 넣었다.<br><br>새 명찰에 이름이 수놓여 있다. 반은 비었다. 이름은 이쪽 이름이다. 한 땀이 덜 놓였다.<br>명찰이 없어진 의자가 천천히 접혀 올라간다. 자리가 사라졌다. 사라진 자리는 아무도 못 채운다.<br><br>나중에 꺼내 보니 바늘이 아직 꽂혀 있었다. 바늘은 빼서 물에 버렸다.`,
      ng:`집는데 명찰이 의자에서 안 떨어진다. 실이 의자 밑으로 이어져 있다.<br><br>당기자 실이 끌려 나온다. 실 끝이 이쪽 소매 실밥에 꿰여 있다. 언제 꿰였는지 모른다.<br>칼로 실을 끊었다. 끊는 순간 양옆 머리들이 동시에 이쪽을 봤다. 문까지 뛰는 동안 물이 다리를 감았다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 무력을 실어 난간을 넘어 무대 옆으로 뛰어내린다.', k:'evade', dc:23, cost:{ might:30 },
      ok:`관람석 옆 난간을 짚고 다리에 힘을 다 몰아 한 번에 넘었다.<br><br>무대 옆 물에 내렸다. 물이 크게 튄다. 관람석 머리들이 한꺼번에 이쪽을 돈다.<br>그러나 이쪽은 이미 무대 옆 문 안이다. 문을 닫자 문에 수백 개의 손바닥이 한꺼번에 닿는 소리가 났다. 한 번. 그뿐이었다.`,
      ng:`넘다가 발이 난간에 걸렸다. 힘이 엉뚱한 데로 빠졌다.<br><br>관람석 맨 끝 줄 위로 떨어졌다. 머리들 위로. 차고 미끄럽다. 손들이 이쪽 옷을 잡는다. 앉히려는 것이다.<br>찢고 굴러 무대 옆까지 갔다. 옷이 반쯤 남았다. 어깨에 손톱 자국이 깊다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-16 } }
  ] },

{ at:'A', t:'복도 — 끌린 자국',
  x:`바닥에 자국이 길게 나 있다. 두 줄. 신발 뒤축이 끌린 자국이다.<br><br>
    자국 양옆으로 손톱 자국이 있다. 바닥을 긁으며 버틴 자국. 열 개가 다 있다. 중간부터 여덟, 다섯, 둘.<br>
    자국은 복도 끝 문틈으로 들어간다. 문틈은 손바닥 너비다.<br><br>
    암살자는 끌려간 자리를 많이 봤다. 대개 이쪽이 끈 자리였다.`,
  o:[
    { l:'① 자국 옆 그늘에서 끄는 것이 다시 오기를 기다린다.', k:'hide', dc:23,
      doom:{ title:'두 줄', what:'문틈 너머로 발목을 잡혀 끌려갑니다', dc:18, sec:50,
        text:`자국 옆 벽 그늘에 몸을 접었다. 끄는 것은 다시 온다. 끄는 것은 늘 다시 온다.<br><br>문틈에서 소리가 난다. 바닥을 쓰는 소리. 손 하나가 나와 바닥을 더듬는다. 자국을 따라. 자국 끝, 손톱이 둘 남은 자리까지 와서 멈춘다.<br>손이 옆으로 더듬는다. 그늘 쪽으로. 발목에 닿는다.<br><br>쥔다. 당긴다. 몸이 그늘에서 쓸려 나간다. 손톱을 세워 바닥을 긁었다. 열 개.`,
        dieText:`복도 바닥에 자국이 네 줄이 됐다.<br><br>새 줄 양옆으로 손톱 자국. 열 개, 여덟, 다섯, 둘.<br>문틈은 여전히 손바닥 너비다.` },
      ok:`그늘에 들기 전에 자국 끝을 봤다. 손톱 자국이 둘 남은 자리. 그 옆 벽이 바로 이쪽이 숨으려던 그늘이다.<br><br>끌려간 사람도 여기 숨었다가 잡혔다. 그늘이 아니라 미끼였다.<br>그늘 반대편, 불빛 아래 섰다. 문틈에서 손이 나와 그늘을 더듬었다. 빈 그늘을 오래 쓸었다. 돌아갔다.<br><br>그늘이 늘 이쪽 편이 아니라는 걸 오래 잊고 살았다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 자국을 거슬러 처음 끌린 자리를 찾는다.', k:'sense', dc:22,
      ok:`자국을 거꾸로 따라갔다. 모퉁이를 둘 돌았다. 자국이 시작된 데에 서랍장이 하나 있다.<br><br>서랍이 반쯤 열렸다. 안에 맑은 물이 담긴 병이 하나 있다. 끌려간 사람이 이걸 꺼내려다 잡혔다.<br>병을 꺼냈다. 서랍 안쪽을 보지 않고. 손이 서랍 깊은 데까지 가지 않게 손끝으로만.<br><br>서랍이 저 혼자 닫혔다. 안쪽에서.`,
      ng:`거슬러 가는데 자국이 점점 새것이 된다. 손톱 자국이 아직 젖었다.<br><br>모퉁이를 도니 자국이 이쪽 발밑에서 시작한다. 이쪽 신발 뒤축 모양이다.<br>뒷걸음질 쳤다. 다리에 힘이 빠져 주저앉았다. 일으켜 세워 줄 때까지 손이 바닥을 긁고 있었다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'문 — 열쇠 구멍의 눈',
  x:`문에 열쇠 구멍이 있다. 구멍 안이 하얗다.<br><br>
    눈이다. 저쪽에서 열쇠 구멍에 눈을 대고 있다. 깜빡인다. 이쪽을 본다.<br>
    문은 잠겼다. 열쇠는 없다. 저쪽이 열쇠를 가졌을 것이다.<br><br>
    이쪽은 구멍으로 보는 자가 어떻게 보는지 안다. 구멍으로 보면 옆이 안 보인다.`,
  o:[
    { l:'① 칼끝을 구멍 옆 문틈에 대고 기다린다.', k:'break', dc:23,
      ok:`구멍 바로 옆, 경첩 반대쪽 틈에 칼끝을 댔다. 구멍으로는 안 보이는 자리.<br><br>눈이 이쪽을 찾느라 구멍 안에서 돈다. 못 찾자 구멍에서 눈이 떨어진다. 손잡이가 돈다. 문이 열린다. 저쪽이 내다본다.<br>그 순간 한 번. 칼끝이 문틈으로 들어갔다. 짧게.<br><br>문 너머에 아무도 없다. 칼끝에 하얀 실밥 하나가 묻었다. 손잡이 안쪽에 열쇠가 꽂혀 있다.`,
      ng:`기다리는데 눈이 구멍에서 떨어지지 않는다. 대신 구멍이 넓어진다. 눈이 커진다.<br><br>문 전체가 눈이 될 것 같다. 칼끝이 떨린다.<br>눈을 피해 돌아섰다. 등에 시선이 문짝 크기로 얹혔다. 다음 방까지 등을 펴지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 구멍 앞에서 숨을 끊고 눈이 떠나기를 기다린다.', k:'steady', dc:22,
      ok:`문 앞에 섰다. 숨을 끊었다. 눈은 움직이는 것을 본다. 이쪽은 안 움직였다.<br><br>오래. 눈이 깜빡인다. 한 번, 두 번. 지루한 눈이 된다.<br>구멍에서 눈이 떨어졌다. 발소리가 멀어진다. 그제야 숨을 쉬었다.<br><br>문 밑 틈으로 작은 열쇠가 밀려 들어와 있었다. 들어와도 된다는 뜻인지, 들어오라는 뜻인지는 모른다.`,
      ng:`숨을 끊었는데 눈이 떠나지 않는다. 깜빡이지도 않는다.<br><br>숨이 다했다. 터졌다. 눈이 웃는 모양으로 휜다.<br>구멍으로 바람이 들어온다. 차다. 얼굴에. 숨을 대신 쉬어 주려는 것처럼. 기침이 한참 멎지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'깊은 곳 — 한 번',
  x:`넓은 방이다. 가운데에 그것이 앉아 있다. 크다. 등이 이쪽이다.<br><br>
    그것이 이름을 부른다. 일행 이름을 하나씩. 다정하게. 부를 때마다 일행 하나가 한 발짝 그쪽으로 간다.<br>
    이쪽 이름은 아직 안 불렸다. 맨 마지막일 것이다.<br><br>
    한 번이면 된다. 두 번이면 실패다. 이번에는 두 번이 없다.`,
  o:[
    { l:'① 이름 부르는 숨 사이로 들어가 한 번에 끝낸다.', k:'hide', dc:24, wake:1,
      ok:`이름 하나를 부르고 다음 이름을 부르기 전, 그것은 숨을 들이쉰다. 그 숨은 길다.<br><br>그 숨 동안 다섯 걸음을 갔다. 다음 숨에 다섯. 등 뒤에 닿았다. 그것의 목은 이름이 나오는 데에 있다. 소리를 따라가면 된다.<br>다음 이름이 나오기 직전에 한 번 그었다. 이름이 반만 나오고 끊겼다.<br><br>그것이 앞으로 무너졌다. 일행이 걸음을 멈췄다. 한 번. 그것으로 끝났다. 소리가 나오는 자리를 베는 손. 부르는 것의 목을 찾는 법이 칼끝에 새로 앉았다.`,
      ng:`숨 사이로 들어갔다. 마지막 걸음에서 그것이 숨을 안 들이쉬고 바로 불렀다. 이쪽 이름을.<br><br>발이 멈췄다. 대답이 목까지 올라왔다. 이를 악물고 삼켰다.<br>그것이 돌아본다. 커다란 웃는 얼굴. 팔이 이쪽을 쳐서 벽까지 날렸다. 일행이 끌어당겨 줄 때까지 일어나지 못했다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26 } },
    { l:'② 무력을 다 쏟아 정면으로 들어간다.', k:'break', dc:24, cost:{ might:34 },
      ok:`숨기지 않았다. 그것 앞으로 곧장 갔다. 무력을 다리와 팔에 다 실었다.<br><br>그것이 이쪽 이름을 부르기 전에 세 번을 쳤다. 셋째에 그것이 입을 다물었다. 다문 입에서 물이 흘렀다.<br>그것이 앉은 채 무너졌다. 숨는 칼도 정면에서 끝까지 갈 줄 안다.`,
      ng:`두 번째에 그것이 이쪽 이름을 불렀다. 팔에서 힘이 빠졌다.<br><br>세 번째는 나가지 않았다. 그것의 손이 이쪽을 감싸 쥐었다. 크고 차다.<br>일행이 칼로 그 손가락을 다 쳐 낸 뒤에야 바닥에 떨어졌다. 갈비가 몇 대 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-38, mind:-18 } },
    { l:'③ 이름 불린 일행을 하나씩 붙잡아 뒤로 돌린다.', k:'bond', dc:23,
      ok:`이름이 불릴 때마다 그 사람 손목을 잡고 뒤로 돌렸다. 입을 막았다. 대답하지 말라고.<br><br>다섯을 다 돌렸다. 그것은 계속 불렀다. 대답이 없자 이름을 다시 처음부터 부른다.<br>그사이 다들 문을 빠져나왔다. 문을 닫자 저쪽에서 이쪽 이름이 처음으로 불렸다. 아무도 대답하지 않았다.`,
      ng:`넷까지 돌렸다. 다섯째가 대답했다. 아주 작게. 네.<br><br>그 사람이 그쪽으로 간다. 붙잡았다. 그 사람 몸이 물처럼 무거워진다. 둘이 같이 끌려갔다.<br>일행 셋이 매달려 겨우 문까지 끌어냈다. 팔이 빠질 뻔했다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-30, spirit:-22 } }
  ] }

]);

// ── 자객 (killer) · 내공 ──
kJob('killer', 'A', [

{ at:'A', t:'복도 — 남의 살기',
  x:`자객은 살기를 거두고 걷는다. 늘 그렇게 걷는다.<br><br>
    이 복도에서 살기를 다 거뒀다. 그런데 살기가 남는다. 이쪽 것이 아니다.<br>
    죽이고 싶어 하는 마음이 공기에 배어 있다. 차고 끈적하다. 오래 묵었다.<br><br>
    일행은 그냥 춥다고만 한다. 이쪽은 안다. 이건 추위가 아니다. 누가 이쪽을 고르고 있다.`,
  o:[
    { l:'① 남의 살기가 짙어지는 쪽을 짚어 간다.', k:'sense', dc:22, wake:1,
      ok:`살기에도 결이 있다. 짙은 데와 옅은 데. 제 살기를 다뤄 온 몸이 남의 것도 더듬는다.<br><br>짙은 쪽은 왼쪽 벽이다. 벽 너머에 서 있다. 벽에 귀를 대지 않았다. 대면 저쪽도 안다.<br>오른쪽 벽에 붙어 지났다. 살기가 벽을 따라 같이 왔다. 모퉁이에서 끊겼다. 벽이 끝나는 데서.<br><br>제 살기를 거두던 손이 남의 살기를 쥔다. 어디서 오는지, 어디서 끊기는지. 살기가 길이 됐다.`,
      ng:`짚어 가는데 살기가 갑자기 사방에서 짙어진다. 한 곳이 아니다. 복도 전체가 이쪽을 노린다.<br><br>어느 쪽으로도 못 간다. 섰다. 살기가 살갗에 들러붙는다. 바늘처럼.<br>일행이 등을 밀어 복도를 빠져나올 때까지 온몸에 소름이 가시지 않았다. 팔에 핏방울이 점점이 맺혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 내공으로 맥을 늦춰 죽은 것처럼 지난다.', k:'steady', dc:23, cost:{ qi:28 },
      ok:`단전에 기를 모아 심장을 눌렀다. 맥이 느려진다. 한 번 뛰고, 오래 쉬고, 한 번.<br><br>죽은 것에는 고를 것이 없다. 살기가 이쪽을 스치고 지나간다. 일행 쪽으로.<br>일행 앞에 섰다. 맥을 늦춘 채로. 살기가 일행 앞에서 죽은 몸 하나를 만나 멈췄다. 흩어졌다.<br><br>맥을 되돌리는 데 오래 걸렸다. 손끝이 한참 하얬다.`,
      ng:`맥을 누르는데 맥이 안 늦춰진다. 이쪽 맥이 아닌 맥이 하나 섞여 뛴다. 빠르게.<br><br>누가 이쪽 손목에 손가락을 대고 있다. 안 보인다. 맥을 재는 것이다. 살아 있는지.<br>뿌리쳤다. 손목에 차가운 손가락 셋 자국이 남았다. 맥이 그 자리에서 한참 따로 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 살기를 일부러 한 줄기 흘려 저쪽을 끌어낸다.', k:'hide', dc:23,
      ok:`거뒀던 살기를 실처럼 가늘게 풀었다. 복도 반대쪽으로.<br><br>남의 살기가 그 실을 문다. 따라간다. 반대쪽 어둠으로 무언가 미끄러져 간다.<br>실을 끊었다. 저쪽은 끊긴 끝에서 헤맨다. 일행을 데리고 반대로 지났다.`,
      ng:`살기를 풀자 저쪽이 실을 따라 오지 않는다. 실을 거슬러 온다. 이쪽으로.<br><br>실이 끊기지 않는다. 저쪽이 쥐고 있다. 당긴다. 가슴 한가운데가 앞으로 쏠린다.<br>넘어지듯 버텼다. 실이 끊겼을 때 가슴에 멍이 들어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 웃음 녹음',
  x:`스피커에서 웃음이 쏟아진다. 녹음된 웃음. 아이들 웃음.<br><br>
    웃음이 날 때마다 빈 방석들이 들썩인다. 같이 웃는 것이다.<br>
    맨 앞줄에 하나가 앉아 있다. 노란 해 얼굴 탈. 고개를 뒤로 돌려 방청석을 훑는다. 안 웃는 사람을 찾는다.<br><br>
    이쪽은 웃는 법을 잊었다. 웃으면 얼굴 근육이 살기를 흘리기 때문이다.`,
  o:[
    { l:'① 얼굴을 웃게 하고 살기는 그 밑에 묻는다.', k:'hide', dc:22, wake:1,
      ok:`입꼬리를 올렸다. 눈은 그대로 두면 안 된다. 눈 밑 살까지 올렸다. 웃는 얼굴이 된다.<br><br>살기는 얼굴에서 빠져 아랫배로 내려간다. 웃음과 살기는 같은 자리에 못 있다. 얼굴을 웃음에 내주면 살기는 깊은 데로 숨는다.<br>노란 얼굴이 이쪽을 훑고 지나갔다. 멈추지 않았다.<br><br>웃는 얼굴 밑에 칼을 묻는 법. 얼굴을 버려 살기를 감추는 길이 하나 더 생겼다. 볼이 한참 아팠다.`,
      ng:`웃었는데 눈이 안 웃었다. 노란 얼굴이 이쪽에서 멈춘다.<br><br>탈 머리가 갸웃한다. 그리고 손을 든다. 손가락이 이쪽을 가리킨다.<br>웃음 녹음이 끊기고 한 사람 웃음만 남는다. 이쪽 목에서 나는 웃음이다. 멈춰지지 않는다. 목이 쉬고 갈비뼈가 결렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 웃음 사이로 내려가 노란 얼굴의 혈을 짚는다.', k:'break', dc:23,
      doom:{ title:'안 웃는 친구', what:'노란 손에 손목을 잡혀 무대로 끌려 나갑니다', dc:18, sec:50,
        text:`웃음이 쏟아질 때마다 한 줄씩 내려갔다. 맨 앞줄. 노란 탈 뒤통수가 손 닿는 데 있다.<br><br>목 뒤 혈 자리에 손가락 둘을 꽂았다. 탈 천이 손가락을 받는다. 그 밑에 아무것도 없다. 혈이 없다.<br>노란 얼굴이 고개를 거꾸로 돌려 이쪽을 본다. 웃는다. 우리 친구, 안 웃네.<br><br>노란 손이 이쪽 손목을 쥔다. 일어선다. 무대로 걷는다. 이쪽 발이 끌려간다. 방청석 전체에서 박수가 터진다.`,
        dieText:`무대에 조명이 켜졌다. 오늘의 친구 소개 시간이다.<br><br>방청석 맨 앞줄에 노란 탈이 다시 앉았다. 고개를 뒤로 돌려 훑는다.<br>그 옆자리 방석이 웃음에 맞춰 가장 크게 들썩인다.` },
      ok:`내려가다 노란 탈 목덜미를 봤다. 혈 자리가 있어야 할 데에 실밥이 있다. 꿰맨 자리다. 혈이 없는 몸이다.<br><br>짚지 않았다. 손가락을 거두고 그 등 뒤에 웃는 얼굴로 앉았다. 맨 앞줄 등 뒤는 훑는 눈이 안 닿는 자리다.<br>웃음이 끝날 때까지 앉아 있다가 무대 옆 문으로 빠졌다. 노란 얼굴은 끝까지 뒤만 봤다. 바로 등 뒤는 안 봤다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'양호실 — 커튼 안의 맥',
  x:`양호실 침대가 셋. 커튼이 쳐졌다. 물은 턱 밑까지 온다.<br><br>
    셋째 침대 커튼 아래로 손 하나가 늘어져 있다. 물 위에 떠서. 하얗고 작다.<br>
    자객은 맥을 짚을 줄 안다. 죽은 손인지 산 손인지는 손목 한 번이면 안다.<br><br>
    커튼 너머에서 아주 작게 숨소리가 난다. 물속인데.`,
  o:[
    { l:'① 커튼 아래 손목의 맥을 짚는다.', k:'gaze', dc:23,
      doom:{ title:'셋째 침대', what:'커튼 안 침대로 끌려 들어가 물 밑에 눕혀집니다', dc:18, sec:50,
        text:`손가락 둘을 손목에 댔다. 차다. 맥이 없다. 그런데 손가락 밑에서 무언가 뛴다. 한 번.<br><br>이쪽 맥이다. 이쪽 손가락 끝의 맥을 저 손목이 재고 있다. 거꾸로.<br>손이 뒤집힌다. 이쪽 손목을 쥔다. 맥 자리를 정확히. 꾹.<br><br>커튼이 열린다. 침대 위에 물이 고였다. 그 밑에 누운 것이 이쪽을 끌어당긴다. 자리가 하나 비어 있다. 이쪽 몸 크기다.`,
        dieText:`셋째 침대 커튼이 다시 쳐졌다.<br><br>커튼 아래로 손이 둘 늘어져 있다. 하나는 작고 하나는 크다.<br>둘 다 맥이 없다. 숨소리는 둘이다.` },
      ok:`짚기 전에 손톱을 봤다. 손톱 밑이 하얗다. 죽은 지 오래된 손이다. 그런데 손가락이 아주 조금씩 오므린다. 잡으려는 모양으로.<br><br>짚지 않았다. 대신 커튼 고리에서 실 한 가닥을 풀어 손목에 감았다. 맥 자리에.<br>손이 실을 쥐었다. 이쪽 손인 줄 알고. 꼭. 그사이 지나갔다.<br><br>문을 나서며 돌아봤다. 손이 실을 쥔 채 커튼 안으로 거둬졌다. 숨소리가 한 번 실망했다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 커튼에 기척을 안 남기고 침대 옆을 지난다.', k:'hide', dc:22,
      ok:`물속에서 발을 들지 않고 미끄러지듯 옮겼다. 물결이 커튼에 닿지 않게.<br><br>커튼은 물결에 흔들린다. 흔들리면 안쪽이 안다. 이쪽은 한 번도 흔들지 않았다.<br>약장 앞에 닿았다. 유리 안에 봉한 약초 꾸러미가 마른 채로 남아 있다. 챙겨서 나왔다.`,
      ng:`셋째 커튼 앞에서 물결이 커튼 밑자락을 건드렸다. 아주 조금.<br><br>늘어진 손이 물결 쪽으로 돈다. 손가락이 물을 더듬어 이쪽 무릎에 닿는다. 차다. 쥐려 한다.<br>몸을 비틀어 빠졌다. 무릎에 손가락 자국이 얼음처럼 박혔다. 한참 다리가 굽혀지지 않았다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 운기 중의 손',
  x:`가부좌를 틀었다. 흐트러진 기를 돌린다. 한 바퀴, 두 바퀴.<br><br>
    셋째 바퀴에 등에 손이 닿는다. 등 한가운데, 기가 지나는 자리.<br>
    손이 기를 보탠다. 차가운 기다. 이쪽 기와 섞여 같이 돈다.<br><br>
    일행은 다 잠들었다. 등 뒤에는 벽뿐이다. 운기 중에 기를 끊으면 내상을 입는다.`,
  o:[
    { l:'① 섞인 찬 기만 골라 등 밖으로 밀어낸다.', k:'steady', dc:23, cost:{ qi:30 },
      ok:`기를 끊지 않았다. 대신 돌리는 방향을 아주 조금 비틀었다. 이쪽 기는 따라 돈다. 찬 기는 못 따라온다.<br><br>찬 기가 한쪽으로 뭉친다. 등 한가운데로. 거기서 밖으로 밀었다. 손바닥 쪽으로.<br>등 뒤 손이 떨어졌다. 벽 쪽에서 아주 작게, 데인 듯한 소리가 났다.<br><br>눈을 떴다. 등 뒤 벽에 작은 손자국이 하얗게 서리 끼어 있다.`,
      ng:`비틀었는데 찬 기가 따라 비튼다. 이쪽 기보다 빠르다. 단전으로 내려간다.<br><br>배 속이 언다. 기가 거꾸로 돈다. 입에서 쇠맛이 났다. 피를 한 모금 토했다.<br>등 뒤 손은 그 뒤에도 한참 등에 얹혀 있었다. 다정하게.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 눈을 뜨지 않고 손의 주인을 맥으로 짚는다.', k:'sense', dc:22,
      ok:`등에 닿은 손바닥 너머로 맥을 찾았다. 없다. 손바닥 밑에서 무엇도 안 뛴다.<br><br>맥 없는 손이 기를 보탠다. 자기 기가 아니다. 남의 것을 모아 온 기다. 여럿의 기다.<br>그걸 안 순간 손이 떨어졌다. 들킨 걸 아는 것이다. 운기를 마저 돌렸다. 찬 기는 들어온 대로 빠져나갔다.`,
      ng:`맥을 찾다가 등 뒤 손이 하나가 아니라는 걸 알았다. 둘, 셋.<br><br>손마다 기를 보탠다. 찬 기가 이쪽 기를 밀어낸다. 이쪽 몸에 이쪽 기가 점점 줄어든다.<br>일행 하나가 깨서 어깨를 흔들 때까지 몸이 돌처럼 굳어 있었다. 손발이 다 얼었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A1', t:'분장실 — 가발 머리',
  x:`벽 선반에 마네킹 머리가 줄지어 놓였다. 머리마다 가발을 썼다. 단발, 땋은 머리, 곱슬.<br><br>
    가발 머리카락이 길어진다. 아주 천천히. 선반 끝에서 흘러내려 바닥을 기어 온다.<br>
    향하는 데는 이쪽 일행의 발목이다.<br><br>
    소매에 비수가 셋. 머리카락은 가늘다. 비수로는 안 끊긴다. 날이 아니라 기로 끊어야 한다.`,
  o:[
    { l:'① 내공을 비수에 실어 머리카락 줄기를 한 번에 끊는다.', k:'break', dc:23, cost:{ qi:28 },
      ok:`비수에 기를 얇게 입혔다. 날이 떨린다. 바닥을 기어 오는 머리카락 다발 밑으로 비수를 던졌다.<br><br>사악. 소리가 짧다. 다발이 한꺼번에 끊겼다. 끊긴 끝이 바닥에서 몸부림친다. 그러다 멎는다.<br>선반 위 마네킹들이 일제히 입을 벌린다. 소리는 없다.<br><br>비수를 주웠다. 날에 머리카락 한 올이 감겨 있다. 떼어 내도 다시 감긴다. 불에 태웠다.`,
      ng:`기를 실었는데 머리카락이 기를 먹는다. 비수가 다발 속에 박혀 멈췄다.<br><br>다발이 비수를 감싸 쥔다. 그리고 비수에 이어진 이쪽 기를 타고 손목까지 기어 온다.<br>손목을 감았다. 조인다. 칼로 끊어 내는 데 손목 살이 같이 쓸렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 숨을 끊고 마네킹 머리 사이에 서서 지나가길 기다린다.', k:'hide', dc:23,
      doom:{ title:'땋은 머리', what:'머리카락에 목이 감겨 선반 위로 끌려 올라갑니다', dc:18, sec:50,
        text:`선반 옆 벽에 붙었다. 숨을 끊었다. 머리카락이 발 옆을 지나간다.<br><br>목덜미가 간지럽다. 위다. 선반 위 땋은 머리 가발이 이쪽 쪽으로 기울어 있다. 땋은 끝이 목을 한 바퀴 감는다. 부드럽다.<br>숨을 끊은 채라 숨이 막히는 걸 늦게 알았다.<br><br>땋은 머리가 당긴다. 위로. 발끝이 바닥에서 뜬다. 선반에 빈자리가 하나 있다. 머리 하나 들어갈 자리.`,
        dieText:`선반에 마네킹 머리가 하나 늘었다.<br><br>가발이 아직 안 씌워졌다. 짧은 머리 그대로다.<br>바닥을 기던 머리카락들이 그 머리 쪽으로 천천히 올라간다. 씌워 주려는 것이다.` },
      ok:`벽에 붙기 전에 위를 봤다. 선반 위 땋은 머리가 이쪽 쪽으로 기울어 있다. 바닥 것은 몰이꾼이다. 위의 것이 사냥한다.<br><br>선반 밑으로 들어갔다. 위를 가린 데로. 땋은 끝이 허공을 몇 번 휘젓다가 거둬졌다.<br>머리카락이 다 지나갈 때까지 선반 밑에 있었다. 나와 보니 선반 밑판에 손톱 자국이 많다. 여기 숨었던 사람들은 위를 안 봤다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 가발 밑 마네킹 머리를 들여다본다.', k:'gaze', dc:22,
      ok:`가발 하나를 손끝으로 들췄다. 밑은 플라스틱 머리다. 정수리에 작은 구멍이 있다.<br><br>구멍에서 머리카락이 자라 나온다. 안에 무엇이 있다. 머리카락의 뿌리.<br>구멍마다 분첩을 눌러 막았다. 막힌 머리부터 가발이 늘어지며 멎었다. 일행 발목까지 와 있던 머리카락이 힘없이 풀렸다.`,
      ng:`들췄는데 밑이 플라스틱이 아니다. 따뜻하다. 정수리 가마가 있다.<br><br>마네킹 눈이 이쪽을 향해 굴렀다. 그려진 눈인데.<br>가발을 놓고 물러서다 선반을 쳤다. 머리들이 쏟아졌다. 하나가 발등 위에서 굴러 이쪽을 보고 멈췄다. 한참 다리가 안 움직였다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'교실 — 수업 중',
  x:`3학년 2반 문이 열려 있다. 물이 허리까지 찼다. 책상마다 머리가 하나씩 물 위로 나와 있다. 다 칠판을 본다.<br><br>
    교탁에 선생이 서 있다. 등이 이쪽이다. 분필로 칠판에 무언가 쓴다. 쓰고, 지우고, 다시 쓴다.<br>
    건너편 창으로 나가야 한다. 교탁 뒤를 지나는 길밖에 없다.<br><br>
    가르치는 것은 등으로도 교실을 본다. 딴짓하는 아이를. 딴 마음을 품은 아이를.`,
  o:[
    { l:'① 살기를 거두고 분필 소리에 걸음을 맞춰 교탁 뒤로 지난다.', k:'hide', dc:22, wake:1,
      ok:`분필이 칠판에 닿을 때 한 걸음. 뗄 때 멈춤. 지울 때 두 걸음.<br><br>살기는 다 거뒀다. 지나는 동안 마음속으로 칠판 글씨를 따라 읽었다. 딴 마음이 없는 아이처럼.<br>선생의 등 바로 뒤를 지났다. 분필 가루가 어깨에 떨어졌다. 선생은 돌아보지 않았다. 칠판에는 출석부의 이름들이 적혀 있었다.<br><br>창턱을 넘었다. 살기를 거두는 것만으로는 모자란 데가 있다. 마음을 다른 것으로 채워야 빈자리가 안 보인다. 거둔 자리를 채우는 법을 알았다.`,
      ng:`교탁 뒤에서 걸음이 분필보다 반 박 빨랐다. 분필이 멈췄다.<br><br>선생이 돌아보지 않고 분필로 칠판을 톡톡 친다. 책상마다 머리들이 이쪽으로 돈다. 물속에서 하얗게.<br>창까지 뛰었다. 물 밑에서 손들이 허리띠를 잡아끌었다. 창턱을 넘었을 때 허리에 손톱 자국이 줄줄이 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 내공으로 발밑 물을 눌러 물결 없이 걷는다.', k:'evade', dc:23, cost:{ qi:28 },
      ok:`기를 발바닥으로 내려 물에 얇게 폈다. 물이 발 둘레에서 단단해진다. 물결이 안 생긴다.<br><br>책상 사이를 지났다. 물 위 머리들이 한 번도 안 돌아봤다. 물이 흔들리지 않으면 아무 일도 안 일어난 것이다.<br>창턱에 닿았을 때 기가 다 빠졌다. 다리가 물에 빠지듯 무거웠다.`,
      ng:`기를 폈는데 물이 너무 단단해졌다. 발이 물 위로 떴다. 반 뼘.<br><br>떠 있는 아이는 수업 시간에 서 있는 아이다. 선생이 돌아본다. 얼굴이 젖은 머리카락에 다 덮였다. 손가락이 이쪽을 가리킨다.<br>기가 끊겨 물에 처박혔다. 물 밑에서 발목들을 붙잡는 손을 걷어차며 창까지 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'문 — 문고리의 맥',
  x:`문고리를 잡았다. 놋쇠다. 그런데 미지근하다.<br><br>
    손바닥 밑에서 무언가 뛴다. 한 번. 쉬고. 한 번.<br>
    맥이다. 문고리에 맥이 있다. 문짝 전체가 아주 조금 부풀었다 가라앉는다. 숨 쉬듯.<br><br>
    이쪽은 혈 자리를 안다. 사람 것도 짐승 것도. 문의 혈 자리는 처음이다.`,
  o:[
    { l:'① 맥이 지나는 길을 더듬어 문의 혈을 짚는다.', k:'gaze', dc:22, wake:1,
      ok:`손바닥을 문짝에 대고 맥을 따라갔다. 문고리에서 경첩 쪽으로. 위로.<br><br>경첩 위 한 뼘. 거기서 맥이 모인다. 손가락 둘로 꾹 눌렀다.<br>문의 숨이 멎었다. 문짝이 그냥 나무가 된다. 열었다. 저쪽은 그냥 방이다.<br><br>닫으며 보니 문짝 안쪽 면이 사람 등 모양으로 볼록하다. 문 안에 누가 기대 서 있다. 혈을 짚인 채 잠들었다. 산 것이면 혈이 있다. 혈이 있으면 짚을 수 있다. 짚을 수 있는 것이 하나 늘었다.`,
      ng:`맥을 따라가다 맥이 이쪽 손바닥으로 옮겨 왔다. 문 맥이 이쪽 맥을 덮는다.<br><br>손이 문짝에 붙는다. 문짝이 부풀 때 이쪽 가슴도 같이 부푼다. 숨이 문 박자로 쉬어진다.<br>일행이 손을 떼어 줬다. 손바닥 살갗이 문짝 결대로 갈라졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 손바닥에 기를 실어 문을 친다.', k:'break', dc:23,
      doom:{ title:'숨 쉬는 문', what:'문짝 속으로 팔부터 끌려 들어갑니다', dc:18, sec:50,
        text:`손바닥에 기를 모아 문짝 한가운데를 쳤다.<br><br>문이 쩍 갈라질 줄 알았다. 갈라지지 않았다. 손바닥이 문짝에 파묻힌다. 나무가 물처럼 받는다.<br>안쪽이 따뜻하다. 문 속에서 손이 이쪽 손을 잡는다. 깍지를 낀다.<br><br>당긴다. 팔꿈치까지 문 속이다. 어깨가 문짝에 붙는다. 얼굴이 나무 결에 닿는다. 결이 숨을 쉰다.`,
        dieText:`문짝이 조용히 가라앉았다.<br><br>문 한가운데 결이 조금 바뀌었다. 손바닥 모양으로 볼록하다.<br>문고리를 잡으면 맥이 두 번 뛴다. 한 번은 늦게.` },
      ok:`치기 직전에 손을 멈췄다. 손바닥 기를 거두고 손끝으로 문짝을 톡 쳤다. 아주 가볍게.<br><br>문짝이 그 자리에서 물결처럼 오목하게 들어갔다. 한 손 깊이. 세게 쳤으면 팔째 들어갔을 것이다.<br>문이 아니라 입이다. 경첩 쪽 벽을 따라 돌아 다른 길로 갔다. 등 뒤에서 문이 한 번 크게 숨을 내쉬었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'천장 — 거꾸로 선 것들',
  x:`천장에 무언가 매달려 있다. 여럿이다. 거꾸로. 발이 천장에 붙었다.<br><br>
    다 사람 모양이다. 팔이 아래로 늘어졌다. 손끝이 이쪽 머리 높이에 닿을락 말락.<br>
    눈은 감았다. 그런데 일행이 지나갈 때마다 손가락이 따뜻한 쪽으로 조금씩 움찔한다.<br><br>
    살아 있는 몸은 따뜻하다. 자객은 몸의 온기를 다룰 줄 안다. 어느 정도는.`,
  o:[
    { l:'① 맥을 늦춰 몸을 식히고 그 아래를 지난다.', k:'hide', dc:23, wake:1,
      ok:`기를 안으로 말아 넣었다. 피가 천천히 돈다. 살갗이 식는다. 손끝부터.<br><br>늘어진 손들 아래를 지났다. 손가락이 이쪽 쪽으로 움찔하지 않는다. 식은 것은 그것들한테 바닥과 같다.<br>마지막 손 아래를 지나 돌아봤다. 일행 쪽으로 손가락들이 다 휘어 있다. 하나씩 이쪽 길로 불러냈다. 식은 몸 뒤에 서게 했다.<br><br>살기만 거두는 게 아니라 몸의 온기까지 거두는 법. 살아 있다는 기척을 줄이는 길이 손에 잡혔다.`,
      ng:`식히다가 너무 식혔다. 다리가 굳는다. 걸음이 끌린다.<br><br>끌리는 소리에 천장 것 하나가 눈을 떴다. 거꾸로 선 얼굴이 이쪽 얼굴과 마주 본다. 코앞에서.<br>입이 벌어진다. 숨이 차다. 기를 풀고 뛰었다. 늘어진 손들이 뒷머리를 쓸고 지나갔다. 머리카락이 한 줌 빠졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 내공을 실어 비수 셋을 한 호흡에 던진다.', k:'break', dc:23, cost:{ qi:30 },
      ok:`비수 셋을 손가락 사이에 끼웠다. 기를 실어 손목만 썼다. 한 호흡.<br><br>셋이 천장에 박혔다. 매달린 것들 발목 바로 위. 붙은 자리를 끊었다. 셋이 떨어진다. 바닥에 닿기 전에 물이 되어 흩어졌다.<br>나머지가 눈을 떴다. 그러나 떨어진 것들 자리를 보느라 이쪽은 못 봤다. 그 틈에 지났다.`,
      ng:`던졌다. 둘이 박혔다. 셋째가 빗나가 천장을 긁었다. 쇳소리.<br><br>천장 것들이 한꺼번에 눈을 뜬다. 거꾸로 선 채 이쪽으로 걸어온다. 천장을 걸어서.<br>손들이 머리 위에서 쏟아진다. 엎드려 기어서 빠져나왔다. 등에 손톱 자국이 길게 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A1', t:'부조정실 — 맥박 선',
  x:`부조정실 벽이 모니터로 가득하다. 방마다 하나씩. 로비, 분장실, 계단.<br><br>
    한 화면에만 그림이 없다. 초록 선 하나가 가로질러 간다. 오르내린다. 맥박 선이다.<br>
    선 밑에 이름이 떠 있다. 이쪽 일행 이름이 차례로 바뀐다. 이름마다 선 모양이 다르다.<br><br>
    한 이름에서 선이 평평해지면 그 사람을 데리러 온다. 이쪽은 그걸 바로 알았다. 선 하나가 벌써 느려지고 있다.`,
  o:[
    { l:'① 느려지는 사람 손목에 손을 대 이쪽 맥을 겹친다.', k:'hide', dc:22, wake:1,
      ok:`느려지는 일행의 손목을 잡았다. 이쪽 맥을 손가락으로 흘려보냈다. 두 맥이 겹친다.<br><br>화면의 선이 다시 오른다. 한 사람 몫이 아니라 두 사람 몫으로 높게. 기계는 몫을 모른다. 높으면 산 것이다.<br>복도 쪽에서 오던 발소리가 문 앞에서 멈췄다가 돌아갔다.<br><br>남의 맥 밑에 제 맥을 숨기는 법. 살아 있음도 숨길 수 있고, 빌려줄 수도 있다. 손끝이 하나 더 할 줄 알게 됐다.`,
      ng:`맥을 겹쳤는데 화면의 선이 둘로 갈라진다. 이름도 둘로. 하나는 이쪽 이름이다.<br><br>이쪽 선이 느려진다. 남의 맥에 기를 너무 흘렸다. 화면에서 이쪽 선이 거의 평평하다.<br>문밖에서 발소리가 빨라진다. 손을 떼고 기를 되돌렸다. 선이 다시 튀었다. 가슴이 한참 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-20 } },
    { l:'② 비수로 그 화면을 깬다.', k:'break', dc:23,
      ok:`비수를 손목으로 던졌다. 맥박 화면 한가운데.<br><br>화면이 깨진다. 선이 끊긴다. 이름들이 흩어져 사라진다. 볼 수 없으면 셀 수도 없다.<br>다른 화면들이 일제히 깨진 화면 쪽을 비춘다. 방마다 카메라가 이쪽으로 돈 것이다. 그사이 부조정실을 빠져나왔다.`,
      ng:`화면이 깨졌다. 깨진 틈 사이로 선이 이어진다. 유리 조각 위로.<br><br>선이 평평해진다. 조각마다. 이쪽 이름이 조각마다 떴다.<br>복도에서 뛰어오는 발소리. 일행이 문을 막는 사이 겨우 반대쪽 문으로 나왔다. 손등이 유리에 길게 베였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } },
    { l:'③ 내공을 손끝에 모아 조정판 전원을 짚어 끊는다.', k:'fix', dc:23, cost:{ qi:28 },
      ok:`조정판 밑을 손바닥으로 훑었다. 전기가 흐르는 줄기가 느껴진다. 맥처럼.<br><br>제일 굵은 줄기가 모이는 자리에 손가락 둘을 꽂고 기를 밀었다. 화면이 하나씩 꺼진다. 맥박 화면이 마지막까지 버티다 꺼졌다.<br>어둠 속에서 조정판 위 빨간 불 하나만 남았다. 녹화 중. 그건 끄지 못했다.`,
      ng:`기를 밀었는데 전기가 거꾸로 올라왔다. 손끝에서 팔꿈치까지 저린다.<br><br>화면이 꺼지지 않고 더 밝아진다. 맥박 화면 선이 이쪽 맥 박자로 뛴다. 빠르게.<br>손을 떼었다. 손가락 끝이 까맣게 그을렸다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'체육관 — 대형 속의 빈칸',
  x:`체육관은 천장까지 물이다. 천장 아래 한 뼘만 공기가 남았다.<br><br>
    물 밑 바닥에 아이들이 줄 맞춰 서 있다. 체조 대형. 팔을 벌린 간격. 미동이 없다.<br>
    대형 한가운데 한 칸이 비었다. 그 칸만 물이 맑다.<br><br>
    반대편 벽에 문이 있다. 물 밑으로 대형을 가로질러야 한다. 이쪽은 숨을 오래 참는다. 오래가 얼마나 긴지는 해 봐야 안다.`,
  o:[
    { l:'① 내공으로 숨을 닫고 대형 가장자리를 돌아간다.', k:'steady', dc:23, cost:{ qi:30 },
      ok:`천장 공기에서 숨을 한 번 깊이 마시고 단전 아래로 닫았다. 거북 숨이다.<br><br>대형 가장자리로 내려가 벽을 짚고 돌았다. 서 있는 아이들 바로 옆을 지난다. 팔을 벌린 손끝이 이쪽 어깨에 닿을락 말락.<br>문에 닿았다. 문 너머 공기로 머리를 내밀었다. 한 번도 숨을 안 열었다. 가슴이 터질 듯했다. 그래도 열지 않았다.`,
      ng:`반쯤 돌았을 때 닫았던 숨이 새어 나왔다. 거품 하나.<br><br>거품이 대형 위로 오른다. 아이들 고개가 한꺼번에 거품을 따라 든다. 그리고 거품이 나온 데를 본다.<br>문까지 헤엄쳤다. 발목을 잡는 손을 걷어찼다. 물을 많이 먹었다. 문 너머에서 한참 토했다.`,
      win:{ exp:20, dream:2, hp:6 }, lose:{ hp:-34, mind:-16 } },
    { l:'② 빈칸을 지나 대형 한가운데로 곧장 건넌다.', k:'hide', dc:23,
      doom:{ title:'체조 대형', what:'대형 속 빈칸으로 끌려가 줄에 세워집니다', dc:18, sec:45,
        text:`빈칸으로 내려갔다. 물이 맑다. 맑은 데는 차가움이 덜하다. 지나가기 좋다.<br><br>빈칸 한가운데서 몸이 멈췄다. 양옆 아이의 손끝이 이쪽 손끝에 닿는다. 팔을 벌린 간격이다. 이쪽 팔도 벌어져 있다. 언제 벌렸는지 모른다.<br>발이 바닥에 닿는다. 선다. 줄을 맞춘다.<br><br>숨이 다한다. 위로 가야 한다. 양옆 손끝이 손가락을 걸어 놓지 않는다. 대형이 흐트러지면 안 된다.`,
        dieText:`체육관 물 밑에 대형이 다 찼다. 빈칸이 없다.<br><br>한가운데 하나만 키가 크다. 팔을 벌린 채 미동이 없다.<br>물이 더는 맑은 데가 없다.` },
      ok:`빈칸 바로 위에서 멈췄다. 내려가지 않았다. 빈칸 둘레 아이들의 손끝이 빈칸 쪽으로 조금씩 굽어 있다. 기다리는 손이다.<br><br>빈칸 위 천장 공기 쪽에 붙어 지났다. 위는 대형이 아니다. 줄 맞춰 선 것들은 위를 안 본다. 앞만 본다.<br>문 앞에서 숨을 터뜨렸다. 돌아보니 빈칸 둘레 손끝이 허공을 오므렸다 폈다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'복도 — 등을 내준 것',
  x:`복도 끝에 사람이 등을 보이고 서 있다. 무릎을 꿇었다. 고개를 숙였다.<br><br>
    목덜미가 드러났다. 혈 자리가 훤히 보인다. 한 수면 된다.<br>
    자객은 그런 등을 오래 찾아다녔다. 여기서는 등이 이쪽을 찾아왔다.<br><br>
    너무 좋은 자리다. 너무 좋은 자리는 누가 차려 놓은 자리다.`,
  o:[
    { l:'① 손을 내지 않고 등이 차려진 까닭을 본다.', k:'gaze', dc:22, wake:1,
      ok:`멈춰 섰다. 등을 봤다. 숨을 쉬지 않는다. 목덜미 혈 자리 둘레 살갗이 조금 반들반들하다. 여러 번 짚인 자리다.<br><br>바닥을 봤다. 등 뒤로 비수가 여럿 떨어져 있다. 녹슨 것, 새것. 그 옆에 손톱 자국이 문 쪽으로 끌려가 있다.<br>등은 미끼다. 짚으러 다가간 자를 무엇이 뒤에서 데려간다. 천장 쪽에서 무엇이 조금 움직였다.<br><br>한 수를 안 내는 것도 한 수다. 칠 자리를 고르던 눈이 치지 않을 자리를 고른다. 판 전체를 먼저 읽는 눈이 생겼다.`,
      ng:`보는 사이 등이 아주 조금 굽는다. 목덜미가 더 드러난다. 짚어 달라는 듯이.<br><br>손가락이 저절로 움찔한다. 오래 길든 손이다. 손목을 다른 손으로 붙잡았다.<br>천장에서 무엇이 떨어졌다. 이쪽이 아니라 이쪽 그림자 위에. 어깨가 짓눌리듯 무거웠다. 한참 기어서 빠져나왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 다가가 혈을 짚되 한 발은 뒤에 남긴다.', k:'break', dc:23,
      ok:`왼발은 뒤에 두고 오른발만 내디뎠다. 몸을 늘여 손가락 둘로 목덜미를 짚었다.<br><br>등이 물처럼 무너졌다. 빈 옷이다. 그 순간 천장에서 긴 팔이 내려와 방금 이쪽 몸이 있던 자리를 쓸었다.<br>뒤에 남긴 발로 몸을 당겨 빠졌다. 팔이 허공을 쥐고 천장으로 거둬졌다.`,
      ng:`짚는 순간 등이 돌아섰다. 얼굴이 없다. 목덜미가 앞에도 있다.<br><br>천장에서 팔이 내려와 이쪽 뒷덜미를 쥐었다. 들린다. 뒤에 남긴 발이 바닥을 긁었다.<br>일행이 다리를 붙잡아 끌어내렸다. 뒷덜미 살갗이 손톱에 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A1', t:'녹음 부스 — 언니의 목소리',
  x:`녹음 부스 유리 너머에 마이크가 하나. 아무도 없다. 스피커에서 목소리가 나온다. 진행자 언니 목소리다. 상냥하다.<br><br>
    친구들, 다 같이 따라 불러 볼까? 이름 부르면 손 들기.<br>
    언니가 이름을 부른다. 일행 이름. 불린 사람의 손이 저절로 반쯤 올라간다.<br><br>
    이쪽은 오래전에 이름 하나를 버리는 법을 배웠다. 다가갈 때마다 이름을 내려놓는다. 이름이 있으면 살기가 붙는다. 여기서는 이름이 끈이다.`,
  o:[
    { l:'① 이름을 내려놓고 부르는 소리 밑으로 지난다.', k:'hide', dc:22, wake:1,
      ok:`걸음마다 하나씩 내려놓았다. 이름, 나이, 고향. 이쪽을 부를 수 있는 것을 다.<br><br>언니가 이쪽 이름을 불렀다. 손이 안 올라간다. 그 이름의 주인이 지금 여기 없다.<br>언니가 다시 부른다. 조금 의아하게. 대답 대신 이쪽은 일행 손목을 하나씩 잡아 내렸다. 불린 손을 붙들어 주었다.<br><br>스스로 이름을 내려놓는 데서 그치지 않았다. 남이 쥔 끈 끝을 손으로 끊어 줄 수 있다. 버리는 일이 지키는 일이 되었다.`,
      ng:`이름을 다 내려놓았다고 생각했다. 하나 남았다. 어릴 때 부르던 짧은 이름.<br><br>언니가 그 이름을 불렀다. 다정하게. 손이 끝까지 올라갔다.<br>잘했어. 이리 와. 발이 부스 쪽으로 세 걸음 갔다. 일행이 허리를 끌어안아 세웠다. 그 이름이 한참 귀에서 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 비수 손잡이로 부스 유리를 깨 마이크 선을 끊는다.', k:'break', dc:23,
      ok:`비수를 거꾸로 쥐고 유리 모서리를 쳤다. 금이 간다. 한 번 더. 깨졌다.<br><br>손을 넣어 마이크 선을 쥐고 끊었다. 언니 목소리가 반쯤 남은 말에서 끊긴다.<br>스피커가 지직거린다. 그리고 다른 목소리가 작게 난다. 고마워. 아이 목소리다. 여럿.`,
      ng:`깨진 유리 틈으로 손을 넣는데 마이크가 이쪽을 향해 고개를 돌린다.<br><br>마이크 앞에서 숨을 쉬었다. 그 숨이 스피커로 크게 나간다. 언니가 웃는다. 어머, 친구 목소리 들어 보자.<br>이쪽 목에서 노래가 나왔다. 모르는 노래다. 끝까지 불렀다. 목에서 피 맛이 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-20 } }
  ] },

{ at:'A2', t:'보일러실 — 꺼지지 않은 불',
  x:`보일러실은 따뜻하다. 학교에서 처음 만난 따뜻한 데다. 물이 가슴까지 왔는데 미지근하다.<br><br>
    보일러 창 안에 불이 탄다. 물속에서. 파랗게.<br>
    배관마다 소리가 난다. 뚝, 뚝. 누가 배관 안에서 두드린다. 여러 군데서.<br><br>
    배관이 천장을 따라 학교 전체로 뻗어 나간다. 두드리는 소리가 점점 이쪽 머리 위로 모인다.`,
  o:[
    { l:'① 두드리는 소리 사이사이로 발을 옮긴다.', k:'hide', dc:22,
      ok:`뚝. 한 걸음. 뚝, 뚝. 두 걸음. 소리가 멎으면 섰다.<br><br>두드리는 쪽은 소리를 낸다. 소리를 내는 동안은 듣지 못한다.<br>보일러실을 가로질렀다. 문을 열 때 배관 소리가 한꺼번에 멎었다. 이쪽이 연 문소리를 들은 것이다. 그때는 이미 문 밖이었다.`,
      ng:`셋째 걸음에 소리가 멎었다. 이쪽 발이 물을 가르는 소리만 남았다.<br><br>머리 위 배관이 일제히 두드린다. 이쪽 바로 위에서. 배관 이음매가 벌어지며 미지근한 물이 쏟아진다. 물속에서 손이 같이 쏟아진다.<br>문까지 손을 헤치고 나왔다. 어깨가 데었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 불가에서 젖은 몸과 기를 말린다.', k:'steady', dc:22,
      ok:`보일러 옆 높은 선반에 올라 앉았다. 물 밖이다. 불 열기가 올라온다.<br><br>옷을 짜고 기를 돌렸다. 언 손발이 풀린다. 일행도 하나씩 올라와 등을 댔다.<br>선반 구석에 기름종이 꾸러미가 있다. 말린 고기다. 보일러 당번이 숨겨 둔 야식이다. 나눠 먹었다.`,
      ng:`선반에 앉아 몸을 말리는데 졸음이 온다. 따뜻한 졸음이다.<br><br>눈을 감았다 떴다. 물이 턱까지 와 있다. 선반은 그대로인데 물이 올라왔다. 따뜻한 물이다. 그래서 몰랐다.<br>일행을 깨워 뛰었다. 다들 물을 먹었다. 따뜻한 물이 가장 위험하다.`,
      win:{ exp:16, dream:2, hp:10, item:'말린 고기' }, lose:{ hp:-24, mind:-18 } },
    { l:'③ 내공을 손끝에 실어 배관 이음매의 혈을 짚는다.', k:'gaze', dc:23, cost:{ qi:28 },
      ok:`배관에 손을 대고 두드림이 모이는 데를 찾았다. 소리가 다 지나가는 이음매 하나. 거기가 목이다.<br><br>손가락 둘에 기를 모아 이음매를 눌렀다. 쇠가 아주 조금 오므라든다. 통로가 좁아진다.<br>두드리는 소리가 그 너머에서 막혔다. 이쪽 머리 위로 안 온다. 배관 너머가 한참 조용하다가 아주 멀리서 다시 시작됐다.`,
      ng:`기를 실어 눌렀는데 이음매가 이쪽 손가락을 빨아들인다. 쇠가 아니라 입이다.<br><br>손가락 끝이 배관 안으로 들어간다. 안에서 작은 이빨이 손톱을 깨문다.<br>비틀어 뺐다. 손톱 하나가 배관 안에 남았다. 안에서 그걸 씹는 소리가 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A', t:'어둠 — 어릴 적 이름',
  x:`어둠 속에서 누가 부른다. 짧은 이름. 아무도 모르는 이름.<br><br>
    칼을 잡기 전에 쓰던 이름이다. 어머니만 그렇게 불렀다.<br>
    목소리도 그 목소리다. 밥 먹어라, 하는 목소리.<br><br>
    몸이 먼저 돌아선다. 오래전에 버린 이름에도 몸은 대답하려 한다.`,
  o:[
    { l:'① 그 이름까지 마저 내려놓는다.', k:'steady', dc:23, wake:1,
      ok:`섰다. 눈을 감았다. 그 이름을 떠올렸다. 마지막으로.<br><br>그리고 내려놓았다. 바닥에 두듯이. 그 이름으로 불리던 아이도, 밥 짓는 냄새도, 그 목소리도.<br>어둠이 다시 불렀다. 그 이름을. 이번에는 아무것도 돌아서지 않았다. 그 이름의 주인은 이제 어디에도 없다.<br><br>목소리가 한참 헤매다 멎었다. 가슴이 텅 빈 것 같았다. 비어서 가볍다. 남김없이 버린 사람은 어디에도 붙잡히지 않는다.`,
      ng:`내려놓으려는데 목소리가 운다. 왜 대답을 안 하니.<br><br>대답이 목까지 올라왔다. 삼켰다. 삼킨 것이 가슴에서 터졌다. 숨이 막힌다.<br>주저앉았다. 울음이 났다. 몇 년 만인지 모른다. 어둠은 그 울음을 오래 들었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 소리 나는 쪽으로 비수를 던진다.', k:'break', dc:23,
      ok:`이름이 끝나는 자리를 노렸다. 말끝은 입이 있는 데서 끝난다.<br><br>비수가 날아가 박혔다. 어둠 속에서 목소리가 끊겼다. 그리고 다른 소리가 났다. 젖은 천이 바닥에 떨어지는 소리.<br>비수를 주우러 가지 않았다. 그 자리에 무엇이 있든, 이쪽 어머니는 아니다.`,
      ng:`던지려는 손이 안 움직였다. 어머니 목소리 쪽으로는 손이 안 나간다.<br><br>목소리가 다가온다. 따뜻한 손이 볼을 쓰다듬는다. 손가락이 넷이다.<br>뒷걸음질 쳤다. 볼에 젖은 손자국이 남았다. 한참 닦아도 차가웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 멎어 가는 맥',
  x:`일행이 잠들었다. 자객은 습관처럼 맥을 센다. 다섯 사람 손목을 차례로.<br><br>
    한 사람의 맥이 느리다. 한 번 뛰고, 오래 쉬고, 한 번.<br>
    자는 얼굴은 편하다. 너무 편하다. 입가가 웃는다.<br><br>
    누가 꿈에서 데려가는 중이다. 맥이 멎으면 다 데려간 것이다.`,
  o:[
    { l:'① 혈을 짚어 멎어 가는 맥을 다시 친다.', k:'heal', dc:23,
      ok:`가슴 한가운데와 손목 안쪽 혈에 손가락을 꽂았다. 기를 짧게 끊어 넣었다. 두드리듯.<br><br>맥이 한 번 튄다. 두 번. 제 박자를 찾는다. 웃던 입가가 굳는다. 그리고 눈을 번쩍 떴다. 숨을 크게 들이쉬었다.<br>무슨 꿈을 꿨냐고 물었다. 운동장에서 줄을 서는 꿈이었다고 했다. 자리 하나가 비어 있었다고.`,
      ng:`혈을 짚었는데 맥이 오히려 느려진다. 기가 그 사람 몸 안에서 무엇에 먹힌다.<br><br>먹히는 기가 이쪽 손가락까지 거꾸로 빨려 나온다. 손끝이 언다.<br>억지로 흔들어 깨웠다. 깨어난 얼굴이 한참 이쪽을 못 알아봤다. 이쪽 손가락은 날이 샐 때까지 굽지 않았다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 맥이 멎는 자리에 무엇이 붙었는지 본다.', k:'gaze', dc:22,
      ok:`그 사람 손목을 들어 불빛에 비췄다. 맥 자리 살갗 밑에 무엇이 비친다. 실 같은 것.<br><br>따라갔다. 손목에서 바닥으로. 바닥 틈으로 들어간다. 젖은 실이다.<br>비수로 끊었다. 그 사람 맥이 바로 돌아왔다. 끊긴 실 끝이 바닥 틈으로 빨려 들어갔다.`,
      ng:`보는데 실이 하나가 아니다. 다섯. 일행 다섯 손목마다. 이쪽 손목에도.<br><br>다 바닥 틈으로 들어간다. 이쪽 실이 당겨진다. 손목이 바닥 쪽으로 끌린다.<br>다섯 실을 다 끊는 동안 손목이 바닥에 몇 번이고 처박혔다. 손목이 퉁퉁 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A1', t:'7층 복도 — 입장 대기',
  x:`7층 복도 벽을 따라 인형탈들이 줄 서 있다. 노란 해, 갈색 털, 파란 새. 번갈아 끝없이.<br><br>
    다들 스튜디오 문을 향해 섰다. 입장을 기다린다. 한 칸씩 앞으로 간다. 발소리는 없다.<br>
    줄 중간에 한 칸이 비었다. 그 칸 앞뒤 탈이 고개를 조금 돌려 복도를 본다. 채울 사람을 찾는다.<br><br>
    스튜디오 반대쪽에 송출 부스 쪽 문이 있다. 줄 옆을 지나야 한다.`,
  o:[
    { l:'① 탈들의 걸음에 섞이지 않고 벽 그늘로 지난다.', k:'hide', dc:22,
      ok:`줄이 한 칸 움직일 때마다 멈췄다. 움직이는 것들 옆에서 서 있는 것은 벽이다.<br><br>빈 칸 앞을 지날 때 앞뒤 탈이 고개를 돌렸다. 이쪽 쪽으로. 숨을 끊고 섰다. 맥까지 늦췄다.<br>탈들이 다시 문 쪽을 봤다. 서 있는 것은 줄에 설 마음이 없는 것이다. 문에 닿았다. 뒤에서 줄이 또 한 칸 움직였다.`,
      ng:`줄이 움직일 때 같이 한 걸음 디뎠다. 그만 박자가 맞았다.<br><br>빈 칸 앞뒤 탈이 이쪽 어깨를 잡는다. 털 손과 깃털 손. 부드럽다. 빈 칸으로 끌어당긴다.<br>뿌리치며 벽을 짚고 문으로 굴렀다. 어깨에 털이 한 움큼 들러붙었다. 떼어 내니 살갗이 같이 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 내공을 실어 빈 칸 앞 탈의 목 혈을 끊는다.', k:'break', dc:23, cost:{ qi:30 },
      ok:`빈 칸 앞 탈의 뒤로 붙었다. 털 깃 사이 목 자리에 손날을 세웠다. 기를 실어 한 번.<br><br>탈의 고개가 앞으로 툭 떨어진다. 줄이 멈춘다. 앞이 멈추면 뒤도 멈춘다.<br>멈춘 줄 옆을 걸어서 지났다. 탈들은 앞만 본다. 앞이 안 움직이면 다들 기다린다. 오래 기다린다.`,
      ng:`손날이 털에 파묻혔다. 목 자리가 없다. 솜만 깊다.<br><br>탈이 고개를 돌린다. 웃는 해 얼굴이 이쪽 코앞이다. 손날을 문 채 털이 오므라든다.<br>손을 빼는 데 손목이 비틀렸다. 줄 전체가 이쪽을 향해 한 칸 돌아섰다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A2', t:'강당 — 명찰 줄',
  x:`강당 천장에서 바닥까지 줄이 늘어졌다. 줄마다 명찰이 꿰여 있다. 수백 개. 물속에서 흔들린다.<br><br>
    명찰은 젖지 않았다. 이름마다 학년과 반이 수놓였다. 줄이 무대 쪽으로 기운다.<br>
    무대 쪽 줄 하나에 명찰이 하나 덜 꿰였다. 빈 고리가 있다.<br><br>
    이쪽은 명찰을 단 적이 없다. 이름표를 다는 순간 그건 누군가의 것이 된다.`,
  o:[
    { l:'① 명찰 줄 사이를 물 밑으로 잠겨 지난다.', k:'hide', dc:23, wake:1,
      ok:`숨을 닫고 잠겼다. 줄과 줄 사이 간격이 어깨 너비다. 몸을 옆으로 세웠다.<br><br>명찰이 얼굴 옆을 스친다. 이름들이 읽힌다. 하나도 소리 내 읽지 않았다. 읽으면 부르는 것이다.<br>무대 옆 계단에 닿았다. 줄 하나도 흔들리지 않았다.<br><br>이름 사이를 이름 없이 지나는 법. 이름을 버린 사람은 이름들 틈을 물처럼 지난다. 남의 이름도 건드리지 않는 손이 됐다.`,
      ng:`줄 사이를 지나다 명찰 하나를 소리 없이 읽었다. 입술만 움직여.<br><br>그 명찰이 이쪽 쪽으로 돈다. 그 줄이 이쪽 어깨에 감긴다. 다른 줄들도 따라 감긴다.<br>물 밑에서 줄에 묶인 채 버둥거렸다. 일행이 끊어 줄 때까지 숨이 다했다. 물을 많이 먹었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-22 } },
    { l:'② 내공으로 몸을 가볍게 해 수면 위를 건넌다.', k:'evade', dc:23, cost:{ qi:30 },
      ok:`기를 끌어올려 몸을 가볍게 했다. 발끝만 물에 닿는다. 파문이 작다.<br><br>명찰 줄은 수면 위로도 이어진다. 줄 사이를 발끝으로 건넜다. 줄이 이쪽 무게를 못 느낀다.<br>무대 옆에 내렸다. 그제야 기가 다 빠져 무릎이 꺾였다.`,
      ng:`기가 반쯤에서 떨어졌다. 물에 빠졌다. 첨벙.<br><br>줄들이 일제히 물결 쪽으로 기운다. 명찰들이 이쪽을 향한다. 이름들이 이쪽을 본다.<br>헤엄쳐 무대 옆까지 갔다. 줄 몇 가닥이 발목에 감겨 따라왔다. 끊는 데 손가락을 베었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-18 } },
    { l:'③ 빈 고리에 걸릴 명찰을 먼저 찾아 없앤다.', k:'luck', dc:22,
      ok:`빈 고리 근처 물 밑을 더듬었다. 손에 무엇이 걸린다. 명찰이다. 아직 꿰이지 않았다.<br><br>이름은 반만 수놓였다. 실 끝에 바늘이 매달렸다. 바늘을 뺐다. 명찰을 물 밑 깊이 던졌다.<br>빈 고리가 흔들리다 멎었다. 채울 것이 없으면 기다리지도 않는다.`,
      ng:`명찰을 찾았다. 반쯤 수놓인 이름이 이쪽 이름이다. 손에 쥔 순간 바늘이 손가락을 찔렀다.<br><br>바늘이 살 속에서 한 땀을 뜬다. 혼자서. 이름 한 자가 손가락에 수놓인다.<br>바늘을 뽑아냈다. 손가락에 실밥이 남았다. 떼어 내도 자국이 이름 모양이다.`,
      win:{ exp:16, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'복도 — 첫 공부',
  x:`복도 바닥에 물이 얇게 깔렸다. 디디면 찰박 소리가 난다.<br><br>
    복도 저편에 그것이 있다. 귀만 있다. 사람 키만 한 귀가 벽에 붙어 있다. 소리 쪽으로 돈다.<br>
    이쪽의 첫 공부는 발소리를 지우는 것이었다. 젖은 바닥에서는 해 본 적이 없다.<br><br>
    일행은 다섯. 발소리도 다섯이다.`,
  o:[
    { l:'① 발소리를 지우고 혼자 먼저 지나 길을 연다.', k:'hide', dc:23,
      doom:{ title:'찰박', what:'벽의 귀 속으로 끌려 들어갑니다', dc:18, sec:45,
        text:`발바닥 앞쪽만 디디고 물을 밀듯 옮겼다. 찰박 소리가 안 난다. 다섯 걸음, 열 걸음.<br><br>귀 앞을 지날 때 귀가 돈다. 이쪽 쪽으로. 소리가 없는데. 이쪽 심장 소리다. 발소리를 지우느라 심장이 빨라졌다.<br>귀 안쪽이 열린다. 깊다. 안에서 바람이 빨려 든다.<br><br>몸이 귀 쪽으로 쏠린다. 젖은 바닥에서 발이 미끄러진다. 귓바퀴가 이쪽 어깨를 감싼다. 따뜻하다. 안으로.`,
        dieText:`복도 벽의 귀가 오래 조용했다.<br><br>그러다 귀 안쪽에서 소리가 났다. 발소리다. 찰박, 찰박. 이쪽 걸음 박자로.<br>귀는 그 소리를 듣느라 다음 일행이 지나는 것도 몰랐다.` },
      ok:`지나기 전에 숨부터 골랐다. 발소리를 지우면 심장이 빨라진다. 귀는 그것도 듣는다.<br><br>기를 내려 심장을 눌렀다. 맥을 늦추고 발을 밀었다. 귀 앞을 지날 때 귀는 벽 쪽을 향해 있었다.<br>지나서 돌아섰다. 바닥에 작은 돌을 하나 굴려 복도 끝으로 보냈다. 귀가 그쪽으로 돈다. 그사이 일행이 건넜다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 일행 다섯의 걸음을 하나로 맞춘다.', k:'bond', dc:22,
      ok:`일행을 한 줄로 세웠다. 앞사람 발자국에 뒷사람 발을 넣게 했다. 이쪽이 맨 앞에서 박자를 쳤다. 손가락으로 어깨를 톡톡.<br><br>다섯 발이 한 발로 디딘다. 찰박 소리가 하나다. 하나는 물 떨어지는 소리와 같다.<br>귀가 한 번 돌았다가 되돌아갔다. 다섯을 하나로 들었다.`,
      ng:`셋째가 반 박 늦었다. 찰박, 찰박. 두 번.<br><br>귀가 돈다. 귀 안쪽에서 바람이 빨려 든다. 셋째 몸이 기운다. 붙잡았다. 둘이 같이 끌려가다 벽 모서리를 붙들었다.<br>귀가 거둬질 때까지 버텼다. 팔이 빠질 듯 아팠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A', t:'문 — 문 밑의 발',
  x:`문 밑 틈으로 불빛이 샌다. 그 불빛이 둘로 끊겼다. 발이 서 있다. 문 바로 앞.<br><br>
    발끝이 이쪽을 향했다. 맨발이다. 발가락이 물에 불었다.<br>
    문을 열면 마주친다. 안 열면 지나갈 데가 없다.<br><br>
    자객은 마주치면 한 수에 끝낸다. 한 수에 안 끝나는 것은 상대하지 않는다.`,
  o:[
    { l:'① 문 밑 틈으로 비수를 낮게 밀어 넣는다.', k:'break', dc:23,
      ok:`엎드려 비수를 틈에 눕혔다. 손끝으로 튕겼다. 바닥을 미끄러져 들어간다.<br><br>발등에 박혔다. 발이 움찔 물러난다. 불빛이 다시 하나로 이어졌다.<br>문을 열었다. 아무도 없다. 비수만 바닥에 떨어져 있다. 날에 물이 묻었다. 피는 없다.<br><br>문 너머 바닥에 젖은 발자국이 뒷걸음질 친 모양으로 이어져 있었다.`,
      ng:`비수를 밀었다. 틈에서 발가락이 비수를 집었다. 발가락으로.<br><br>비수가 도로 밀려 나온다. 날이 이쪽을 향해. 손바닥에 박혔다.<br>틈 너머에서 아주 작게 웃는 소리가 났다. 손바닥을 싸매는 데 천이 다 젖었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 숨을 끊고 발이 먼저 떠나길 기다린다.', k:'steady', dc:22,
      ok:`문 옆 벽에 등을 붙이고 숨을 끊었다. 맥까지 늦췄다.<br><br>오래. 발이 움직이지 않는다. 그러다 발끝이 돈다. 옆으로. 그리고 멀어진다. 불빛이 하나로 이어진다.<br>문을 열었다. 복도 바닥에 젖은 발자국이 이어진다. 다음 문 앞에서 멈췄다. 다음 문에서 또 기다리는 것이다.`,
      ng:`기다리는데 발이 하나 더 왔다. 둘, 셋. 불빛이 여러 조각으로 끊긴다.<br><br>문 밑 틈으로 손가락들이 기어 나온다. 바닥을 더듬는다. 이쪽 발 쪽으로.<br>숨을 끊은 채 발을 들었다. 너무 오래 끊었다. 머리가 하얘져 쓰러졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'깊은 곳 — 아무도 아닌 걸음',
  x:`큰 방에 그것이 서 있다. 키가 천장에 닿는다. 팔이 바닥에 끌린다.<br><br>
    그것은 이쪽을 보지 않는다. 듣는다. 숨을, 발을, 맥을. 그리고 살기를.<br>
    일행이 반대편 문으로 가려면 그것 옆을 지나야 한다.<br><br>
    이쪽은 다가가는 동안 하나씩 버린다. 여기서는 몇 개를 더 버려야 한다.`,
  o:[
    { l:'① 살기, 발소리, 맥까지 버리고 그것의 목에 닿는다.', k:'hide', dc:24, wake:1,
      ok:`살기를 거뒀다. 발소리를 지웠다. 맥을 눌렀다. 그리고 체온까지 식혔다.<br><br>그것 앞에 섰다. 그것이 고개를 숙여 듣는다. 아무것도 안 들린다. 이쪽은 지금 아무도 아니다.<br>팔이 닿는 거리에서 목 혈 자리에 손가락 둘을 꽂고 기를 한 번에 밀었다.<br><br>그것이 무릎을 꿇는다. 소리 없이. 일행이 지났다. 이쪽은 마지막에 지났다. 버린 것을 하나씩 다시 주우며. 가진 것을 다 내려놓고도 돌아올 길을 아는 사람이 됐다.`,
      ng:`맥을 누르다 하나를 놓쳤다. 숨. 아주 얕은 숨.<br><br>그것의 고개가 이쪽으로 꺾인다. 팔이 바닥을 쓸며 온다. 다리를 휩쓸었다.<br>벽까지 굴렀다. 일행이 끌어당겨 줄 때까지 숨이 돌아오지 않았다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-36, spirit:-24 } },
    { l:'② 내공을 다 끌어올려 정면에서 한 장을 친다.', k:'break', dc:24, cost:{ qi:34 },
      ok:`단전을 비워 손바닥에 실었다. 숨기지 않았다. 그것 앞으로 곧장 들어갔다.<br><br>장이 가슴에 닿았다. 안에서 무언가 터진다. 그것이 뒤로 한 걸음 물러난다. 또 한 걸음. 천장에 머리를 부딪치며 주저앉았다.<br>손바닥이 얼얼하다. 그것의 가슴은 차고 물렀다. 물주머니를 친 느낌이었다.`,
      ng:`장이 반만 실렸다. 그것의 가슴이 이쪽 손바닥을 받아 오목하게 들어간다. 그리고 되민다.<br><br>몸이 날아갔다. 벽에 부딪쳤다. 갈비가 울렸다.<br>그것은 이제 이쪽을 들었다. 일행이 끌어내는 동안 팔이 두 번 바닥을 쓸었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-38, mind:-18 } },
    { l:'③ 그것이 다른 소리를 듣는 틈에 일행을 벽 따라 보낸다.', k:'evade', dc:23,
      ok:`비수 하나를 방 반대편 천장으로 던졌다. 박히는 소리. 그것이 그쪽으로 돈다.<br><br>그 틈에 손짓으로 하나씩 보냈다. 벽에 붙어. 발소리를 줄여서.<br>다섯이 다 문을 지났다. 마지막에 이쪽이 지났다. 그것은 천장의 비수를 오래 올려다봤다.`,
      ng:`그것이 돌지 않았다. 비수 소리는 들었지만 일행 발소리를 먼저 들었다.<br><br>팔이 벽을 쓸었다. 일행 하나가 걸렸다. 몸을 날려 대신 받았다.<br>등이 찢겼다. 그래도 다섯은 다 문을 지났다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-32, spirit:-20 } }
  ] }

]);

// ── 그림자술사 (shadow) · 마력 ──
kJob('shadow', 'A', [

{ at:'A', t:'복도 — 먼저 가는 쪽',
  x:`그림자는 주인보다 먼저 움직인다. 그림자술사는 그걸 안다. 늘 그렇게 부려 왔다.<br><br>
    복도에서 그림자가 먼저 움직였다. 오른쪽으로. 이쪽은 아직 왼쪽으로 갈지 오른쪽으로 갈지 안 정했다.<br>
    그림자가 오른쪽 벽에 기대 기다린다. 이쪽을.<br><br>
    부린 적 없는 쪽으로 그림자가 간다. 누가 저쪽에서 부르고 있다.`,
  o:[
    { l:'① 그림자가 기우는 결을 읽어 부르는 쪽을 가늠한다.', k:'gaze', dc:22, wake:1,
      ok:`그림자 끝을 봤다. 오른쪽 벽으로 기운다. 기우는 각이 일정하지 않다. 당겨졌다 풀렸다 한다. 숨 쉬는 박자다.<br><br>당기는 쪽은 숨을 쉰다. 오른쪽 복도 끝 문 너머. 거기서 들이쉴 때마다 그림자가 끌려간다.<br>왼쪽으로 갔다. 그림자가 한참 버티다 끌려오듯 따라왔다. 발에 붙을 때 조금 뜨거웠다.<br><br>그림자가 끌려가는 쪽을 보면 부르는 것이 보인다. 그림자가 이쪽 눈이 되는 법이 하나 늘었다. 부리는 것만이 아니라 읽는 것.`,
      ng:`결을 읽는 사이 그림자가 발에서 반쯤 떨어졌다. 오른쪽으로 더 기운다.<br><br>발목이 같이 당겨진다. 그림자는 발에 묶여 있다. 그림자가 가면 발도 간다.<br>일행이 어깨를 잡아 버텨 줄 때까지 오른쪽으로 세 걸음 끌려갔다. 발목이 삐었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 마력으로 그림자를 발꿈치에 꿰맨다.', k:'steady', dc:23, cost:{ mana:28 },
      ok:`손가락 끝에 마력을 실로 뽑아 그림자 발꿈치를 이쪽 발꿈치에 꿰맸다. 세 땀.<br><br>그림자가 오른쪽으로 당기다 멈춘다. 꿰맨 데가 팽팽하다. 버틴다.<br>왼쪽으로 걸었다. 그림자가 질질 끌려온다. 오른쪽 문 너머에서 실망한 숨이 길게 났다.<br><br>꿰맨 자리가 따끔하다. 그림자도 살이다.`,
      ng:`꿰매는데 그림자가 실을 끊는다. 한 땀, 두 땀.<br><br>그림자가 발꿈치에서 떨어져 오른쪽으로 미끄러져 간다. 문 밑 틈으로 들어간다.<br>그림자 없는 발로 서 있었다. 몸이 너무 가볍다. 쓰러질 것 같다. 한참 뒤에 그림자가 돌아왔다. 문 너머 냄새를 묻혀서.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-26 } },
    { l:'③ 그림자가 가자는 대로 몰래 따라가 본다.', k:'hide', dc:23,
      ok:`그림자를 앞세웠다. 이쪽은 그림자 뒤에 숨었다. 그림자 그늘에.<br><br>오른쪽 복도 끝 문 앞에서 그림자가 멈춘다. 문틈으로 손이 나와 그림자를 쓰다듬는다. 이쪽 그림자인 줄 알고, 주인도 거기 있는 줄 안다.<br>주인은 세 걸음 뒤에 있다. 손이 그림자만 끌어당기는 순간 그림자를 거둬들이고 물러났다. 손이 빈 바닥을 쥐었다.`,
      ng:`따라가다 그림자가 문틈으로 쑥 들어갔다. 발이 문 앞까지 끌려간다.<br><br>문틈에 발끝이 끼었다. 안쪽에서 무엇이 발끝을 만진다. 젖었다.<br>발을 빼는 데 신발 한 짝을 버렸다. 그림자가 돌아왔을 때 발가락 끝이 하얗게 얼어 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A1', t:'무대 — 핀 조명',
  x:`무대 쪽에서 둥근 빛이 내려온다. 핀 조명이다. 천장 어딘가에서 누가 돌린다.<br><br>
    빛이 일행을 쫓는다. 빛 안에서는 그림자가 발밑에 짧게 웅크린다. 빛 가장자리에 서면 그림자가 길게 늘어진다. 무대 쪽으로.<br>
    늘어진 그림자 끝에 무대 위 무엇이 발을 올려놓는다. 밟는다.<br><br>
    이쪽은 그림자 길이를 다룬다. 빛을 다룬 적은 없다.`,
  o:[
    { l:'① 빛 가장자리에서 그림자를 짧게 접어 발밑에 감춘다.', k:'hide', dc:22, wake:1,
      ok:`그림자 끝을 손으로 잡아당겨 접었다. 한 번, 두 번. 그림자가 발밑에서 손수건만 해진다.<br><br>빛 가장자리를 따라 걸었다. 그림자가 늘어지려 할 때마다 접었다. 무대 위 것이 밟을 끝이 없다.<br>일행 그림자도 하나씩 접어 주었다. 다섯이 다 발밑에 그림자를 숨기고 빛 밖으로 나왔다.<br><br>남의 빛 속에서 그림자를 줄이는 법. 빛이 누구 것이든 그림자는 이쪽 것이다. 그걸 다루는 손이 하나 늘었다.`,
      ng:`접다가 놓쳤다. 그림자가 탁 풀리며 무대까지 길게 뻗었다.<br><br>무대 위 무엇이 그 끝을 밟는다. 발목이 무대 쪽으로 꺾인다. 쓰러졌다. 끌린다.<br>그림자를 손톱으로 끊어 냈다. 끊긴 그림자 끝이 무대 위에 남았다. 돌아온 그림자가 짧다. 발가락 하나만큼.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 빛 한가운데로 들어가 그림자를 아예 지운다.', k:'steady', dc:23,
      doom:{ title:'핀 조명', what:'빛에 싸여 무대 한가운데로 끌려 나갑니다', dc:18, sec:50,
        text:`빛 한가운데에 섰다. 그림자가 발밑에서 사라진다. 밟힐 그림자가 없다.<br><br>빛이 따뜻하다. 아주 밝다. 눈을 뜰 수 없다. 스피커에서 박수가 난다. 빛 안에 선 사람에게 치는 박수다.<br>빛이 움직인다. 무대 쪽으로. 빛 안에 있는 몸도 같이 간다. 빛 밖으로 나가려 했다. 빛 가장자리가 벽처럼 단단하다.<br><br>그림자가 없으니 버틸 데가 없다. 발이 미끄러진다. 무대 계단을 하나씩 올라간다.`,
        dieText:`무대 한가운데 핀 조명이 멈췄다. 박수가 길게 난다.<br><br>빛 안에 누가 서 있다. 그림자가 없다. 웃고 있다.<br>조명이 꺼지자 무대 바닥에 그림자 하나가 남았다. 주인 없이. 무대 밖으로 기어 나가려다 멈췄다.` },
      ok:`빛 한가운데에 들어가기 직전에 멈췄다. 빛 안 바닥에 그림자 없는 발자국이 줄지어 있다. 다 무대 쪽을 향한다.<br><br>빛 안에서는 그림자가 없다. 그림자가 없으면 버틸 데도 없다. 빛은 그걸 아는 빛이다.<br>그림자를 앞세워 빛 가장자리를 짚었다. 그림자가 빛을 조금 갉아먹는다. 그 틈으로 일행을 내보냈다. 빛이 빈자리를 비추며 무대로 돌아갔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'교실동 — 수면 밑 그림자',
  x:`복도 물은 허리 깊이. 위에서 희미한 빛이 든다. 수면 밑 바닥에 그림자가 진다.<br><br>
    일행 그림자 다섯. 그 사이에 다른 그림자들이 걷는다. 작은 그림자. 책가방을 멘 모양.<br>
    그림자만 있다. 그림자를 드리울 몸은 어디에도 없다.<br><br>
    작은 그림자들이 일행 그림자 옆에 붙는다. 손을 잡는다. 그림자끼리.`,
  o:[
    { l:'① 제 그림자를 작은 그림자들 사이에 섞어 걷는다.', k:'hide', dc:22,
      ok:`그림자를 좁고 낮게 줄였다. 책가방 멘 아이 키만큼.<br><br>작은 그림자들 사이에 섞였다. 작은 그림자들이 이쪽 그림자를 같은 반으로 여긴다. 손을 잡지 않는다. 같은 줄에 선다.<br>일행 그림자 옆에 붙은 것들을 하나씩 이쪽 줄로 불러냈다. 줄 맨 끝에 서면 다들 따라온다.<br><br>교실동 끝에서 작은 그림자들이 계단 쪽으로 줄지어 내려갔다. 이쪽 그림자만 남았다.`,
      ng:`줄였는데 작은 그림자가 이쪽 그림자 손을 잡는다. 같은 반이니까.<br><br>그림자 손이 당긴다. 계단 쪽으로. 줄 맞춰서. 그림자가 끌려가니 다리가 물속에서 무거워진다.<br>그림자를 비틀어 뺐다. 그림자 손목에 작은 손 자국이 남았다. 이쪽 진짜 손목에도.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 마력으로 작은 그림자 하나를 붙잡아 말을 듣는다.', k:'bond', dc:23, cost:{ mana:28 },
      ok:`마력을 손바닥에 모아 물속으로 넣었다. 작은 그림자 하나 어깨를 살짝 눌렀다.<br><br>그림자가 멈춘다. 고개를 든다. 그림자에는 얼굴이 없는데 올려다보는 게 느껴진다.<br>그림자 손가락이 바닥을 긁어 글씨를 쓴다. 물속 진흙에. 서쪽 계단은 막혔어. 동쪽.<br><br>놓아주었다. 그림자가 줄로 돌아갔다. 동쪽 계단으로 갔다. 막히지 않았다.`,
      ng:`붙잡았더니 그림자가 버둥거린다. 그리고 운다. 소리 없이. 물이 그 둘레에서 떨린다.<br><br>다른 그림자들이 다 멈춘다. 이쪽을 본다. 일행 그림자들의 손을 놓고 이쪽 그림자에 몰려든다.<br>그림자째 물에 눌렸다. 무릎이 꺾여 얼굴까지 잠겼다. 놓아준 뒤에야 풀렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 무거워진 그림자',
  x:`쉬기 전에 그림자를 떼어 보냈다. 복도 끝까지 보고 오라고. 늘 하던 일이다.<br><br>
    그림자가 돌아왔다. 발에 붙는다. 무겁다.<br>
    무게가 이쪽 무게가 아니다. 다리가 조금 더 짧게 느껴진다. 그림자가 이쪽 발을 아래로 누른다.<br><br>
    그림자 안에 손님이 탄 것이다. 복도 끝에서 같이 왔다.`,
  o:[
    { l:'① 그림자를 벽에 털어 손님만 떨어낸다.', k:'steady', dc:23, wake:1,
      ok:`그림자를 발에서 반쯤 떼어 벽에 세웠다. 옷 털듯 그림자 끝을 잡고 흔들었다.<br><br>그림자에서 무엇이 떨어진다. 그림자보다 진한 덩어리. 아이 무릎만 하다. 벽을 타고 위로 기어 오른다. 천장 구석으로.<br>가벼워진 그림자를 발에 붙였다. 제 무게다.<br><br>그림자 안에 무엇이 들었는지 무게로 아는 것. 그림자를 보내는 손이 받는 손도 되었다. 들고 오는 것을 고를 수 있다.`,
      ng:`흔들었는데 손님이 안 떨어진다. 그림자 깊이 붙었다.<br><br>털수록 그림자가 찢어진다. 찢어진 데서 손님이 이쪽 다리로 건너온다. 진짜 다리로. 종아리가 시퍼렇게 언다.<br>다리를 불에 쬐어서야 빠져나갔다. 종아리에 작은 손자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 그림자 안을 들여다보고 손님에게 내리라고 한다.', k:'gaze', dc:22,
      ok:`그림자 위에 쪼그려 앉아 들여다봤다. 그림자 안쪽 깊이 얼굴 하나가 있다. 아이다. 무릎을 안고 앉았다.<br><br>여기는 네 자리가 아니라고 낮게 말했다. 얼굴이 고개를 숙인다. 그리고 그림자 밖으로 기어 나간다. 벽 그늘로.<br>그림자가 가벼워졌다. 벽 그늘 쪽에서 밤새 무릎 안은 숨소리가 났다. 아무것도 하지 않았다.`,
      ng:`들여다보는데 그림자 안 얼굴이 고개를 든다. 그리고 이쪽 얼굴을 그대로 흉내 낸다.<br><br>그림자 안에 이쪽 얼굴이 있다. 이쪽은 그림자 밖에 있는데. 어느 쪽이 이쪽인지 잠깐 헷갈렸다.<br>일행 이름을 부르고서야 이쪽으로 돌아왔다. 한참 손이 떨렸다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'인형극 무대 — 막 위의 손',
  x:`인형극 무대에 하얀 막이 쳐졌다. 막 뒤에 등불. 막 위에 그림자 손 인형들이 논다. 토끼, 여우, 해님.<br><br>
    막 뒤를 들춰 보니 인형은 하나도 없다. 손도 없다. 그림자만 막 위에 있다.<br>
    그림자 여우가 막 위에서 이쪽 쪽으로 고개를 돌린다. 막에서 발 하나를 뗀다. 막 밖으로.<br><br>
    이쪽은 남의 그림자를 묶을 줄 안다. 주인 없는 그림자는 묶어 본 적이 없다.`,
  o:[
    { l:'① 마력으로 제 그림자를 떼어 막 뒤로 보내 등불을 살핀다.', k:'sense', dc:23, cost:{ mana:28 },
      ok:`그림자를 발에서 떼어 막 뒤로 보냈다. 그림자가 등불 옆에 선다.<br><br>돌아온 그림자가 본 것을 들고 온다. 등불 기름이 다 됐다. 심지가 그림자로 탄다. 불 대신 그림자가 등을 밝히고 있다. 막 위 그림자들은 그 불에서 나온다.<br>심지 끝에 손가락 하나 크기의 그림자가 매달려 탄다. 그것이 다른 그림자를 다 낳는다. 막 뒤로 손을 넣어 심지를 집어 껐다. 막 위가 하얘졌다.`,
      ng:`그림자가 막 뒤로 가서 안 돌아온다. 막 위에 이쪽 그림자가 떴다. 손 인형들 사이에.<br><br>여우가 이쪽 그림자를 문다. 토끼가 잡아당긴다. 해님이 웃는다. 막 위에서 이쪽 그림자가 인형극이 된다.<br>발목이 막 쪽으로 꺾였다. 그림자를 끊다시피 거둬들였다. 돌아온 그림자에 이빨 자국이 났다. 발목에도.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 막 앞에 서서 나오는 그림자 손을 묶는다.', k:'hide', dc:23,
      doom:{ title:'그림자 여우', what:'막 위 그림자들에게 막 뒤로 끌려 들어갑니다', dc:18, sec:50,
        text:`막 앞에 섰다. 그림자 여우가 막 밖으로 나온다. 제 그림자를 뻗어 여우 다리를 감았다.<br><br>여우가 멈춘다. 그리고 이쪽 그림자를 타고 올라온다. 그림자에서 그림자로. 이쪽 발밑까지.<br>토끼가 따라 나온다. 해님이 따라 나온다. 이쪽 그림자가 그것들로 가득 찬다. 무겁다.<br><br>막이 이쪽 쪽으로 볼록해진다. 그림자들이 이쪽 그림자를 막 쪽으로 끌어당긴다. 발이 끌린다. 막에 얼굴이 닿는다. 막 너머가 뜨겁다. 등불이다.`,
        dieText:`인형극 막 위에 그림자 인형이 하나 늘었다.<br><br>토끼, 여우, 해님. 그리고 사람 모양 하나. 손 인형이 아니다. 온몸이다.<br>막 앞에 신발 한 켤레가 있다. 그림자가 없다.` },
      ok:`묶으려다 멈췄다. 그림자 여우의 발끝이 막에서 아직 안 떨어졌다. 막에 붙은 그림자는 막 위 것이다. 막에서 떨어져야 이쪽 쪽이다.<br><br>기다렸다. 여우가 발을 다 뗐다. 막과 그림자 사이에 실 같은 그림자가 이어져 있다. 그 실을 손톱으로 끊었다.<br>여우가 바닥에 떨어져 녹았다. 막에서 떨어진 그림자는 주인이 없으면 오래 못 간다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 막 뒤 등불을 줄여 막 위를 어둡게 한다.', k:'fix', dc:22,
      ok:`막 옆으로 돌아 등불 심지를 낮췄다. 막 위 그림자들이 흐려진다.<br><br>여우는 막 밖으로 나오려다 흐려지는 중에 멈췄다. 막 가장자리에 반쯤 걸린 채 굳었다.<br>다 흐려진 막 앞을 지났다. 막 아래 받침대에 꿀 단지가 하나 있었다. 관객 간식이다.`,
      ng:`심지를 낮추는데 불이 꺼지지 않고 그림자가 짙어진다. 빛이 줄수록.<br><br>막 위가 검게 찬다. 그림자들이 막에서 흘러내린다. 바닥으로. 이쪽 발 쪽으로.<br>뒤로 뛰었다. 발목에 검은 것이 얼룩처럼 묻었다. 씻어도 지워지지 않는다. 한참 뒤에야 바랬다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'세면장 — 거꾸로 진 그림자',
  x:`세면장 거울 일곱 장. 수도꼭지가 다 열려 물이 넘친다. 천장 전구 하나가 흔들린다.<br><br>
    흔들릴 때마다 그림자가 따라 흔들린다. 이쪽 그림자도, 세면대 그림자도.<br>
    거울 속 그림자만 다르다. 거울 속 이쪽 그림자는 전구 쪽으로 진다. 빛을 향해 그림자가 뻗는다.<br><br>
    빛이 반대편에 있는 것이다. 거울 속 세면장에는 다른 불이 켜져 있다.`,
  o:[
    { l:'① 그림자가 가리키는 쪽으로 거울 속 불을 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`거울 속 그림자 방향을 거꾸로 따라갔다. 그림자가 빛을 향하면 빛은 그림자 끝 너머다.<br><br>일곱째 거울. 거울 속 그 자리에 촛불 하나가 있다. 진짜 세면장 그 자리에는 배수구가 있다. 물이 빨려 든다.<br>배수구 위에서 그림자가 둘로 갈라진다. 거울 쪽과 이쪽. 갈라지는 자리가 문이다. 거울 속 것이 나오는 문.<br><br>배수구를 비누로 막았다. 거울 속 촛불이 꺼졌다. 그림자가 거꾸로 지는 곳에는 다른 빛이 있다. 그림자로 빛을 찾는 눈이 생겼다.`,
      ng:`따라가다 거울 속 그림자가 거울 밖으로 나온다. 이쪽 그림자 위로 겹친다.<br><br>두 그림자가 서로 반대로 당긴다. 몸이 둘로 찢기는 것 같다. 한쪽 어깨가 거울 쪽으로 쏠렸다.<br>전구가 흔들림을 멈출 때까지 버텼다. 어깨가 빠질 듯 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 마력으로 세면장 바닥을 그림자로 덮고 지난다.', k:'hide', dc:23, cost:{ mana:28 },
      ok:`일행 그림자를 모아 바닥에 넓게 폈다. 물 위에 검은 천을 덮듯.<br><br>거울 속에서는 바닥이 안 보인다. 그림자 밑으로 일행이 지난다. 거울 일곱 장이 다 빈 세면장을 비춘다.<br>다 지나고 그림자를 거뒀다. 거울 하나에 손바닥 자국이 거울 안쪽에서 찍혀 있었다. 바닥을 더듬던 손이다.`,
      ng:`덮었는데 거울 속에는 그림자가 안 비친다. 일행 다섯이 그대로 비친다.<br><br>거울 속 일행에게 거울 속 손들이 뻗는다. 진짜 일행 어깨가 그 모양대로 눌린다.<br>그림자를 거두고 뛰었다. 마력이 다 새어 머리가 지끈거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'복도 — 그림자 없는 사람',
  x:`불을 들고 걷는다. 벽에 일행 그림자가 진다. 넷.<br><br>
    다섯이 걷는다. 그림자는 넷이다. 맨 끝 사람 그림자가 없다.<br>
    그 사람은 평소대로 걷는다. 평소대로 말한다. 그림자만 없다.<br><br>
    그림자술사는 그림자를 나눠 줄 수 있다. 반쪽쯤은. 반쪽이면 사람 하나가 버틴다.`,
  o:[
    { l:'① 제 그림자를 반 떼어 그 사람 발에 붙인다.', k:'hide', dc:23,
      doom:{ title:'반쪽 그림자', what:'그림자 없는 것에게 그림자째 끌려갑니다', dc:18, sec:50,
        text:`그림자를 반으로 갈라 맨 끝 사람 발밑에 밀어 붙였다.<br><br>그 사람이 웃는다. 고마워. 목소리가 맞다. 그런데 그림자가 그 사람 발에 붙지 않는다. 발 대신 손으로 받는다.<br>손으로 쥔 그림자를 당긴다. 이쪽 남은 반쪽이 딸려 간다. 이쪽 발도.<br><br>일행은 넷이 맞다. 처음부터 넷이었다. 다섯째는 불빛 밖에서 걸어 들어온 것이다. 그것이 뒷걸음질 친다. 불빛 밖으로. 이쪽을 끌고.`,
        dieText:`불을 들고 걷는다. 벽에 그림자가 다섯 진다.<br><br>다섯이 걷는다. 넷은 일행이다. 맨 끝 사람의 그림자는 조금 크다. 반쪽씩 붙인 자국이 있다.<br>그 사람은 평소대로 걷는다. 이쪽 걸음걸이로.` },
      ok:`그림자를 떼기 전에 일행 숫자를 셌다. 처음 들어올 때 몇이었는지.<br><br>넷이었다. 그림자 없는 쪽은 다섯째다. 불빛 밖에서 섞여 든 것이다.<br>그림자를 주지 않았다. 대신 불을 그쪽으로 들이밀었다. 그림자가 없는 것은 빛을 받아도 아무것도 안 남는다. 그것이 웃는 채로 빛 밖으로 물러났다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 그 사람의 그림자가 어디 떨어졌는지 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`불을 낮춰 바닥을 훑었다. 지나온 길을 거슬러.<br><br>모퉁이 하나 뒤. 벽에 그림자가 하나 붙어 있다. 맨 끝 사람 모양이다. 주인을 놓친 그림자가 벽에 기대 기다린다.<br>그림자를 손으로 떼어 들고 와 맨 끝 사람 발에 붙였다. 그 사람이 그제야 몸을 떨었다. 춥다고 했다. 그림자가 없는 동안 무엇이 그 사람 속을 들여다보고 있었다.<br><br>남의 그림자를 찾아 되돌리는 손. 이쪽 그림자만 다루던 손이 남의 그림자 자리까지 안다.`,
      ng:`찾아 거슬러 가는데 벽마다 그림자가 붙어 있다. 수십 개. 다 주인을 놓친 그림자다.<br><br>어느 것이 맨 끝 사람 것인지 모르겠다. 그림자들이 이쪽 쪽으로 손을 뻗는다. 데려가 달라는 것이다.<br>뒷걸음질 쳐 돌아왔다. 등 뒤로 그림자 손들이 한참 따라왔다. 목덜미가 얼었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A', t:'계단 — 먼저 내려오는 그림자',
  x:`위층에서 그림자가 내려온다. 계단을 따라 한 칸씩. 사람 그림자다.<br><br>
    주인은 안 보인다. 그림자만 먼저 온다. 그림자는 주인보다 먼저 움직인다.<br>
    그림자가 이쪽 발밑까지 내려왔다. 주인은 아직 위층에 있다. 곧 내려온다.<br><br>
    그림자 끝이 이쪽 그림자에 닿는다. 겹친다. 주인이 내려올 길을 이쪽 그림자 위로 낸다.`,
  o:[
    { l:'① 마력을 실어 내려온 그림자를 계단에 못 박는다.', k:'break', dc:23, cost:{ mana:30 },
      ok:`손바닥에 마력을 모아 그림자 한가운데를 눌렀다. 계단 디딤판에. 못 박듯.<br><br>그림자가 퍼덕인다. 계단에서 안 떨어진다. 위층에서 무언가 휘청한다. 그림자가 묶이면 주인도 묶인다.<br>그사이 일행을 다른 계단으로 내려보냈다. 위층에서 발 구르는 소리가 오래 났다. 내려오지 못했다.`,
      ng:`눌렀는데 그림자가 이쪽 손바닥을 타고 올라온다. 그림자에서 그림자로. 손 그림자로.<br><br>손이 저 혼자 계단 위를 짚는다. 위층에서 무엇이 이쪽 손 그림자를 잡고 당긴다. 몸이 계단 위로 끌려 오른다.<br>손 그림자를 끊다시피 거둬들였다. 손바닥이 얼음처럼 식었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 그 그림자 그늘 뒤에 이쪽을 숨긴다.', k:'hide', dc:22, wake:1,
      ok:`그림자를 걷어 내지 않았다. 대신 이쪽 그림자를 그 그림자 밑으로 밀어 넣었다. 겹친다. 하나로 보인다.<br><br>위층에서 주인이 내려온다. 발소리가 계단을 내려온다. 제 그림자를 따라. 그림자가 하나뿐이니 제 그림자 밑에 남이 있는 줄 모른다.<br>주인이 이쪽 옆을 지나간다. 차가운 바람. 젖은 냄새. 그대로 아래로 내려갔다.<br><br>남의 그림자를 덮개로 쓰는 법. 그림자는 주인보다 먼저 오지만, 주인은 제 그림자 속을 안 본다.`,
      ng:`밀어 넣는데 그림자가 이쪽 그림자를 삼킨다. 하나가 된다. 저쪽 모양으로.<br><br>내려오는 발소리에 이쪽 다리가 박자를 맞춘다. 같이 내려가려 한다.<br>계단 난간을 붙잡고 버텼다. 주인이 지나간 뒤에야 그림자가 갈라졌다. 이쪽 그림자가 조금 젖어 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A1', t:'세트 뒤 — 카드를 넘기는 그림자',
  x:`세트 뒤 벽에 그림자가 하나 크게 진다. 헤드셋을 쓴 사람. 손에 카드를 들었다. 넘긴다. 박수. 웃어요.<br><br>
    그림자 주인은 안 보인다. 그림자는 조명 앞에서 진다. 조명 앞은 비었다.<br>
    카드가 넘어갈 때마다 방청석에서 그 말대로 소리가 난다.<br><br>
    다음 카드 그림자가 비친다. 글씨가 거꾸로 비친다. 오늘의 친구.`,
  o:[
    { l:'① 감독 그림자 속으로 들어가 그 그늘로 지난다.', k:'hide', dc:23, wake:1,
      ok:`벽의 큰 그림자 속에 몸을 넣었다. 그림자 안은 차다. 남의 그늘이다.<br><br>그림자 속에서 걸으면 이쪽 그림자가 안 진다. 감독 그림자가 한 사람 몫으로 남는다.<br>카드가 넘어갔다. 오늘의 친구. 방청석이 술렁인다. 친구를 찾는다. 그림자 속에 있는 친구는 못 찾는다.<br><br>남의 그림자 안을 길로 쓰는 법. 그림자의 주인이 누구든 그 그늘은 이쪽에게 열린다. 그림자가 하나의 방이 되었다.`,
      ng:`들어갔는데 감독 그림자가 이쪽을 알아챈다. 그림자 손이 카드를 내려놓는다.<br><br>그림자 손이 이쪽 그림자 어깨를 잡는다. 벽에서. 진짜 어깨가 그대로 눌린다. 다음 순서.<br>그림자 밖으로 굴러 나왔다. 어깨에 손가락 자국이 검게 남았다. 박수가 한참 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 마력으로 카드 그림자 글씨를 바꿔 비춘다.', k:'fix', dc:23, cost:{ mana:30 },
      ok:`손가락 그림자를 마력으로 늘여 카드 그림자 위에 겹쳤다. 글씨 획을 바꿨다.<br><br>오늘의 친구가 퇴장이 된다. 방청석에서 박수가 난다. 퇴장할 때 치는 박수다.<br>무대 쪽에서 무언가 물러나는 기척이 났다. 그사이 세트 뒤를 지났다.`,
      ng:`획을 바꾸는데 카드가 넘어갔다. 이쪽 손가락 그림자가 카드 그림자에 묻어 같이 넘어갔다.<br><br>다음 카드에 이쪽 손 그림자가 찍혔다. 방청석이 그 손을 향해 손뼉을 친다. 앞으로 나와요.<br>손이 앞으로 끌려간다. 그림자를 끊어 냈다. 손가락 끝 감각이 한참 없었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } },
    { l:'③ 그림자 길이로 조명의 자리를 재고 그 앞을 피한다.', k:'gaze', dc:22,
      ok:`그림자 크기와 기울기를 봤다. 조명은 낮다. 바닥 가까이, 세트 판자 틈이다.<br><br>판자 틈에서 작은 등이 벽을 비춘다. 그 앞에 서면 그림자가 진다. 그 앞만 피하면 감독 그림자 옆을 지나도 이쪽 그림자는 안 생긴다.<br>일행을 등 뒤로 돌려 지나게 했다. 다섯 다 그림자 없이 지났다.`,
      ng:`재다가 판자 틈 등 앞을 가로질렀다. 이쪽 그림자가 벽에 크게 졌다. 감독 그림자 옆에.<br><br>감독 그림자가 고개를 돌려 이쪽 그림자를 본다. 카드를 넘긴다. 오늘의 친구.<br>방청석 박수가 등을 밀었다. 겨우 판자 뒤로 숨었다. 귀가 한참 먹먹했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'강당 — 졸업 사진',
  x:`강당 벽에 졸업 사진 액자가 줄지어 걸렸다. 해마다 하나씩. 물 위로 나와 있다.<br><br>
    마지막 액자 하나만 사진이 아니다. 그림자다. 줄 맞춰 선 아이들 그림자가 액자 유리에 비친다. 앞에 아무도 없는데.<br>
    맨 뒷줄 끝에 빈 그림자 자리가 하나 있다.<br><br>
    이쪽 그림자가 그 액자 쪽으로 조금 기운다. 자리가 맞는 모양이다.`,
  o:[
    { l:'① 액자 속 그림자 수를 세어 빠진 이름을 찾는다.', k:'sense', dc:22,
      ok:`그림자를 하나씩 셌다. 앞줄, 가운데 줄, 뒷줄. 211.<br><br>액자 밑 판에 숫자가 새겨져 있다. 재적 212. 하나가 빠졌다. 빈자리는 결석생 자리다.<br>결석생은 아직 어딘가에 있다. 이쪽이 채울 자리가 아니다. 그림자를 발에 꽉 붙이고 액자 앞을 지났다. 그림자가 아쉬운 듯 한 번 기울었다.`,
      ng:`세다가 숫자가 늘었다. 셀 때마다 하나씩. 212, 213.<br><br>213째는 이쪽 그림자다. 액자 유리 안에 이미 서 있다. 이쪽 발밑 그림자가 그만큼 옅다.<br>뒷걸음질 쳤다. 그림자가 발에서 다시 진해지는 데 오래 걸렸다. 그동안 몸이 얼음처럼 식었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 빈자리에 남의 그림자를 떼어 대신 넣어 둔다.', k:'hide', dc:23,
      doom:{ title:'빈 액자', what:'그림자째 졸업 사진 속으로 빨려 들어갑니다', dc:18, sec:45,
        text:`물에 뜬 의자 그림자를 떼어 들었다. 사람 모양으로 접어 액자 빈자리에 밀어 넣었다.<br><br>액자 속 그림자들이 일제히 고개를 돌린다. 가짜다. 의자 그림자가 액자에서 튕겨 나온다.<br>빈자리가 그대로다. 그리고 빈자리가 이쪽 그림자를 당긴다. 진짜를 달라고.<br><br>그림자가 발에서 뜯겨 나간다. 발이 따라간다. 얼굴이 액자 유리에 닿는다. 유리가 물처럼 열린다.`,
        dieText:`마지막 졸업 사진이 다 찼다. 맨 뒷줄 끝 자리까지.<br><br>액자 밑 판의 숫자가 고쳐졌다. 재적 213.<br>그 자리 그림자만 키가 크다. 다른 아이들 어깨 위로 고개 하나만큼.` },
      ok:`의자 그림자를 사람 모양으로 접다가 멈췄다. 액자 속 그림자들 발밑을 봤다. 다들 실내화를 신었다.<br><br>가짜는 들킨다. 진짜만 받는 자리다. 그림자를 내려놓고 액자 앞을 그림자 없이 지났다. 불을 등 뒤로 숨겨서.<br>액자 속 빈자리가 이쪽이 지나는 동안 내내 이쪽 쪽으로 기울었다. 받을 것이 없었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'어둠 — 불 하나, 그림자 여섯',
  x:`초 하나를 켰다. 일행이 둘러앉았다. 다섯이다.<br><br>
    벽에 그림자가 진다. 여섯.<br>
    여섯째는 일행 사이에 앉아 있다. 무릎을 안았다. 다른 그림자들보다 조금 작다.<br><br>
    불이 흔들리면 다섯 그림자가 흔들린다. 여섯째는 안 흔들린다. 다른 불에서 진 그림자다.`,
  o:[
    { l:'① 여섯째 그림자를 벽에서 잘라 낸다.', k:'break', dc:23,
      ok:`손톱에 마력을 얇게 입혀 여섯째 그림자 둘레를 그었다. 벽에서 떼어 냈다.<br><br>그림자가 손에서 퍼덕인다. 가볍다. 초 불에 대니 그림자가 오그라든다. 타는 냄새 없이.<br>벽에 그림자가 다섯이 됐다. 그런데 일행 하나가 어깨를 떤다. 방금 무엇이 옆에서 일어났다고 했다.`,
      ng:`그었는데 그림자가 안 떨어진다. 벽이 아니라 그 뒤에 붙었다. 벽 너머에.<br><br>그림자 안쪽에서 손이 나와 이쪽 손톱을 쥔다. 손톱이 들린다.<br>당겨 뺐다. 손톱 하나가 반쯤 들렸다. 초가 꺼졌다. 어둠 속에서 여섯째가 웃었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 여섯째 그림자 옆에 제 그림자를 앉혀 말을 붙인다.', k:'bond', dc:22, wake:1,
      ok:`제 그림자를 벽 위로 옮겨 여섯째 옆에 앉혔다. 그림자끼리 어깨가 닿는다.<br><br>여섯째가 고개를 든다. 그림자 손가락으로 벽을 가리킨다. 위쪽. 천장 구석. 거기서 불빛이 아주 약하게 샌다. 여섯째를 드리운 불이다.<br>그 불 밑에 길이 있다고 그림자 손이 말한다. 가 보니 환기구 덮개가 헐겁다. 덮개 안쪽에 낡은 초 한 토막과 말린 고기 한 봉지.<br><br>그림자에게 말을 거는 법. 주인 없는 그림자도 아는 것이 있다. 그림자를 부리는 손이 그림자를 듣는 귀가 됐다.`,
      ng:`여섯째가 이쪽 그림자에 기댄다. 무겁다. 그림자가 아니라 사람 무게다.<br><br>이쪽 어깨가 그만큼 처진다. 일어나려는데 다리에 힘이 안 들어간다. 여섯째가 이쪽 그림자를 베개 삼아 잠든다.<br>날이 샐 때까지 그 무게를 지고 앉아 있었다. 어깨가 내려앉았다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A1', t:'놀이 세트 — 작은 집 창',
  x:`놀이 세트에 작은 집이 있다. 아이가 들어갈 크기. 창에 노란 불이 켜졌다.<br><br>
    창에 그림자가 비친다. 갈색 털 덩어리. 뭉치다. 의자에 앉아 무언가 기다린다. 이쪽을 향해.<br>
    작은 집 뒤로 7층 계단이 있다. 창 앞을 지나야 한다.<br><br>
    창불이 바닥에 길게 깔린다. 그 빛을 밟으면 창 안 그림자가 고개를 든다.`,
  o:[
    { l:'① 창빛 가장자리 그림자를 이어 집 뒤로 건넌다.', k:'hide', dc:22, wake:1,
      ok:`세트 소품마다 그림자가 진다. 나무 판자, 우체통, 꽃 화분. 창빛 가장자리를 따라 점처럼.<br><br>그림자에서 그림자로 발을 옮겼다. 그림자 위에 선 발은 그림자가 된다. 창빛 한 칸도 안 밟았다.<br>집 뒤에 닿았다. 창 안 그림자가 고개를 돌려 창 밖을 본다. 아무도 없다. 다시 기다린다.<br><br>남이 드리운 그림자를 디딤돌로 쓰는 법. 길이 없어도 그림자가 있으면 길이 있다. 발밑이 넓어졌다.`,
      ng:`우체통 그림자가 너무 짧았다. 발끝이 창빛을 밟았다.<br><br>창 안 그림자가 일어선다. 창문이 열린다. 털 팔이 창밖으로 나온다. 길다. 이쪽 허리를 감는다.<br>털에서 좀약 냄새. 숨이 막힌다. 일행이 팔을 쳐 내고 끌어냈다. 허리에 털이 박혀 따끔거렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 마력으로 창불 그림자를 키워 불빛을 가린다.', k:'break', dc:23, cost:{ mana:28 },
      ok:`창 옆 화분 그림자를 마력으로 부풀렸다. 그림자가 창을 덮을 만큼 커진다.<br><br>창불이 바닥에 안 깔린다. 창 안에서는 밖이 까맣다. 뭉치 그림자가 고개를 갸웃한다.<br>그 앞을 지났다. 화분 그림자를 놓자 창불이 다시 깔렸다. 바닥에 이쪽 발자국은 없다.`,
      ng:`부풀리는데 그림자가 창 안으로 들어간다. 창 안 그림자와 섞인다.<br><br>뭉치 그림자가 커진다. 화분 그림자를 먹고. 창이 터질 듯 그림자로 꽉 찼다. 문이 열린다.<br>뛰었다. 등 뒤로 털 냄새가 쫓아왔다. 계단에 닿을 때까지 숨이 막혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A2', t:'수영장 — 레인 바닥',
  x:`수영장 물이 맑다. 학교에서 처음 본 맑은 물이다. 바닥까지 보인다.<br><br>
    바닥에 레인 선이 그어졌다. 선 위로 그림자들이 헤엄친다. 수영모를 쓴 그림자들. 몸은 물 위에 없다.<br>
    건너편 배수로 쪽으로 가야 한다. 수영장을 가로질러야 한다.<br><br>
    그림자들이 레인을 따라 돈다. 한 레인만 비었다.`,
  o:[
    { l:'① 물 밖에서 제 그림자만 빈 레인으로 먼저 보낸다.', k:'hide', dc:22,
      ok:`물가에 엎드렸다. 그림자를 떼어 빈 레인 바닥으로 내렸다. 그림자가 헤엄친다.<br><br>다른 레인 그림자들이 빈 레인을 본다. 새 친구다. 그쪽으로 몰린다.<br>그사이 수영장 가장자리를 돌아 배수로 쪽에 닿았다. 그림자를 불러들였다. 젖어서 무거웠다. 물을 짜듯 그림자를 털었다.`,
      ng:`그림자가 빈 레인에 내려가자 다른 그림자들이 그림자 다리를 잡는다. 같이 돌자고.<br><br>그림자가 끌려 레인을 돈다. 물가에 엎드린 이쪽 몸도 물 쪽으로 미끄러진다.<br>일행이 다리를 붙잡았다. 그림자를 거둬들였을 때 그림자 발목에 손자국이 셋. 이쪽 발목에도.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 마력으로 그림자를 물 위에 다리처럼 깐다.', k:'evade', dc:23, cost:{ mana:30 },
      ok:`일행 그림자를 모아 꼬았다. 물 위로 길게 폈다. 그림자 다리.<br><br>물 위 그림자는 물 밑 것과 안 섞인다. 그 위를 한 사람씩 건넜다. 발밑으로 수영모 그림자들이 지나간다. 위를 안 본다.<br>다 건너고 그림자를 풀어 각자 발에 돌려줬다. 하나도 안 젖었다.`,
      ng:`다리가 반쯤에서 가라앉았다. 그림자가 물을 먹었다.<br><br>밑의 그림자들이 다리를 타고 올라온다. 일행 그림자에 붙는다. 일행 발이 물 쪽으로 미끄러진다.<br>다리를 끊고 다들 헤엄쳐 건넜다. 물이 맑아서 더 차다. 몸이 오래 떨렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'③ 레인 줄을 붙잡고 그림자 흐름을 거슬러 건넌다.', k:'steady', dc:22,
      ok:`빈 레인 줄을 붙잡고 물에 들어갔다. 줄을 따라 손을 옮긴다.<br><br>그림자들이 레인을 돌다 이쪽 아래를 지난다. 줄을 놓지 않으면 끌려가지 않는다. 그림자 흐름이 다리를 당긴다. 버텼다.<br>건너편에 닿았다. 손바닥이 줄에 쓸려 벌갰다.`,
      ng:`반쯤에서 줄이 출렁였다. 다른 레인 줄과 이어져 있다. 저쪽 끝에서 누가 당긴다.<br><br>손이 미끄러졌다. 그림자 흐름에 다리가 휩쓸린다. 레인을 따라 반 바퀴 돌았다.<br>일행이 던진 줄을 잡고 나왔다. 물을 많이 먹었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A', t:'벽 — 타 붙은 그림자',
  x:`복도 벽에 그림자가 붙어 있다. 사람 그림자. 빛이 없는데 진다.<br><br>
    여럿이다. 다 벽에 손을 대고 있다. 뒤를 돌아보는 모양으로. 무엇에게 끌려가던 순간의 모양이다.<br>
    끌려간 사람은 없다. 그림자만 남았다.<br><br>
    하나가 손을 움직인다. 아주 조금. 이쪽으로.`,
  o:[
    { l:'① 움직인 그림자 손을 제 그림자로 잡아 준다.', k:'bond', dc:23, wake:1,
      ok:`제 그림자 손을 벽 위로 뻗었다. 그 그림자 손에 닿았다. 깍지를 꼈다.<br><br>그림자가 벽에서 조금 떨어진다. 붙들려 있던 데서 풀린다. 그림자가 이쪽 그림자에 기대 벽을 따라 걷는다. 복도 끝까지.<br>복도 끝에서 그림자가 손을 놓는다. 바닥에 스며든다. 그 자리에 젖은 신발 한 짝이 놓여 있다. 끌려간 사람 것이다. 신발 속에 쪽지가 있다. 아래층 문은 열려 있다고.<br><br>남겨진 그림자를 놓아주는 법. 그림자를 묶던 손이 푸는 손도 되었다.`,
      ng:`잡았더니 그림자가 놓지 않는다. 끌려가던 순간 그대로 힘을 준다. 뒤로.<br><br>이쪽 그림자가 그 그림자와 같이 끌려간다. 벽을 따라 복도 끝 어둠 쪽으로. 발이 따라간다.<br>그림자 손을 끊었다. 끊긴 데서 이쪽 그림자 손가락 하나가 짧아졌다. 진짜 손가락이 한참 저렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 그림자들 자세로 끌어간 쪽을 읽는다.', k:'gaze', dc:22,
      ok:`그림자마다 돌아본 방향을 봤다. 다 같은 데를 본다. 복도 왼쪽 천장. 환기구.<br><br>끌려간 쪽이 아니라 끌어간 쪽을 본 것이다. 끌어간 것은 위에서 왔다.<br>일행을 환기구 아래에서 비켜 세웠다. 벽에 바짝 붙어 지났다. 환기구 덮개가 지나는 동안 조금씩 열렸다 닫혔다.`,
      ng:`읽다가 그림자 하나와 눈이 맞았다. 그림자에는 눈이 없는데.<br><br>그 그림자가 이쪽 그림자 쪽으로 돌아본다. 끌려가던 그 표정을 이쪽 그림자에게 옮긴다. 이쪽 그림자가 뒤를 돌아보는 모양이 된다.<br>몸이 저절로 뒤를 돌아봤다. 아무것도 없었다. 그 뒤로 한참 목이 그쪽으로 굳었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 먼저 눕는 그림자',
  x:`쉴 자리를 찾았다. 일행이 벽에 기댄다.<br><br>
    일행 그림자가 먼저 눕는다. 사람들은 아직 앉아 있는데. 그림자들이 바닥에 길게 눕는다. 다 같은 쪽을 향해. 문 쪽이다.<br>
    그림자는 주인보다 먼저 움직인다. 먼저 잠든다. 그리고 먼저 일어나 나간다.<br><br>
    문 밑 틈이 그림자들 머리맡에 있다. 틈이 숨을 쉰다.`,
  o:[
    { l:'① 마력으로 그림자들을 일으켜 문 앞에 벽처럼 세운다.', k:'steady', dc:23, cost:{ mana:28 },
      ok:`손을 들어 누운 그림자들을 하나씩 일으켰다. 마력으로 발목을 묶어 세웠다. 문 앞에 나란히.<br><br>그림자 벽이 문을 막는다. 문 밑 틈에서 무엇이 그림자를 핥는다. 그림자들이 버틴다. 서 있는 것은 쉽게 끌려가지 않는다.<br>밤새 그림자들을 세워 두었다. 아침에 그림자들이 지쳐 주인 발로 돌아왔다. 주인들은 푹 잤다.`,
      ng:`일으키는데 그림자들이 다시 눕는다. 문 쪽으로 더 가까이.<br><br>문 밑 틈이 그림자 머리를 하나씩 문다. 일행이 잠결에 앓는다. 이쪽이 그림자들 발목을 붙잡고 버텼다.<br>날이 샐 때까지 버텼다. 팔이 그림자에 쓸려 검게 멍들었다.`,
      win:{ exp:20, dream:2, mind:6 }, lose:{ hp:-26, mind:-20 } },
    { l:'② 그림자들이 향한 문 너머를 먼저 살핀다.', k:'sense', dc:22,
      ok:`문 밑 틈에 귀를 대지 않았다. 손가락 그림자만 틈 너머로 밀어 넣었다.<br><br>그림자 끝이 느낀다. 차가운 물. 그리고 작은 손이 여럿. 손바닥을 위로 펴고 기다린다. 그림자를 받으려고.<br>쉬는 자리를 옮겼다. 문에서 먼 데로. 그림자들이 반대쪽을 향해 누웠다. 그쪽에는 아무것도 없었다.`,
      ng:`밀어 넣은 그림자 끝을 작은 손이 잡았다. 당긴다.<br><br>손가락이 문 쪽으로 꺾인다. 그림자를 끊으려는데 손이 더 많아진다.<br>손가락 그림자를 버리고 손을 뺐다. 손가락 끝이 하얗게 얼었다. 그림자가 다시 자라는 데 하룻밤이 걸렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A1', t:'부조정실 — 화면 속 그림자',
  x:`모니터 하나가 이 방을 비춘다. 부조정실. 일행 다섯이 화면 속에 서 있다. 뒤에서 찍은 모습이다.<br><br>
    화면 속 그림자가 이상하다. 다섯 그림자가 다 카메라 쪽으로 뻗는다. 조명은 반대편인데.<br>
    화면 속 그림자 하나가 길어진다. 화면 가장자리까지. 화면 밖으로 넘어오려 한다.<br><br>
    그림자술사의 진짜 그림자가 발밑에서 당겨진다. 화면 쪽으로.`,
  o:[
    { l:'① 마력을 실어 화면 속 그림자를 화면째 끊는다.', k:'break', dc:23,
      doom:{ title:'화면 속 그림자', what:'그림자째 화면 속으로 빨려 들어갑니다', dc:18, sec:45,
        text:`손에 마력을 모아 화면을 쳤다. 화면 속 이쪽 그림자 위를.<br><br>화면이 깨지지 않는다. 손이 화면에 닿자 화면 속 그림자가 이쪽 손 그림자를 잡는다. 화면 안에서.<br>손이 화면 속으로 들어간다. 유리가 물처럼 받는다. 팔꿈치까지.<br><br>화면 속 이쪽이 돌아본다. 화면 밖 이쪽을. 웃는다. 그림자를 쥐고 당긴다. 어깨가 화면에 닿는다. 화면 속 부조정실이 차갑다.`,
        dieText:`모니터 속 부조정실에 여섯이 서 있다. 하나는 카메라를 본다.<br><br>화면 밖 부조정실에는 다섯이 있다.<br>화면 속 여섯째의 그림자만 카메라 반대쪽으로 진다. 제대로.` },
      ok:`치기 전에 화면 속 그림자 끝을 봤다. 화면 가장자리에 닿은 끝이 손 모양이다. 쥐려고 기다리는 손.<br><br>치지 않았다. 대신 발밑 그림자를 접어 발 안쪽으로 넣었다. 화면 쪽으로 당길 끝이 없다.<br>화면 속 그림자 손이 허공을 쥔다. 그리고 화면 속 이쪽이 천천히 돌아본다. 찾는다. 못 찾는다.<br><br>모니터 선을 뽑고 나왔다. 화면이 꺼지기 직전에 화면 속 이쪽이 입 모양으로 말했다. 다음에.`,
      win:{ exp:22, dream:3 } },
    { l:'② 화면 앞에 다른 그림자를 세워 카메라를 가린다.', k:'hide', dc:22,
      ok:`조정판 위 의자 그림자를 떼어 세웠다. 사람 모양으로 접어 카메라 앞에.<br><br>화면 속에 의자 그림자가 크게 찬다. 일행이 가려진다. 화면 속 그림자들이 의자 그림자를 붙든다. 그건 의자다. 끌려가도 아무도 안 아프다.<br>의자 그림자가 화면 속으로 빨려 들어갔다. 진짜 의자가 바닥에 털썩 넘어졌다. 그사이 부조정실을 나왔다.`,
      ng:`세웠는데 카메라가 의자 그림자를 피해 돈다. 이쪽을 찾는다.<br><br>화면 속에 이쪽이 크게 뜬다. 그림자가 화면 가장자리를 넘는다. 발목이 화면 쪽으로 끌린다.<br>조정판 다리를 붙잡고 버텼다. 카메라 선을 일행이 뽑아 줄 때까지. 발목에 손자국이 검게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-24 } }
  ] },

{ at:'A2', t:'강당 — 무대 커튼 뒤 불',
  x:`강당 무대에 붉은 커튼이 쳐졌다. 커튼 뒤에서 불이 켜져 있다. 물에 잠긴 무대인데.<br><br>
    커튼에 그림자가 비친다. 손들이다. 커튼 뒤에서 커튼 쪽으로 손바닥을 대고 있다. 수십 개.<br>
    커튼 밑자락이 물 위에 떠 있다. 그 아래로 지나가야 무대 뒤로 간다.<br><br>
    커튼에 비친 손 그림자가 일행이 다가가면 그쪽으로 모인다.`,
  o:[
    { l:'① 커튼에 비친 손 그림자들을 손으로 접어 한쪽에 몬다.', k:'hide', dc:23, wake:1,
      ok:`커튼 앞에 서서 손 그림자 끝을 하나씩 잡았다. 접었다. 접힌 그림자를 커튼 왼쪽 끝으로 밀었다.<br><br>그림자가 몰리면 커튼 뒤 손들도 몰린다. 손은 제 그림자를 따라간다. 그림자를 부리면 주인도 부린다.<br>커튼 오른쪽이 비었다. 그 밑으로 일행이 지났다. 왼쪽 끝에서 손들이 커튼을 오래 쥐고 있었다.<br><br>그림자를 몰아 주인을 모는 법. 남의 그림자를 옮기면 남의 몸이 옮겨진다. 그림자가 끈이 되고 손이 끈을 쥐었다.`,
      ng:`접다가 손 그림자 하나가 이쪽 손 그림자를 쥐었다. 커튼 위에서.<br><br>커튼 너머에서 진짜 손이 커튼째 이쪽 손을 쥔다. 젖은 천 너머로. 당긴다. 커튼 쪽으로.<br>천을 찢고 손을 뺐다. 손등에 손가락 자국이 넷. 커튼에 찢긴 구멍으로 손들이 내다봤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 마력으로 커튼 뒤 불을 꺼 그림자를 없앤다.', k:'fix', dc:23, cost:{ mana:30 },
      ok:`커튼 틈으로 마력을 한 줄 밀어 넣었다. 불빛이 나오는 데까지. 눌렀다.<br><br>불이 꺼진다. 커튼에서 손 그림자들이 다 지워진다. 커튼 뒤에서 손들이 갑자기 앞을 못 보는 듯 허둥댄다.<br>그 틈에 밑자락 아래로 지났다. 손들은 서로의 손을 잡고 있었다.`,
      ng:`불을 누르는데 불이 커진다. 커튼 전체가 밝아진다. 손 그림자가 또렷해진다.<br><br>그림자 손 하나하나가 이쪽을 가리킨다. 커튼 뒤에서 손들이 커튼을 밀고 나온다. 커튼이 부풀어 이쪽을 덮친다.<br>물속으로 잠겨 겨우 빠졌다. 마력이 다 새어 손끝이 저렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-18 } },
    { l:'③ 커튼 밑자락의 발 그림자를 센다.', k:'sense', dc:22,
      ok:`커튼 밑 물에 발 그림자가 비친다. 손 그림자보다 적다. 손은 수십인데 발은 넷.<br><br>손이 많은 것은 둘이다. 무대 양쪽 끝에 하나씩. 가운데는 발이 없다.<br>가운데로 지났다. 손들이 커튼 양 끝에서 허우적거렸다. 가운데까지 닿지 않았다.`,
      ng:`세다가 발 그림자가 늘어난다. 셀수록. 넷, 여덟, 열여섯.<br><br>다 이쪽 쪽으로 발끝을 돌린다. 커튼 밑에서 발들이 걸어 나온다. 물 밑으로.<br>뒤로 물러서다 무대 턱에 정강이를 찧었다. 뼈가 울렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'A', t:'복도 — 끌려가는 그림자',
  x:`걷는데 그림자가 늦는다. 이쪽은 앞으로 가는데 그림자는 뒤로 늘어진다.<br><br>
    늘어진 그림자 끝을 무엇이 쥐었다. 복도 뒤쪽 어둠에서.<br>
    천천히 당긴다. 그림자가 길어진다. 발목이 무거워진다.<br><br>
    이쪽은 그림자를 버릴 수 있다. 버린 그림자는 다시 자란다. 오래 걸린다. 그동안은 아무것도 부리지 못한다.`,
  o:[
    { l:'① 그림자를 끊어 내주고 빈 몸으로 걷는다.', k:'steady', dc:22,
      ok:`발꿈치에서 그림자를 끊었다. 살갗을 뜯는 것처럼 아프다. 놓았다.<br><br>그림자가 어둠 속으로 쑥 끌려간다. 저쪽에서 무엇이 그림자를 받아 들고 만족한 소리를 낸다.<br>그림자 없이 걸었다. 몸이 가볍고 춥다. 다음 쉬는 자리까지 그림자는 손톱만큼 자랐다. 그래도 끌려가지는 않았다.`,
      ng:`끊었는데 다 안 끊겼다. 실 한 가닥만큼 남았다.<br><br>그 한 가닥으로 저쪽이 당긴다. 가늘어서 더 아프다. 발목 힘줄이 당겨진다.<br>손톱으로 그 가닥을 마저 끊었다. 발목이 퉁퉁 부었다. 한동안 절뚝였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 그림자를 붙잡고 끝까지 끌어당긴다.', k:'hide', dc:23,
      doom:{ title:'그림자 끝', what:'그림자를 붙든 채 어둠 속으로 끌려갑니다', dc:18, sec:45,
        text:`그림자를 두 손으로 붙들고 당겼다. 그림자가 팽팽하다. 저쪽도 당긴다.<br><br>저쪽 힘이 세다. 그림자가 이쪽 손에서 미끄러진다. 놓지 않았다. 그림자는 이쪽 것이다.<br>그림자 끝을 쥔 것이 어둠에서 나온다. 손만. 팔이 길다. 그림자를 감아 올리듯 한 손씩 당긴다. 이쪽이 그림자째 감겨 간다.<br><br>발이 바닥에서 미끄러진다. 그림자를 놓으면 산다. 손이 안 펴진다. 그림자와 손이 붙었다.`,
        dieText:`복도에 그림자가 하나 남았다. 주인 없이 바닥에 누워 있다.<br><br>그림자 손이 무엇을 꽉 쥔 모양이다.<br>어둠 쪽에서 아주 천천히 그 그림자도 감겨 들어갔다.` },
      ok:`당기기 전에 그림자 끝을 봤다. 쥔 손이 그림자를 감고 있다. 실패에 실 감듯.<br><br>당기면 감긴다. 반대로 했다. 그림자를 풀어 줬다. 길게, 더 길게. 저쪽 손이 감을 실이 너무 많아진다. 엉킨다.<br>엉킨 틈에 그림자 끝을 손으로 잘랐다. 저쪽에 엉킨 실뭉치만 남았다. 이쪽 그림자는 짧아졌지만 이쪽에 붙어 있다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'문 — 틈으로 새는 빛',
  x:`문 밑 틈으로 빛이 샌다. 노랗다. 따뜻해 보인다.<br><br>
    빛 쪽으로 이쪽 그림자가 기운다. 원래 그림자는 빛 반대쪽으로 진다. 이건 빛 쪽으로 진다. 문틈으로 들어가려 한다.<br>
    그림자가 먼저 가고 싶어 한다. 저쪽에 무엇이 있는지 안다는 듯이.<br><br>
    그림자를 먼저 보내면 무엇이 있는지 알 수 있다. 그림자가 돌아온다면.`,
  o:[
    { l:'① 마력으로 그림자 끝만 문틈 너머로 보내 본다.', k:'sense', dc:22, cost:{ mana:28 },
      ok:`그림자 끝을 손가락 하나 너비로 가늘게 뽑았다. 마력으로 쥔 채 틈 너머로 밀었다.<br><br>그림자 끝이 느낀다. 따뜻하다. 불이 아니다. 사람 체온이다. 여럿. 문 바로 앞에 빼곡히 서 있다. 빛은 그들이 들고 있는 작은 등불이다.<br>그림자 끝을 거뒀다. 문을 열지 않았다. 문 너머에서 등불들이 한참 기다리다가 하나씩 꺼졌다.`,
      ng:`밀어 넣은 그림자 끝을 따뜻한 손이 쥐었다. 따뜻하다. 그래서 늦게 놓쳤다.<br><br>손이 그림자를 당긴다. 그림자가 문틈으로 줄줄이 빨려 든다. 발목까지 문틈에 닿았다.<br>그림자를 끊었다. 다리가 문짝에 부딪쳐 무릎이 깨졌다. 문틈의 빛이 웃는 듯 흔들렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 그림자를 발에 꽉 붙이고 문을 연다.', k:'break', dc:23,
      ok:`그림자 끝을 발로 밟아 붙들었다. 문을 확 열었다.<br><br>빛이 쏟아진다. 문 너머는 빈방이다. 천장에 전구 하나. 바닥에 그림자들이 빼곡히 누웠다. 주인 없이. 다 문 쪽을 향해.<br>이쪽 그림자를 기다리던 자리가 맨 앞에 비어 있다. 문을 닫았다. 다른 길로 갔다.`,
      ng:`열었는데 빛이 이쪽 그림자를 발밑에서 지운다. 빛이 너무 세다.<br><br>그림자가 없어진 발이 미끄러진다. 방 안 바닥의 그림자들이 이쪽 발을 붙든다. 빈자리로.<br>문틀을 붙잡고 몸을 뺐다. 손톱이 문틀에 박혀 깨졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'깊은 곳 — 그림자로 된 것',
  x:`넓은 방이다. 불 하나 없다. 그런데 방 한가운데 그것이 보인다. 어둠보다 진하다.<br><br>
    그것은 그림자다. 몸이 없는 그림자. 일어서 있다. 크다.<br>
    그것이 팔을 뻗을 때마다 일행 그림자가 끌려간다. 하나씩.<br><br>
    이쪽은 그림자를 겹치면 짙어진다는 걸 안다. 저것은 수백 겹이다.`,
  o:[
    { l:'① 제 그림자를 그것 위에 겹쳐 그것의 걸음을 묶는다.', k:'hide', dc:24, wake:1,
      ok:`제 그림자를 바닥에서 들어 올렸다. 한 겹. 일행이 내준 그림자를 겹쳤다. 두 겹, 다섯 겹.<br><br>그것의 발밑에 덮었다. 꿰맸다. 그것이 움직이려 한다. 그림자가 안 따라간다. 그림자로 된 것이 그림자에 묶였다.<br>그것이 팔을 뻗다 멈춘다. 일행 그림자가 풀려 주인에게 돌아온다.<br><br>그 사이로 다섯이 지났다. 이쪽은 마지막에 그림자를 거두며 지났다. 수백 겹 앞에서 다섯 겹으로 버티는 법. 겹의 수가 아니라 꿰맨 자리가 묶는다는 걸 알았다.`,
      ng:`겹치는 중에 그것이 이쪽 그림자를 먹었다. 겹이 하나 늘었다. 그것 쪽에.<br><br>그림자를 잃은 발이 바닥에 안 붙는다. 그것이 팔을 뻗는다. 몸이 떠서 끌려간다.<br>일행이 다리를 붙잡아 끌어냈다. 그림자는 조금만 돌아왔다. 한참 서 있지 못했다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-28 } },
    { l:'② 마력을 다 쏟아 빛을 켜 그것을 줄인다.', k:'break', dc:24, cost:{ mana:34 },
      ok:`손바닥에 마력을 다 모았다. 불을 켰다. 작은 불이 아니다. 방 전체를 비출 만큼.<br><br>그것이 줄어든다. 빛이 세면 그림자는 짧아진다. 그것이 벽 쪽으로 밀려난다. 사람 키가 됐다. 아이 키가 됐다.<br>손바닥만 해졌을 때 불을 껐다. 다시 커지기 전에 일행이 다 지났다. 마력이 바닥나 한참 앞이 노랬다.`,
      ng:`불을 켰는데 빛이 그것에 먹힌다. 빛이 닿는 데마다 그것이 진해진다.<br><br>불이 꺼졌다. 그것이 전보다 크다. 팔이 이쪽을 감는다. 차고 무게가 없다. 그런데 무겁다.<br>일행이 이쪽을 끌어냈다. 몸 한쪽이 얼음처럼 식었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-38, mind:-18 } },
    { l:'③ 일행을 그것의 발밑 그림자 속으로 이끌어 지난다.', k:'bond', dc:23,
      ok:`그림자로 된 것도 발밑이 있다. 제일 짙은 데. 제 발밑은 아무도 안 본다.<br><br>일행 손을 하나씩 잡고 그 짙은 데로 들어갔다. 그것이 머리 위에 있다. 팔을 뻗는다. 앞쪽으로. 발밑은 안 본다.<br>반대편으로 빠져나왔다. 다섯 다 그림자가 그대로 붙어 있었다.`,
      ng:`발밑에서 하나가 넘어졌다. 그것이 고개를 숙인다. 처음으로 제 발밑을 본다.<br><br>그림자 손이 넘어진 사람 그림자를 쥔다. 이쪽이 대신 붙들었다. 둘이 같이 끌려가다 벽을 붙잡았다.<br>빠져나왔을 때 이쪽 그림자가 반쯤 찢겨 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-30, spirit:-24 } }
  ] }

]);

// ── 첩자 (agent) · 자원 없음 ──
kJob('agent', 'A', [

{ at:'A', t:'복도 — 여러 이름',
  x:`복도 끝에서 누가 부른다. 이쪽 이름이다. 진짜 이름.<br><br>
    첩자에게 이름은 여럿이다. 장부마다, 도시마다, 문마다 다른 이름을 썼다. 진짜 이름은 오래 안 썼다. 입에 올린 적도 없다.<br>
    그런데 저쪽이 그걸 안다. 또박또박 부른다. 그리고 다른 이름들도. 하나씩. 쓴 순서대로.<br><br>
    이름이 여럿이면 하나쯤 잃어도 된다. 어느 하나에라도 대답하면 끈이 된다.`,
  o:[
    { l:'① 오래전 버린 가짜 이름 하나를 던져 준다.', k:'hide', dc:22, wake:1,
      ok:`대답하지 않았다. 대신 벽에 분필로 이름 하나를 적었다. 십 년 전 항구에서 쓰던 이름. 그 이름으로 진 빚은 다 갚았다. 쓸모가 끝난 이름이다.<br><br>부르던 목소리가 멈춘다. 벽 쪽으로 온다. 이름을 읽는다. 그 이름을 부른다. 벽이 대답하지 않는다. 그래도 목소리는 그 이름을 쥐고 놓지 않는다.<br>그 이름을 붙든 채 목소리가 벽 앞에 머물렀다. 그사이 지나갔다.<br><br>이름을 미끼로 주는 법. 버린 이름에도 쓸모가 남아 있다. 여럿인 이름이 짐이 아니라 연장이 되었다.`,
      ng:`분필을 들었는데 손이 진짜 이름을 쓰기 시작한다. 첫 자까지 썼다.<br><br>목소리가 웃는다. 다 썼으면 좋겠다고. 첫 자를 지웠다. 손바닥으로. 손바닥에 그 자가 거꾸로 묻었다.<br>복도를 빠져나올 때까지 손바닥의 그 자가 따뜻했다. 누가 쥐고 있는 것처럼.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 아무 이름에도 대답 않고 부르는 쪽을 엿듣는다.', k:'sense', dc:22,
      ok:`숨을 죽이고 들었다. 목소리가 이름을 부르는 사이사이 다른 소리가 섞인다. 종이 넘기는 소리.<br><br>저쪽은 읽는 것이다. 이쪽이 쓴 이름들을 적은 무엇을. 장부다. 누가 이쪽 뒤를 오래 밟아 적었다.<br>장부는 순서대로 읽힌다. 마지막 이름이 불리기 전에 복도를 지났다. 그 이름은 아직 아무 데도 안 쓴 이름이다.`,
      ng:`엿듣는데 종이 넘기는 소리가 멎었다. 목소리가 이쪽을 향한다. 듣고 있구나.<br><br>그리고 이쪽이 지금 속으로 생각한 이름을 부른다. 아직 안 쓴 이름이다. 쓸 생각만 한 이름.<br>머리를 감싸 쥐었다. 그 이름은 다시는 못 쓴다. 한참 속이 울렁거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
    { l:'③ 일행 입을 하나씩 막고 손짓으로 지난다.', k:'bond', dc:22,
      ok:`목소리가 일행 이름도 부르기 시작했다. 손가락을 입에 대 보이고 하나씩 어깨를 짚었다.<br><br>손짓으로 말했다. 대답 금지. 고개 끄덕임도 금지. 다섯이 다 따랐다. 복도를 빠져나오는 동안 아무도 입을 안 열었다.<br>목소리는 끝까지 불렀다. 이름이 다섯이 아니라 여섯이었다. 여섯째는 아무도 모르는 이름이었다.`,
      ng:`하나가 고개를 끄덕였다. 아주 작게. 제 이름이 불렸을 때.<br><br>그 사람 걸음이 목소리 쪽으로 기운다. 붙잡았다. 둘이 같이 끌린다. 끄덕임도 대답이었다.<br>벽 모서리를 잡고 버텼다. 목소리가 다른 이름으로 넘어가서야 풀렸다. 팔이 저렸다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A1', t:'접수처 — 직원 명단',
  x:`접수대 위 명단은 방청객 명단이다. 크레용 글씨. 그 밑에 한 권이 더 있다. 직원 출입 명단.<br><br>
    이쪽은 늘 아래 명단을 본다. 위에 펼쳐 둔 것은 보라고 둔 것이다.<br>
    커튼 밑으로 갈색 털 발이 보인다. 발끝이 접수대를 향한다.<br><br>
    직원 명단에는 출입 시각이 적혀 있다. 마지막 칸이 비었다. 아직 퇴근 안 한 사람이 있다.`,
  o:[
    { l:'① 직원 명단에 가짜 출근 줄을 적어 넣는다.', k:'hide', dc:22, wake:1,
      ok:`볼펜을 들지 않았다. 줄이 바닥까지 늘어져 소리가 난다. 품에서 몽당연필을 꺼냈다.<br><br>마지막 줄 밑에 한 줄을 적었다. 소품부. 이름은 그럴듯한 성씨 하나. 출근 시각은 오후 네 시 사십 분.<br>커튼 밑 발이 접수대 쪽으로 한 걸음 나왔다가 멈춘다. 직원은 데려가지 않는다. 직원은 일을 하러 온 사람이다.<br><br>남의 장부에 한 줄을 끼우는 손. 판에 끼어들려면 판의 서류부터 고친다. 이쪽 줄이 이 건물 안에서 통하기 시작했다.`,
      ng:`적는데 연필 끝이 부러졌다. 소리는 작았다.<br><br>커튼이 조금 열린다. 단추 눈 하나가 내다본다. 명단을 본다. 이쪽 줄을 본다. 글씨가 직원 글씨가 아니다.<br>단추 눈이 이쪽 얼굴로 옮겨 왔다. 오래. 뒷걸음질로 빠져나오는 동안 무릎이 접수대 모서리에 몇 번이나 부딪쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 직원 명단 끝 장에서 퇴근 못 한 사람을 찾는다.', k:'gaze', dc:22,
      ok:`끝 장을 넘겼다. 이름 하나에 출근 시각만 있고 퇴근 칸이 비었다. 송출 담당.<br><br>그 줄 옆에 볼펜으로 눌러 쓴 메모. 7층. 소금. 끊지 마.<br>송출 담당은 아직 위에 있다. 무엇을 지키며. 메모를 외워 두었다. 장부를 덮어 원래대로 두었다.`,
      ng:`끝 장 퇴근 칸이 하나씩 채워진다. 이쪽이 보는 동안. 크레용 글씨로.<br><br>퇴근. 퇴근. 퇴근. 이름 옆에 해님 도장이 찍힌다. 재입장 도장이다.<br>손등이 따끔하다. 이쪽 손등에도 도장 자국이 희미하게 떠오른다. 문질러도 안 지워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'나선 계단 — 결석생 부르기',
  x:`밤 아홉 시 점호다. 물 밑에서 이름이 올라온다. 대답이 따라온다.<br><br>
    3학년 2반 17번. 대답이 없다. 다시. 없다.<br>
    물 밑에서 열쇠 꾸러미 소리가 난다. 찰랑. 찾으러 가는 소리. 계단을 올라온다.<br><br>
    이쪽은 목소리를 흉내 낸다. 남의 대답도, 남의 보고도.`,
  o:[
    { l:'① 사감 목소리를 흉내 내 이상 없음이라고 보고한다.', k:'hide', dc:23,
      ok:`물 밑 목소리를 오래 들었다. 끝을 내리는 버릇. 숫자를 끊어 읽는 박자.<br><br>그 박자로 낮게 말했다. 3학년 2반 17번, 양호실. 이상 없음.<br>열쇠 소리가 멈춘다. 한참. 그러다 다시 내려간다. 사감은 사감 목소리를 믿는다. 제 목소리니까.<br><br>점호가 이어졌다. 계단 밑 물이 다시 잔잔해졌다.`,
      ng:`흉내 냈는데 끝을 올렸다. 사감은 끝을 내린다.<br><br>열쇠 소리가 빨라진다. 계단을 오른다. 물에서 검은 치맛단이 올라온다.<br>층계참 뒤로 숨었다. 바로 옆을 열쇠 소리가 지나갔다. 찬 바람에 뺨이 얼었다. 사감은 다른 층으로 갔다. 이쪽 목소리를 찾아서.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 결석생 대신 대답해 수색을 멈춘다.', k:'bond', dc:23,
      doom:{ title:'대리 출석', what:'대답이 받아들여져 물 밑 자리로 끌려갑니다', dc:18, sec:50,
        text:`아이 목소리를 지어 냈다. 작고 또박또박하게. 네.<br><br>열쇠 소리가 멈춘다. 물 밑 목소리가 다정해진다. 거기 있었구나.<br>발밑 계단 물이 차오른다. 무릎, 허리. 대답한 자리로 물이 온다. 출석한 학생은 자리에 앉아야 한다.<br><br>작은 손들이 양옆에서 이쪽 손목을 잡는다. 같은 반 친구들이다. 자리로 데려간다. 계단 아래로. 한 칸씩.`,
        dieText:`점호가 끝났다. 재적 212. 출석 212.<br><br>계단 아래 물속, 3학년 2반 17번 자리에 누가 앉았다. 키가 크다.<br>명찰 이름은 다른 아이 이름이다. 아무도 고쳐 주지 않았다.` },
      ok:`대답하려다 입을 다물었다. 대답은 이름에게 하는 것이다. 이름이 다르면 자리도 다르다. 남의 자리에 앉게 된다.<br><br>대신 계단 위쪽으로 돌을 하나 굴렸다. 툭, 툭. 아이가 도망가는 소리.<br>열쇠 소리가 그 소리를 쫓아 위로 올라갔다. 이쪽은 아래로 내려갔다. 쫓는 쪽과 반대로.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 남이 쓴 줄',
  x:`첩자는 쉴 때 장부를 정리한다. 본 것, 들은 것, 지나온 길. 작은 글씨로.<br><br>
    펼쳤다. 이쪽 글씨 사이에 다른 글씨가 있다. 한 줄씩 끼어 있다.<br>
    이쪽 글씨를 흉내 냈다. 아주 잘. 같은 일을 하는 눈이 아니면 모른다.<br><br>
    끼어 있는 줄들은 다 같은 말을 한다. 다음 길은 왼쪽.`,
  o:[
    { l:'① 끼어든 줄만 골라 읽고 쓴 손의 버릇을 짚는다.', k:'gaze', dc:22, wake:1,
      ok:`끼어든 줄만 따로 읽었다. 획 끝을 봤다. 이쪽은 끝을 꺾는다. 끼어든 줄은 끝을 끈다. 손가락으로 쓴 글씨다. 젖은 손가락.<br><br>왼쪽이 아니라 오른쪽으로 갔다. 왼쪽 길 끝 바닥에 물이 고인 구덩이가 있다는 걸 나중에 알았다. 끼어든 줄이 고른 길이다.<br>장부에 끼어든 줄을 지우지 않았다. 그 옆에 작게 적었다. 젖은 손. 왼쪽.<br><br>남이 이쪽 흉내를 낼 때 어디서 틀리는지 아는 눈. 제 글씨를 아는 사람만 가짜를 가린다. 이쪽 장부가 이쪽을 지키는 법을 배웠다.`,
      ng:`읽다 보니 끼어든 줄이 늘어난다. 읽는 사이에. 이쪽 글씨보다 많아진다.<br><br>어느 것이 이쪽 글씨인지 모르게 됐다. 장부 전체가 왼쪽이라고 한다.<br>장부를 덮었다. 지나온 길을 기억으로 되짚었다. 머리가 깨질 듯 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-22, spirit:-20 } },
    { l:'② 장부에 거짓 길을 적어 읽는 쪽을 속인다.', k:'hide', dc:23,
      ok:`끼어든 줄 밑에 이쪽 글씨로 적었다. 다음 쉬는 자리는 물탱크 뒤. 거기 가지도 않을 거면서.<br><br>밤에 물탱크 쪽에서 무엇이 오래 기다리는 소리가 났다. 물을 헤치며 서성이는 소리.<br>이쪽은 반대편 창고에서 잤다. 장부를 읽는 쪽도 장부를 믿는다.`,
      ng:`거짓을 적는데 펜이 미끄러져 진짜 자리를 적었다. 창고.<br><br>지우려 했다. 지운 자국 위로 젖은 손가락 글씨가 덧쓰인다. 창고. 고마워.<br>잠을 못 잤다. 창고 문 앞에서 밤새 물방울 떨어지는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'분장실 — 남의 얼굴',
  x:`분장실 거울 앞에 분장 도구가 펼쳐져 있다. 분첩, 붓, 빨간 연지, 하얀 분.<br><br>
    벽에 직원 얼굴 사진이 붙어 있다. 무대 감독, 진행자 언니, 소품부. 사진마다 이름.<br>
    이쪽은 얼굴을 빌린다. 직원 얼굴을 쓰면 직원 길로 다닐 수 있다.<br><br>
    거울 속 의자가 하나 더 많다. 그 의자는 비었다.`,
  o:[
    { l:'① 소품부 직원 얼굴을 그려 쓴다.', k:'hide', dc:23,
      doom:{ title:'분장', what:'거울 속 넷째 의자로 끌려가 앉혀집니다', dc:18, sec:50,
        text:`분을 바르고 눈썹을 그렸다. 사진 속 소품부 얼굴로. 잘 그렸다. 거울 속 얼굴이 사진과 같다.<br><br>그런데 거울 속 얼굴이 먼저 웃는다. 이쪽은 안 웃었는데.<br>거울 속 이쪽이 일어선다. 넷째 의자로 간다. 의자를 빼 준다. 앉으라고. 거울 밖 이쪽 다리가 그쪽으로 걸어간다.<br><br>그 얼굴은 빌린 게 아니다. 주인이 있다. 주인이 돌아와 제 얼굴 쓴 몸을 데려간다. 거울에 닿는다. 거울이 물처럼 열린다.`,
        dieText:`분장실 거울 앞 의자가 셋이다. 거울 속 의자는 넷. 넷 다 찼다.<br><br>넷째 의자에 소품부 직원이 앉아 있다. 사진과 같은 얼굴이다. 분이 아직 마르지 않았다.<br>벽 사진 속 얼굴이 조금 다르다. 웃는다.` },
      ok:`붓을 들다가 사진 밑 날짜를 봤다. 소품부 사진 밑에만 날짜에 줄이 그어져 있다. 퇴사가 아니다. 다른 글씨로 적혔다. 실종.<br><br>주인 없는 얼굴은 쓰면 안 된다. 주인이 찾으러 온다. 붓을 내려놓았다.<br>대신 얼굴에 분만 하얗게 발랐다. 아무 얼굴도 아닌 얼굴. 거울 속 넷째 의자가 이쪽 쪽으로 조금 돌다가 멈췄다. 앉을 얼굴이 없다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 사진 이름표로 직원 출입증을 꾸민다.', k:'fix', dc:22,
      ok:`빈 출입증 틀이 서랍에 있다. 사진 하나를 떼어 오려 끼웠다. 무대 감독. 뒷모습 사진이다.<br><br>뒷모습 출입증은 얼굴이 필요 없다. 목에 걸고 등을 보이며 걸었다. 복도 끝 인형탈이 이쪽 등을 보고 비켜 섰다.<br>감독은 늘 등을 보인다. 등만 맞으면 된다.`,
      ng:`출입증을 목에 걸자 줄이 조인다. 목줄이 짧아진다.<br><br>복도에서 헤드셋 낀 것이 이쪽을 돌아본다. 몸만. 뒤통수가 이쪽을 본다. 제 출입증이 남의 목에 걸린 걸 본다.<br>줄을 끊고 출입증을 던졌다. 목에 줄 자국이 빨갛게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'③ 분장 일정표를 읽어 오늘 누가 분장하는지 본다.', k:'gaze', dc:22,
      ok:`거울 옆 일정표를 봤다. 시각과 이름. 오후 네 시 오십오 분. 오늘의 친구. 분장 담당 언니.<br><br>칸이 비었다. 이름 자리에 연필로 물음표. 아직 안 정해졌다.<br>오늘의 친구가 정해지기 전에 이 층을 떠나야 한다. 일정표를 벽에서 떼어 서랍에 넣었다. 일정이 없으면 분장도 늦어진다.`,
      ng:`읽는데 물음표가 지워지고 이름이 적힌다. 이쪽 앞에서. 크레용 글씨로.<br><br>일행 중 하나의 이름이다. 그 사람이 거울 쪽으로 고개를 돌린다. 분첩을 집는다.<br>손목을 붙잡아 끌어냈다. 그 사람 볼에 분이 한 줄 묻었다. 닦아도 하얗게 남았다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'사감실 — 이상 유무 칸',
  x:`사감실 책상 위에 점호 기록부가 펼쳐져 있다. 칸이 셋. 호실, 인원, 이상 유무.<br><br>
    오늘 날짜 줄이 비었다. 오늘 밤 점호가 끝나면 채워질 것이다.<br>
    이 학교에서 서류는 그대로 된다. 기록부에 적힌 인원이 그 방의 인원이 된다.<br><br>
    첩자는 서류를 고쳐 판을 바꾼 적이 많다. 이 서류는 판보다 무겁다.`,
  o:[
    { l:'① 일행이 묵을 호실 줄에 미리 인원 영, 이상 없음을 적는다.', k:'hide', dc:22, wake:1,
      ok:`사감 글씨를 봤다. 반듯하다. 획 끝이 짧다. 그대로 따라 적었다. 415호. 인원 0. 이상 없음.<br><br>빈방에는 점호가 안 간다. 확인할 것이 없으니까.<br>그 밤 열쇠 소리가 복도를 지나갔다. 415호 앞에서 멈추지 않았다. 문 안에서 다섯이 숨을 죽이고 있었다. 아무도 안 셌다.<br><br>사람을 빈칸으로 만드는 글씨. 남의 서류로 남의 눈을 막는 법. 이쪽 손이 이 학교의 장부 안으로 들어갔다.`,
      ng:`적는데 글씨가 번진다. 젖은 종이다. 0 이 6 처럼 보인다.<br><br>그 밤 열쇠 소리가 415호 앞에서 멈췄다. 문이 열린다. 사감이 들어와 센다. 하나, 둘, 셋, 넷, 다섯.<br>여섯. 사감 손가락이 방 구석 빈 데를 가리켰다. 거기 무엇이 섰다. 아침까지 그 구석을 아무도 못 봤다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 벽 열쇠 꼬리표를 바꿔 달아 사감 동선을 엇갈리게 한다.', k:'luck', dc:22,
      ok:`벽에 걸린 열쇠 둘의 꼬리표를 바꿔 달았다. 412호와 강당.<br><br>사감은 꼬리표를 보고 연다. 열쇠는 안 본다. 412호 순서에 강당 열쇠를 들고 간다.<br>복도 끝에서 문이 안 열리는 소리가 오래 났다. 열쇠가 맞지 않는 소리. 그 소리를 등지고 계단으로 내려갔다. 서랍 구석에 봉한 꿀 한 통이 있었다. 같이 챙겼다.`,
      ng:`바꿔 다는데 꼬리표 끈이 손가락에 감긴다. 젖은 끈이다. 조인다.<br><br>꼬리표에 이름이 적혀 있다. 호실 번호 대신. 이쪽 이름이다. 언제 바뀌었는지 모른다.<br>끈을 끊었다. 손가락에 끈 자국이 하얗게 얼었다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'문 — 노크',
  x:`문 저쪽에서 두드린다. 똑, 똑똑, 똑.<br><br>
    신호다. 이쪽은 신호를 안다. 어느 나라 것이든, 어느 패거리 것이든.<br>
    이 신호는 이쪽 패거리 것이다. 오래전에 쓰던. 열어 달라는 뜻. 안전하다는 뜻.<br><br>
    그 신호를 아는 사람은 다섯이었다. 넷은 죽었다. 하나는 이쪽이다.`,
  o:[
    { l:'① 신호의 박자를 끝까지 읽고 엇박으로 답한다.', k:'gaze', dc:22, wake:1,
      ok:`세 번을 더 들었다. 똑, 똑똑, 똑. 세 번째에 똑똑 사이가 아주 조금 길다.<br><br>그건 이쪽 버릇이다. 이쪽이 두드릴 때 생기는 틈이다. 저쪽은 이쪽 노크를 흉내 낸다. 들은 적이 있다. 오래전, 어딘가에서.<br>엇박으로 답했다. 똑똑, 똑. 그 패거리에서 들어오지 말라는 뜻이다. 문 저쪽이 조용해졌다. 그 신호는 모르는 것이다.<br><br>남이 이쪽 신호를 흉내 낼 때 이쪽 버릇까지 따라 한다. 제 버릇을 아는 사람은 가짜를 가린다. 버릇이 열쇠가 되었다.`,
      ng:`읽는데 노크가 바뀐다. 이쪽이 생각하는 대로. 열어 달라, 다쳤다, 빨리.<br><br>이쪽 머릿속을 두드린다. 문이 아니라. 귀를 막아도 들린다.<br>문에서 물러나 다른 길로 가는 동안 노크가 따라왔다. 이마 안쪽에서. 한참 동안.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 같은 노크로 답하고 문을 연다.', k:'bond', dc:23,
      doom:{ title:'옛 신호', what:'문 너머 옛 동료에게 손목을 잡혀 끌려갑니다', dc:18, sec:50,
        text:`똑, 똑똑, 똑. 답했다. 빗장을 풀었다.<br><br>문이 열린다. 사람이 서 있다. 아는 얼굴이다. 넷 중 하나. 오래전에 강에서 건졌다. 그때 그 얼굴 그대로 젖어 있다.<br>왔구나. 손을 내민다. 이쪽 손목을 잡는다. 그때처럼 정확하게, 맥 자리를.<br><br>당긴다. 문 너머로. 그 뒤에 셋이 더 서 있다. 다 젖었다. 다섯째 자리를 비워 두고 있었다.`,
        dieText:`문 저쪽에서 두드린다. 똑, 똑똑, 똑.<br><br>이번엔 똑똑 사이가 아주 조금 길다.<br>그 신호를 아는 사람은 다섯이었다. 다섯 다 문 저쪽에 있다.` },
      ok:`답하기 전에 문 밑 틈을 봤다. 물이 흘러나온다. 이 복도는 마른 복도다.<br><br>답하지 않았다. 대신 빗장에 끈을 매고 멀리서 당겨 열었다. 문이 열린다. 아무도 안 들어온다. 젖은 발자국 넷이 문턱 안쪽에 찍혔다가 천천히 마른다.<br>문을 닫았다. 저쪽에서 다시 노크가 났다. 이번엔 서툴렀다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'갈림길 — 앞선 사람의 표시',
  x:`갈림길 벽에 분필 표시가 있다. 앞선 일행이 남긴 것이다. 첩자들이 쓰는 표시.<br><br>
    동그라미는 물. 세모는 쉴 데. 가위표는 막힘. 화살 끝에 점 셋은 쫓김.<br>
    마지막 표시는 점 셋이 붙은 화살이다. 오른쪽을 가리킨다. 그 뒤로는 표시가 없다.<br><br>
    뒤에서 무엇이 따라온다. 이쪽 발자국을 따라.`,
  o:[
    { l:'① 왼쪽에 거짓 화살을 그리고 이쪽은 표시 없는 길로 간다.', k:'hide', dc:22, wake:1,
      ok:`왼쪽 벽에 화살을 그었다. 그 옆에 세모. 쉴 데가 있다는 뜻. 따라오는 것이 쉬고 싶어 할 표시.<br><br>이쪽은 가운데 틈으로 갔다. 표시가 없는 길. 표시를 아는 것은 표시 없는 길을 길로 안 친다.<br>멀리 왼쪽에서 발소리가 났다. 세모를 찾아가는 소리. 한참 뒤 그쪽에서 무엇이 실망한 소리를 냈다.<br><br>남의 표시 옆에 이쪽 표시를 섞는 법. 읽는 쪽의 습관까지 계산에 넣는 손. 표시를 남기는 사람이 길을 고르는 사람이 됐다.`,
      ng:`화살을 긋는데 분필이 젖었다. 화살이 번진다. 오른쪽으로 흘러내린다.<br><br>번진 화살은 오른쪽을 가리킨다. 점 셋 화살과 같은 쪽.<br>따라오는 것이 이쪽이 간 가운데 틈을 지나쳐 오른쪽으로 갔다. 그런데 얼마 뒤 되돌아왔다. 가운데 틈 앞에서 오래 숨을 쉬었다. 잠을 한숨도 못 잤다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 점 셋 화살 밑에 지워진 표시를 살린다.', k:'gaze', dc:22,
      ok:`화살 밑을 손가락으로 쓸었다. 분필 가루가 아주 얇게 남았다. 지워진 표시다. 누가 지웠다.<br><br>가루 결을 따라 읽었다. 가위표. 오른쪽 막힘. 점 셋 화살은 쫓긴 사람이 그린 게 아니다. 쫓은 것이 그렸다.<br>오른쪽으로 가지 않았다. 왼쪽 길 끝 바위틈에 진짜 동그라미가 있었다. 맑은 물이 고여 있었다.`,
      ng:`쓸다가 지워진 표시 밑에 또 표시가 있다. 그 밑에도. 겹겹이.<br><br>맨 밑 표시는 분필이 아니다. 손톱으로 긁은 것이다. 이쪽 이름 첫 자.<br>읽은 순간 등 뒤 발소리가 빨라졌다. 갈림길을 뛰어 빠져나왔다. 숨이 끊어질 듯했다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A1', t:'방청석 — 머릿수 세는 안내원',
  x:`방청석 통로에 안내원이 서 있다. 모자를 눌러 썼다. 손에 계수기. 딸깍.<br><br>
    줄마다 앉은 머리를 센다. 빈 의자를 세는 것 같은데 딸깍 소리가 난다. 이 방청석에는 보이지 않는 관객이 있다.<br>
    방청석 맨 뒤를 지나야 무대 옆 계단이 나온다. 안내원은 줄 끝에서 늘 뒤를 돌아본다.<br><br>
    계수기 숫자가 맞아야 안내원이 다음 줄로 간다. 머릿수가 늘면 늘어난 머리를 데려간다.`,
  o:[
    { l:'① 외투와 모자로 머리 하나를 꾸며 의자에 앉혀 둔다.', k:'fix', dc:22,
      ok:`외투를 의자 등받이에 걸고 모자를 얹었다. 멀리서 보면 앉은 사람이다.<br><br>안내원이 그 줄을 셌다. 딸깍. 딸깍. 외투 앞에서 딸깍. 한 줄의 숫자가 맞는다. 원래 앉아 있던 하나가 빠진 자리를 외투가 채웠다.<br>빠진 하나는 일행 뒤를 따라오던 무엇이었다. 이제 앉을 데가 없다. 안내원이 그것을 데려갔다. 이쪽은 계단으로 갔다.`,
      ng:`외투를 앉혔는데 안내원이 외투 앞에서 멈춘다. 손전등을 비춘다.<br><br>외투 속이 비었다. 안내원이 고개를 갸웃한다. 비어 있는 손님. 계수기를 되돌린다. 딸깍. 그리고 줄을 다시 센다.<br>이번엔 이쪽을 셌다. 손목을 잡혔다. 뿌리쳐 계단까지 뛰었다. 손목에 차가운 장갑 자국이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 안내원 바로 뒤에 붙어 그 걸음대로 따라간다.', k:'hide', dc:23, wake:1,
      ok:`안내원 등 뒤 한 걸음에 붙었다. 안내원이 서면 섰다. 돌아보면 같이 돌았다. 안내원의 그늘에서.<br><br>세는 쪽은 저 자신을 세지 않는다. 자기 등 뒤도 세지 않는다.<br>맨 뒷줄 끝에서 안내원이 돌아볼 때 같이 돌았다. 계단 앞에서 옆으로 빠졌다. 계수기는 끝까지 맞았다.<br><br>세는 사람의 그늘로 다니는 법. 눈을 피하는 게 아니라 눈의 주인에게 붙는다. 감시하는 쪽이 제일 안 보는 데가 어디인지 알았다.`,
      ng:`붙어 가다 안내원이 갑자기 섰다. 이쪽 발이 반 걸음 더 갔다.<br><br>안내원 등에 이쪽 가슴이 닿았다. 차다. 안내원이 돌아보지 않고 계수기를 누른다. 딸깍. 이쪽을 셌다.<br>손이 뒤로 와서 이쪽 옷깃을 쥐었다. 옷을 벗고 빠졌다. 등에 소름이 한참 가시지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 안내원 허리의 손전등을 슬쩍 빼 온다.', k:'luck', dc:22,
      ok:`안내원이 계수기를 볼 때 허리 손전등을 뺐다. 가볍다. 건전지가 들었다.<br><br>안내원은 손전등이 없으면 맨 뒷줄을 못 본다. 맨 뒷줄로 일행을 지나게 했다.<br>손전등 손잡이에 이름이 긁혀 있다. 안내원 이름이 아니다. 이 방청석에 처음 온 어느 아이 이름이다.`,
      ng:`빼는 순간 손전등이 켜졌다. 이쪽 얼굴로.<br><br>안내원이 돌아본다. 모자 밑에 얼굴이 없다. 계수기만 손에서 딸깍거린다. 하나, 하나, 하나.<br>손전등을 던지고 뛰었다. 눈이 한참 하얗게 탔다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A2', t:'교무실 — 울리는 전화',
  x:`교무실 책상마다 전화기. 물이 턱까지 찼는데 전화가 울린다. 따르릉.<br><br>
    한 대만 울린다. 교감 책상. 수화기 줄이 물에 잠겼다.<br>
    이쪽은 전화를 받는 법을 안다. 받는 쪽이 누구인지 먼저 정하고 받는다.<br><br>
    전화는 학부모 상담 시간에 울린다. 벽 시계는 상담 시간이다.`,
  o:[
    { l:'① 수화기를 들고 교감 목소리를 흉내 낸다.', k:'hide', dc:23,
      doom:{ title:'학부모 상담', what:'수화기 줄에 감겨 물 밑으로 끌려갑니다', dc:18, sec:45,
        text:`수화기를 들었다. 낮고 느리게 말했다. 네, 교감입니다.<br><br>저쪽에서 여자 목소리. 울먹인다. 우리 아이가 아직 안 왔어요. 데리러 가도 되나요.<br>교감이 할 법한 대답을 했다. 학교에서 잘 지냅니다. 저쪽이 조용해진다. 그리고 묻는다. 그럼 선생님은 누구세요.<br><br>대답하기 전에 수화기 줄이 팔을 감는다. 물 밑에서 당긴다. 진짜 교감이 받을 차례다. 가짜는 바꿔 드려야 한다. 물 밑으로.`,
        dieText:`교무실 전화가 다시 울린다. 따르릉.<br><br>이번엔 다른 책상이다. 새 책상. 수화기 줄이 물속에서 길게 늘어졌다.<br>아무도 받지 않는다. 물 밑에서 누가 받는다. 네, 교감입니다. 낮고 느리게.` },
      ok:`수화기를 들기 전에 줄을 따라 봤다. 줄이 전화기에서 나와 물 밑으로 간다. 벽으로 안 간다.<br><br>밖으로 걸리는 전화가 아니다. 물 밑에서 걸려 온다. 받는 사람을 고르는 전화다.<br>수화기를 들되 말하지 않고 책상 위에 눕혀 두었다. 저쪽에서 한참 말이 오갔다. 대답이 없자 끊겼다. 줄이 아쉬운 듯 물 밑으로 거둬졌다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 수화기 줄을 따라 전화가 걸려 오는 데를 찾는다.', k:'sense', dc:22,
      ok:`줄을 손으로 더듬어 따라갔다. 물 밑으로. 책상 밑, 바닥, 벽 틈.<br><br>벽 틈 너머에 작은 방이 있다. 방송실 옆 숙직실. 거기 전화기가 하나 놓였다. 수화기가 내려져 있다. 그 앞에 아무도 없다.<br>숙직실 선반에 마른 수건과 봉한 건빵 상자가 있다. 상자는 열지 않았다. 수건만 챙겼다. 숙직실 문은 바깥에서 잠갔다.`,
      ng:`줄을 따라가다 줄이 손을 감았다. 줄이 이쪽 손을 따라오는 것이다.<br><br>당긴다. 물 밑 벽 틈으로. 틈이 손 하나 너비다. 손이 들어간다. 틈 너머에서 수화기를 귀에 대는 소리가 났다. 여보세요.<br>줄을 끊고 손을 뺐다. 손등이 틈에 긁혀 피가 물에 번졌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A', t:'복도 — 같은 옷',
  x:`복도 앞쪽에 일행이 걸어간다. 다섯. 이쪽 일행과 같은 옷, 같은 짐, 같은 걸음.<br><br>
    이쪽 일행은 이쪽 뒤에 있다. 다섯 다. 돌아보니 다들 얼굴이 굳었다.<br>
    앞의 다섯이 모퉁이에서 멈춘다. 이쪽을 기다린다. 손짓한다. 이리 와, 이쪽이야.<br><br>
    첩자는 남을 흉내 내는 일로 먹고산다. 흉내에는 늘 빈 데가 있다. 그걸 알아서 산다.`,
  o:[
    { l:'① 다섯의 버릇을 하나씩 짚어 빈 데를 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`오래 봤다. 짐 메는 어깨, 머리 긁는 손, 발 끄는 버릇. 다 맞다. 너무 맞다.<br><br>그런데 아무도 숨을 고르지 않는다. 진짜 일행은 걸을 때마다 숨이 다르다. 저 다섯은 숨이 하나다. 한 몸이 다섯 벌 옷을 입은 것이다.<br>손짓을 따라가지 않았다. 반대쪽 길로 갔다. 모퉁이의 다섯이 한꺼번에 고개를 갸웃했다. 같은 각도로.<br><br>흉내의 빈 데는 겉이 아니라 숨에 있다. 사람을 겉으로 읽던 눈이 숨으로 읽게 되었다. 가짜를 가리는 눈금이 하나 늘었다.`,
      ng:`짚다가 어느 쪽이 어느 쪽인지 헷갈렸다. 돌아보니 뒤의 다섯 중 하나가 앞의 다섯처럼 웃고 있다.<br><br>섞였다. 언제부터인지 모른다. 일행 다섯 얼굴을 하나씩 손으로 만져 봤다. 다 따뜻했다. 하나만 덜 따뜻했다.<br>그 하나를 어둠 쪽으로 밀어냈다. 소리 없이 물러났다. 손바닥이 한참 차가웠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 가짜 다섯 틈에 섞여 그들이 가는 데를 엿본다.', k:'hide', dc:23,
      ok:`이쪽 일행을 뒤에 숨겨 두고 혼자 앞의 다섯에게 갔다. 같은 걸음으로.<br><br>다섯이 이쪽을 넣어 여섯이 걷는다. 모퉁이를 돈다. 그들이 가는 데는 계단 아래 물이다. 물 앞에서 다섯이 한 줄로 선다. 들어갈 차례를 기다린다.<br>여섯째로 서 있다가 다섯째가 물에 들어갈 때 뒤로 빠졌다. 물은 다섯만 셌다.`,
      ng:`섞였는데 다섯이 이쪽 쪽으로 돈다. 여섯째는 원래 없었다.<br><br>다섯의 손이 이쪽 어깨를 잡는다. 따뜻하다. 진짜 일행 손처럼. 그래서 늦게 뿌리쳤다.<br>물가까지 끌려가다 벽을 붙잡았다. 손톱이 둘 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A1', t:'탕비실 — 출근 카드',
  x:`5층 탕비실 벽에 출근 카드 꽂이가 있다. 직원마다 카드 한 장. 시각 찍는 기계가 옆에 붙었다.<br><br>
    카드마다 오늘 날짜에 도장이 찍혔다. 오후 네 시 오십 분 출근.<br>
    꽂이 맨 끝에 새 카드가 다섯 장. 이쪽 일행 이름이다. 출근 칸이 비었다.<br><br>
    찍으면 직원이다. 이 건물 직원은 퇴근을 안 한다.`,
  o:[
    { l:'① 다섯 장을 빼고 퇴사한 직원 카드를 대신 꽂는다.', k:'hide', dc:22, wake:1,
      ok:`꽂이 아래 서랍에 오래된 카드 뭉치가 있다. 퇴사. 빨간 도장.<br><br>일행 카드 다섯 장을 빼서 품에 넣었다. 빈자리에 퇴사 카드 다섯 장을 꽂았다. 이름은 다르다. 빨간 도장은 그대로다.<br>꽂이가 조용하다. 다섯 자리가 다 찼다. 찬 자리에는 새 사람이 안 온다.<br><br>남의 서류로 자리를 막는 법. 비어 있으면 누가 채운다. 먼저 채워 두면 아무도 못 채운다. 빈칸을 다루는 손이 하나 더 생겼다.`,
      ng:`카드를 빼는데 시각 기계가 저 혼자 덜컥 움직였다. 이쪽 손에 든 카드에 도장이 찍혔다.<br><br>오후 네 시 오십육 분. 출근.<br>카드를 찢었다. 찢어진 반쪽에도 도장이 있다. 이쪽 손등에도 희미하게. 한참 손이 무거웠다. 일을 하러 가야 할 것 같았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 직원 냉장고에서 쓸 만한 것을 챙긴다.', k:'luck', dc:22,
      ok:`냉장고 문에 이름 쪽지가 붙은 통들. 손대지 마시오. 밑 칸 맨 안쪽에 쪽지 없는 통이 하나.<br><br>쪽지 없는 건 주인이 없는 거다. 열었다. 말린 고기. 비닐이 탱탱하다. 공기가 안 들어갔다.<br>챙겼다. 냉장고 문을 닫을 때 안쪽 칸 통들이 일제히 조금 돌아갔다. 쪽지 쪽이 이쪽으로.`,
      ng:`쪽지 없는 통을 열었다. 안에 쪽지가 들었다. 이름은 이쪽 이름.<br><br>그 밑에 연필 글씨. 내일 도시락.<br>통을 닫고 냉장고를 닫았다. 손이 냉장고 손잡이에 얼어붙었다. 떼는 데 살갗이 벗겨졌다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'매점 — 외상 장부',
  x:`매점 계산대에 외상 장부가 놓였다. 물에 반쯤 잠겼는데 글씨가 안 번진다.<br><br>
    학생 이름과 외상 값. 빵 하나, 우유 하나. 갚은 사람은 줄이 그어졌다.<br>
    줄이 안 그어진 이름은 학교를 못 떠난다. 장부 첫 장에 그렇게 적혀 있다. 매점 규칙.<br><br>
    이쪽은 남의 이름으로 외상을 지는 데 익숙하다. 갚는 일은 덜 익숙하다.`,
  o:[
    { l:'① 없는 이름으로 외상을 달고 물건을 받는다.', k:'hide', dc:22,
      ok:`장부 맨 끝에 적었다. 아무도 아닌 이름. 학년, 반, 번호까지 그럴듯하게. 건빵 한 봉, 물 한 병.<br><br>계산대 밑 진열장 문이 덜컹 열린다. 물이 안 든 칸. 건빵과 병물.<br>받았다. 없는 이름은 학교를 못 떠나도 된다. 처음부터 학교에 없으니까. 장부가 그 줄에서 오래 생각하는 듯 페이지를 들썩였다.`,
      ng:`없는 이름을 적었는데 장부가 그 이름 옆에 사진을 붙인다. 젖은 사진. 이쪽 얼굴이다.<br><br>없는 이름이 이쪽 이름이 된다. 외상 한 줄이 이쪽에게 붙었다.<br>장부에서 그 장을 찢었다. 찢긴 자리에 같은 줄이 다시 떠오른다. 가슴이 무겁게 눌렸다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 일행 이름이 적힌 줄을 찾아 갚음 줄을 그어 둔다.', k:'fix', dc:23,
      ok:`장부를 넘겼다. 맨 뒤에 새 줄이 다섯. 일행 이름. 빵 하나씩. 언제 먹었는지 아무도 모른다.<br><br>매점 펜으로 줄을 그었다. 갚음. 사감 글씨처럼 반듯하게.<br>장부가 조용히 덮였다. 다섯 줄이 장부에서 지워졌다. 학교 문을 나설 때 아무도 붙잡지 않을 것이다.`,
      ng:`줄을 긋는데 펜이 안 나온다. 갚지 않고 그은 줄은 안 그어진다.<br><br>주머니를 뒤졌다. 동전 한 닢. 계산대에 올렸다. 동전이 물에 떨어져 가라앉는다. 값이 모자라다.<br>장부가 한 장 넘어간다. 다섯 줄 옆에 이자가 붙었다. 머리가 울렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 장부 끝장 여백의 메모를 읽는다.', k:'gaze', dc:22,
      ok:`끝장 여백에 연필 글씨가 빼곡하다. 매점 아주머니 글씨. 외상 못 받은 이름들, 그리고 그 옆에 한 줄씩.<br><br>17번 서하람. 외상 없음. 대신 빵 하나 맡겨 둠. 데리러 오면 줄 것.<br>계산대 밑을 봤다. 비닐에 싼 빵 하나가 젖지 않고 있다. 손대지 않았다. 맡긴 사람의 것이다. 메모만 외워 두었다.`,
      ng:`읽는데 메모가 이쪽 쪽으로 기울어진다. 글씨가 바뀐다. 외상 받을 이름들. 맨 밑에 이쪽 이름.<br><br>옆에 적힌다. 받을 것: 하나. 무엇을 하나 받겠다는 것인지 적혀 있지 않다.<br>장부를 덮고 나왔다. 그 하나가 무엇인지 생각하느라 한참 아무 말도 못 했다.`,
      win:{ exp:16, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 바뀌는 명찰',
  x:`쉬고 일어나니 가슴에 명찰이 달려 있다. 단 적 없다. 이름은 이쪽 이름이 아니다.<br><br>
    일행 가슴에도 다 달렸다. 서로 다른 이름. 다 모르는 이름이다.<br>
    명찰 이름대로 몸이 조금씩 바뀐다. 걸음이, 말투가.<br><br>
    누가 밤사이 다섯을 다른 다섯으로 바꾸고 있다. 명찰부터.`,
  o:[
    { l:'① 밤사이 바뀐 명찰을 하나씩 되찾아 단다.', k:'sense', dc:22,
      ok:`잠든 자리를 거꾸로 짚었다. 바닥에 끌린 자국. 명찰을 단 손이 지나간 길이다.<br><br>벽 틈에 원래 명찰들이 꽂혀 있다. 이쪽 일행 이름들. 아니, 일행이 쓰던 이름들. 하나씩 빼서 돌려 달았다.<br>다 달고 나니 걸음과 말투가 돌아왔다. 벽 틈에 남은 낯선 명찰들은 다 버렸다. 버린 데서 한참 바스락거리는 소리가 났다.`,
      ng:`자국을 따라가는데 명찰 다는 손이 아직 거기 있다. 벽 틈에서. 다음 명찰을 고르고 있다.<br><br>손이 이쪽 가슴으로 뻗는다. 명찰을 하나 더 단다. 두 장이 됐다. 두 이름이 서로 이쪽을 끌어당긴다.<br>둘 다 뜯어냈다. 옷이 찢어지고 가슴에 핀 자국이 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 바꿔 다는 손에게 가짜 명찰을 미리 쥐여 준다.', k:'hide', dc:23, wake:1,
      ok:`이쪽 이름 하나를 종이에 적어 가짜 명찰을 만들었다. 버린 이름이다. 품 안쪽, 손이 먼저 닿을 자리에 꽂았다.<br><br>밤에 손이 왔다. 품을 더듬어 그 명찰을 뺐다. 낯선 명찰을 대신 꽂았다. 이쪽 진짜 명찰은 손이 못 찾은 바지 안쪽에 그대로 있다.<br>아침에 낯선 명찰을 떼어 버렸다. 손은 버린 이름 하나를 들고 갔다. 그걸로 다섯 몫인 줄 안다.<br><br>빼앗길 것을 미리 내주는 법. 이름이 여럿이니 하나를 바쳐 나머지를 지킨다. 여럿인 이름이 방패가 되었다.`,
      ng:`가짜 명찰을 꽂았는데 손이 그걸 안 뺐다. 그 위에 하나 더 꽂았다.<br><br>가짜 이름과 낯선 이름이 겹친다. 이쪽이 그 둘 사이에서 누군지 헷갈린다.<br>일행이 이쪽 진짜 이름을 세 번 부르고서야 돌아왔다. 대답하는 데 한참 걸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잠꼬대',
  x:`일행 하나가 잠꼬대를 한다. 또렷하다. 이름, 고향, 동생 이름.<br><br>
    어둠 속에서 다른 목소리가 대답한다. 그렇구나. 더 말해 봐.<br>
    잠꼬대가 이어진다. 묻는 대로 다 말한다. 비밀까지.<br><br>
    이쪽은 안다. 다 털어놓은 사람은 털어놓은 상대 것이 된다. 첩자는 그렇게 사람을 산다.`,
  o:[
    { l:'① 잠꼬대에 끼어들어 대화를 이쪽으로 돌린다.', k:'bond', dc:22,
      ok:`잠든 사람 귀에 대고 낮게 말했다. 거짓 고향, 거짓 동생 이름. 꿈결에 그게 섞인다.<br><br>잠꼬대가 그 거짓을 따라 말한다. 어둠 속 목소리가 거짓을 받아 적는다. 끝까지.<br>아침에 깬 사람은 아무것도 기억하지 못했다. 어둠 쪽에서 무엇이 틀린 주소로 찾아갔을 것이다.`,
      ng:`끼어들었더니 어둠 속 목소리가 이쪽에게 묻는다. 너는? 너는 어디서 왔어?<br><br>입이 열렸다. 대답할 뻔했다. 혀를 깨물어 막았다. 피가 났다.<br>목소리가 웃는다. 다음에. 밤새 이쪽 귀에 대고 같은 걸 물었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-22 } },
    { l:'② 대답하는 목소리가 어디서 나는지 엿듣는다.', k:'sense', dc:22,
      ok:`숨을 죽이고 들었다. 목소리는 잠든 사람 그림자에서 난다. 바닥에서.<br><br>그림자가 귀를 대고 있다. 잠든 사람 입에. 그림자를 손으로 덮었다. 목소리가 멎었다.<br>잠꼬대도 멎었다. 아침까지 아무도 아무 말도 안 했다. 그게 제일 안전한 밤이었다.`,
      ng:`엿듣는데 목소리가 이쪽 쪽으로 돈다. 너도 듣고 있었네.<br><br>그 목소리가 이쪽 비밀을 하나 말한다. 아무도 모르는 것. 정확히.<br>일행 앞에서 그 말이 크게 울렸다. 다들 깨지 않았다. 다행이었다. 가슴이 한참 뛰었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'7층 — 오늘의 친구 이름표',
  x:`7층 복도 끝 탁자에 이름표가 하나 놓였다. 노란 해 모양. 오늘의 친구.<br><br>
    이름 칸이 비었다. 크레용이 옆에 있다.<br>
    스튜디오 안에서 진행자 언니가 말한다. 오늘의 친구는 이름표를 달고 무대로 오세요. 조금 있다가 이름을 불러 줄게요.<br><br>
    이름표를 단 사람이 없으면 언니가 찾으러 나온다. 이쪽은 남의 이름표를 다는 일에 익숙하다.`,
  o:[
    { l:'① 이름표를 복도의 소품 인형 가슴에 달아 둔다.', k:'luck', dc:22,
      ok:`복도 구석에 소품 인형이 하나 앉아 있다. 사람 크기. 솜 얼굴. 그 가슴에 이름표를 달았다. 이름 칸은 비워 둔 채.<br><br>스튜디오 문이 열린다. 하얀 장갑 둘이 나와 인형을 일으킨다. 가볍다. 장갑들은 무게를 따지지 않는다. 이름표만 본다.<br>인형이 스튜디오로 들어갔다. 박수가 났다. 그사이 송출 부스 쪽으로 갔다. 한참 뒤 스튜디오에서 언니가 웃음 섞인 목소리로 말했다. 오늘 친구는 참 조용하네.`,
      ng:`인형 가슴에 이름표를 달았는데 이름 칸에 글씨가 스스로 적힌다. 크레용으로. 이쪽 이름.<br><br>장갑들이 나와 인형을 본다. 그리고 이름표를 본다. 인형이 아니라 이름표를 따라 고개를 돌린다. 이쪽을 향해.<br>송출 부스 쪽으로 뛰었다. 장갑 하나가 등을 스쳤다. 등에 손가락 넷 자국이 차갑게 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 이름표에 지어낸 이름을 적어 직접 달고 무대 옆을 지난다.', k:'hide', dc:23,
      doom:{ title:'오늘의 친구', what:'불린 이름에 대답하고 무대로 끌려 나갑니다', dc:18, sec:45,
        text:`크레용으로 이름을 지어 적었다. 아무 데도 안 쓴 이름. 가슴에 달고 무대 옆 통로로 들어갔다.<br><br>오늘의 친구는 무대 옆을 지나도 된다. 장갑들이 비켜 준다. 송출 부스가 보인다.<br>언니가 이름을 부른다. 지어낸 그 이름을. 다정하게. 대답하지 않으려 했다. 그런데 그 이름은 지어낼 때 이쪽이 처음 부른 이름이다. 처음 부른 사람은 대답하게 된다.<br><br>네. 입이 말했다. 무대 조명이 이쪽을 비춘다. 장갑들이 양 팔을 잡는다. 무대로.`,
        dieText:`생방송이 시작됐다. 오늘의 친구가 무대에 섰다.<br><br>가슴 이름표의 이름은 이 세상에 없던 이름이다. 이제는 있다.<br>방글 동산 출연자 명단에 그 이름이 한 줄 늘었다.` },
      ok:`이름을 지어 적으려다 크레용을 내려놓았다. 이름 칸을 비워 둔 채 달았다.<br><br>무대 옆 통로로 들어갔다. 장갑들이 비켜 준다. 언니가 이름을 부르려 한다. 이름표를 본다. 비었다. 부를 이름이 없다.<br>언니가 웃는다. 이름을 잊었구나. 괜찮아, 나중에. 그 나중이 오기 전에 송출 부스 앞에 닿았다. 이름표는 떼어 무대 아래로 떨어뜨렸다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'무대 뒤 — 결석생',
  x:`강당 무대 뒤는 물이 얕다. 소품 상자들이 쌓였다. 상자 하나가 아주 작게 떨린다.<br><br>
    물 밑에서 열쇠 소리가 다가온다. 찰랑, 찰랑. 사감이 결석생을 찾는다.<br>
    상자 안에 숨은 것이 있다. 숨을 참는 소리가 난다. 아이다. 3학년 2반 17번.<br><br>
    이쪽은 숨은 사람을 찾는 일도, 숨겨 주는 일도 했다. 어느 쪽 값이 더 비쌌는지 기억한다.`,
  o:[
    { l:'① 사감이 오는 길과 아이가 숨은 길을 함께 읽는다.', k:'sense', dc:22, wake:1,
      ok:`열쇠 소리 박자를 들었다. 셋 걷고 멈추고 둘 걷고. 사감은 상자마다 멈춘다.<br><br>아이 숨소리는 상자 하나가 아니다. 상자에서 상자로 옮겨 간다. 사감이 멈추는 박자 사이에. 아이는 오래 숨었다. 숨는 법을 안다.<br>둘의 길이 겹치지 않는 틈이 있다. 그 틈으로 일행을 지나게 했다. 상자 안에서 아주 작게 고맙다는 숨이 났다.<br><br>쫓는 쪽과 쫓기는 쪽의 길을 한꺼번에 읽는 귀. 첩자는 늘 한쪽 편이었다. 두 길을 다 보면 그 사이에 이쪽 길이 난다.`,
      ng:`읽다가 이쪽 숨이 아이 숨에 맞춰졌다. 같은 박자로 참고 같은 박자로 쉰다.<br><br>열쇠 소리가 이쪽 쪽으로 온다. 사감은 숨소리를 쫓는다. 둘 중 큰 쪽을.<br>상자 뒤로 숨었다. 검은 치맛단이 바로 앞에 섰다. 한참 숨을 참았다. 사감은 다른 상자를 열고 갔다. 가슴이 터질 듯했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 아이 명찰을 받아 다른 상자에 숨겨 준다.', k:'hide', dc:23,
      ok:`상자 틈으로 손을 넣었다. 작은 손이 명찰을 쥐여 준다. 젖지 않은 명찰.<br><br>사감은 명찰을 찾는다. 사람이 아니라. 명찰을 무대 반대편 상자 밑에 넣고 열쇠 소리 반대쪽으로 물러났다.<br>열쇠 소리가 반대편으로 갔다. 오래 거기 머물렀다. 아이는 이쪽 일행 뒤에 붙어 한참 따라오다 물속으로 사라졌다. 고맙다는 말은 없었다. 대신 이쪽 주머니에 젖은 사탕 하나가 들어 있었다.`,
      ng:`명찰을 받는데 손이 놓지 않는다. 같이 가자고 쥔다. 작은 손인데 세다.<br><br>열쇠 소리가 빨라진다. 아이 손이 이쪽을 상자 안으로 당긴다. 같이 숨자고. 상자는 둘이 숨을 크기가 아니다.<br>손을 비틀어 뺐다. 손등에 작은 손톱 자국이 줄지어 났다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-26, spirit:-22 } },
    { l:'③ 사감에게 아이가 다른 층에 있다고 흘린다.', k:'bond', dc:23,
      ok:`물가에 서서 아이 목소리로 위층 쪽에 외쳤다. 선생님, 저 체육관에 있어요.<br><br>열쇠 소리가 멈춘다. 그리고 계단 쪽으로 간다. 위층으로. 서두르지 않는다. 사감은 늘 같은 걸음이다.<br>상자 하나에서 아이가 고개를 내밀었다. 이쪽을 오래 봤다. 그리고 다시 숨었다.`,
      ng:`외쳤는데 목소리가 아이 목소리가 아니었다. 어른 목소리였다.<br><br>열쇠 소리가 이쪽으로 온다. 결석생을 감추는 어른도 결석생과 같다. 검은 치맛단이 물 위로 미끄러져 온다.<br>소품 상자 뒤를 기어서 빠져나왔다. 손바닥이 다 까졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A', t:'복도 — 이름을 빌려 간 것',
  x:`복도 저편에서 누가 이쪽 이름을 쓴다. 이쪽이 쓰던 가짜 이름 하나. 그 이름으로 일행에게 말을 건다.<br><br>
    목소리도 그 이름을 쓸 때 쓰던 목소리다. 말투, 버릇까지.<br>
    그 이름으로 일행 하나를 부른다. 이리 와, 길 찾았어.<br><br>
    이름을 빌려 간 것이다. 이쪽 이름은 여럿이다. 하나를 남이 쓰면 그 이름이 남의 것이 된다. 그 이름으로 한 일은 이쪽이 한 일이 된다.`,
  o:[
    { l:'① 그 이름을 일행 앞에서 버린다고 말한다.', k:'steady', dc:22,
      ok:`일행에게 말했다. 그 이름은 이제 안 쓴다. 그 이름이 부르면 이쪽이 아니다.<br><br>일행이 알아들었다. 저편에서 그 이름으로 부르는 목소리를 아무도 안 따라갔다.<br>버린 이름은 힘이 없다. 저편 목소리가 그 이름을 몇 번 더 부르다 멈췄다. 이름을 바닥에 내려놓는 소리가 났다. 아주 작게.`,
      ng:`버린다고 말하는데 목이 막힌다. 그 이름으로 산 몇 해가 목에 걸린다.<br><br>다 못 버렸다. 일행 하나가 그 목소리 쪽으로 반 걸음 갔다. 붙잡았다.<br>저편 목소리가 이쪽 진짜 목소리로 웃었다. 그 웃음이 한참 귀에 남았다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 그 이름 쓰는 것을 몰래 밟아 가서 이름을 되찾는다.', k:'hide', dc:23,
      doom:{ title:'빌린 이름', what:'제 이름에 불려 이름 쓴 것에게 끌려갑니다', dc:18, sec:45,
        text:`그것의 뒤를 밟았다. 소리 없이. 그것은 이쪽 이름으로 걸으며 이쪽 버릇대로 모퉁이를 돈다.<br><br>모퉁이 뒤에서 그것이 멈춘다. 돌아보지 않고 말한다. 이쪽 이름을, 이쪽에게. 따라오는 거 알아.<br>그 이름으로 불리면 몸이 대답한다. 그 이름으로 산 몸이다. 발이 그쪽으로 간다.<br><br>그것이 손을 내민다. 이쪽 손이다. 이쪽 손금까지. 잡는다. 이름이 이쪽을 끌고 간다. 모퉁이 너머로.`,
        dieText:`복도 저편에서 누가 이쪽 이름을 쓴다. 진짜 이름이다.<br><br>목소리도 그 목소리다. 말투, 버릇까지.<br>이제 그 이름을 부를 사람이 아무도 안 남았다. 그것이 대신 쓴다.` },
      ok:`밟아 가기 전에 그 이름으로 쓴 장부를 떠올렸다. 그 이름으로 남긴 서명. 서명 끝에 늘 점 하나를 찍었다.<br><br>그것의 뒤를 밟다가 그것이 벽에 서명을 남기는 걸 봤다. 이쪽 이름. 점이 없다.<br>점이 없으면 이쪽 이름이 아니다. 그 서명 위에 다른 이름 하나를 덧써 지웠다. 그것이 갑자기 이름을 잃은 듯 멈춰 섰다. 그 틈에 돌아섰다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'문 — 문패',
  x:`복도에 문이 셋. 문마다 문패가 붙었다. 숙직실, 창고, 그리고 이름 하나.<br><br>
    이름 문패 방에서 숨소리가 난다. 주인이 있다.<br>
    창고 문패 방은 조용하다. 너무 조용하다.<br><br>
    이쪽은 문패를 믿지 않는다. 문패는 누가 붙였느냐가 중요하다.`,
  o:[
    { l:'① 문패 둘을 바꿔 달아 주인이 엉뚱한 문을 열게 한다.', k:'fix', dc:22,
      ok:`이름 문패와 창고 문패를 바꿔 달았다. 못을 손톱으로 빼고, 같은 구멍에 꽂고.<br><br>한참 뒤 이름 방 문이 안에서 열린다. 무엇이 나와 제 문패를 찾는다. 창고 문 앞에 서서 문을 연다. 들어간다. 문이 닫힌다.<br>그 방은 조용했다. 조용한 방이 제일 무섭다. 이쪽은 원래 이름 방으로 들어가 반대편 창으로 나갔다.`,
      ng:`바꿔 다는데 못이 휘었다. 문패 하나가 바닥에 떨어진다. 딸그락.<br><br>이름 방 숨소리가 멎는다. 문고리가 돈다. 이쪽은 아직 손에 문패를 쥐고 있다.<br>문패를 던지고 뛰었다. 등 뒤에서 문이 열리고 젖은 손이 뒷머리를 스쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 이름 문패의 이름을 읽고 문 너머를 엿듣는다.', k:'sense', dc:22,
      ok:`문패 이름을 읽었다. 소리 내지 않고. 이 건물 직원 명단에서 본 이름이다. 퇴근 칸이 빈 사람.<br><br>문에 귀를 대지 않고 문틀 옆 벽에 손바닥을 댔다. 안에서 사람이 오락가락한다. 오래 갇힌 사람 걸음이다. 해칠 걸음이 아니다.<br>문을 두드려 직원 신호로 말했다. 나가는 길은 왼쪽. 안에서 걸음이 멈췄다. 그리고 문 밑 틈으로 열쇠 하나가 밀려 나왔다.`,
      ng:`엿듣는데 안의 걸음이 이쪽 박자로 바뀐다. 이쪽이 엿듣는 걸 엿듣는다.<br><br>문 밑 틈으로 숨이 나온다. 차다. 엿듣던 귀에 바로.<br>귀가 얼얼하게 언다. 한참 그쪽 귀가 안 들렸다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'깊은 곳 — 명부를 쥔 것',
  x:`넓은 방 한가운데 그것이 앉아 있다. 무릎 위에 두꺼운 명부. 넘기며 읽는다.<br><br>
    읽는 이름마다 방 어딘가에서 대답이 난다. 네. 그리고 대답한 자리가 조용해진다.<br>
    일행 이름이 가까워진다. 명부 몇 장 뒤다.<br><br>
    첩자에게는 이름이 여럿이다. 명부에 적힌 것은 그중 하나뿐이다. 어느 것인지가 중요하다.`,
  o:[
    { l:'① 이쪽의 가장 하찮은 이름 하나를 대신 바친다.', k:'hide', dc:24, wake:1,
      ok:`명부를 읽는 쪽의 등 뒤로 돌아갔다. 소리 없이. 명부가 넘어가는 박자에 맞춰.<br><br>어깨 너머로 명부를 봤다. 일행 이름 다섯. 이쪽 이름 하나. 이쪽 이름은 이쪽이 쓰던 이름 중 하나다. 어느 장터에서 하루 쓴 이름.<br>그 이름에 대답해 주었다. 네. 그 이름의 주인은 원래 하루짜리다. 그것이 만족하고 명부를 덮었다. 일행 이름은 읽히지 않았다.<br><br>하루짜리 이름 하나로 다섯을 산 날이다. 여럿인 이름을 쓰는 법이 아니라 바치는 법. 무엇을 줘도 되는지 아는 사람이 끝까지 남는다.`,
      ng:`등 뒤로 돌다가 명부에 적힌 이쪽 이름이 진짜 이름인 걸 봤다. 하찮은 이름이 아니다.<br><br>그것이 그 이름을 읽는다. 대답하지 않았다. 그것이 다시 읽는다. 천천히. 목에서 대답이 올라온다. 이를 악물었다.<br>그것이 고개를 돌린다. 팔이 이쪽을 쳐서 날렸다. 일행이 끌어당겨 겨우 문 밖으로 나왔다. 그 이름이 아직 그것 손에 있다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-28 } },
    { l:'② 명부를 슬쩍 빼서 일행 이름에 줄을 긋는다.', k:'fix', dc:24,
      ok:`그것이 이름 하나를 읽고 대답을 기다리는 사이. 명부 끝장을 손가락으로 들춰 일행 이름 다섯에 줄을 그었다. 갚음. 퇴사. 결석. 아무 줄이든.<br><br>그것이 다음 장을 넘긴다. 줄 그은 이름은 건너뛴다. 이미 처리된 이름이다.<br>그것이 명부를 다 읽고 덮었다. 다섯은 다 서 있었다. 그것은 고개를 갸웃했지만 명부를 믿었다.`,
      ng:`줄을 긋는데 펜 끝이 종이를 찢었다. 그것이 명부를 내려다본다. 찢긴 자리를.<br><br>그리고 이쪽 손을 본다. 손이 명부에 붙는다. 명부가 이쪽 손을 한 장으로 삼는다.<br>일행이 손목을 잡고 떼어 냈다. 손바닥에 이름 줄이 잉크처럼 배어 들었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-22 } },
    { l:'③ 일행을 저마다 다른 이름으로 불러 대답을 섞는다.', k:'bond', dc:23,
      ok:`일행에게 손짓했다. 이제부터 서로를 다른 이름으로 부른다. 꽃 이름, 짐승 이름. 아무거나.<br><br>그것이 일행 이름을 읽는다. 아무도 대답하지 않는다. 다들 지금 다른 이름이다. 그것이 다시 읽는다. 대답 대신 방 안에서 꽃 이름, 짐승 이름이 오간다.<br>그것이 헷갈려 명부를 처음으로 넘긴다. 그사이 다들 문을 나섰다.`,
      ng:`하나가 새 이름을 까먹었다. 제 이름이 불리자 그만 고개를 들었다.<br><br>그것의 손이 그 사람을 가리킨다. 그 사람이 그쪽으로 걷는다. 붙잡았다. 둘이 같이 끌려가다 문틀을 붙잡았다.<br>셋이 매달려 떼어 냈다. 어깨가 빠질 듯 아팠다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-30, spirit:-24 } }
  ] }

]);

// ── 좀도둑 (thief) · 무력 ──
kJob('thief', 'A', [

{ at:'A', t:'복도 — 주인이 따라온다',
  x:`아까 바닥에서 단추 하나를 주웠다. 반들반들한 검은 단추. 버릇처럼 주머니에 넣었다.<br><br>
    그 뒤로 등 뒤에서 발소리가 난다. 한 걸음씩. 이쪽이 서면 선다.<br>
    주인이 없는 것은 없다. 다만 지금 없을 뿐. 좀도둑이 늘 하던 말이다.<br><br>
    지금 그 주인이 있다. 바로 뒤에. 단추 하나를 찾으러.`,
  o:[
    { l:'① 돌아서는 척 주인 소매에 단추를 도로 넣어 준다.', k:'hide', dc:22, wake:1,
      ok:`모퉁이에서 일부러 비틀거렸다. 뒤에 선 것과 어깨가 스쳤다. 그 순간 손가락으로 단추를 그것의 소매 안에 밀어 넣었다.<br><br>스친 것은 소매가 젖은 무엇이었다. 차다. 소매 끝에 단추 구멍이 하나 비어 있었다. 거기 맞는 단추다.<br>발소리가 멈췄다. 소매를 더듬는 소리. 찾았다. 발소리가 반대로 멀어졌다.<br><br>빼는 손으로 넣는 법을 배웠다. 돌려줄 때가 더 어렵다. 들키지 않고 돌려주는 손은 들키지 않고 빼는 손보다 한 수 위다.`,
      ng:`스치는 순간 그것의 손이 먼저 이쪽 주머니에 들어왔다. 빠르다. 이쪽보다.<br><br>단추를 쥐어 갔다. 그리고 이쪽 단추 하나를 뜯어 갔다. 셔츠 맨 위.<br>발소리가 멀어졌다. 목덜미로 찬 바람이 들어온다. 그 단추 자리가 한참 시렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 무력을 실어 단추를 복도 끝으로 멀리 던진다.', k:'evade', dc:23, cost:{ might:28 },
      ok:`단추를 손가락에 걸고 팔에 힘을 다 실어 던졌다. 복도 끝 어둠 너머로.<br><br>멀리서 딸깍. 바닥에 떨어지는 소리. 등 뒤 발소리가 그 소리 쪽으로 간다. 빠르다. 이쪽 옆을 바람처럼 지나갔다.<br>그사이 반대쪽 계단으로 내려갔다. 주인은 물건을 쫓는다. 물건을 든 손은 안 쫓는다. 대개는.`,
      ng:`던졌는데 단추가 손가락에서 안 떨어진다. 실이 감겨 있다. 단추에서 실이 나와 이쪽 손가락을 감았다.<br><br>실 끝은 등 뒤로 이어진다. 등 뒤 것이 실을 감아 당긴다. 손이 뒤로 꺾인다.<br>실을 이빨로 끊었다. 손가락에 실 자국이 깊게 패었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'③ 단추를 꼭 쥐고 일행 가운데 서서 버틴다.', k:'steady', dc:22,
      ok:`단추를 주먹에 쥐고 일행 한가운데로 들어갔다. 어깨를 붙였다.<br><br>발소리가 일행 둘레를 돈다. 한 바퀴, 두 바퀴. 다섯이 막고 있으면 손이 안 들어온다.<br>세 바퀴째에 발소리가 멎었다. 포기한 것이다. 주먹을 폈다. 단추가 젖어 있었다. 손에 쥐고 있는 동안 내내 땀이 아니라 물이 났다.`,
      ng:`버티는데 주먹이 저절로 풀린다. 손가락 하나씩. 바깥에서 누가 하나씩 펴는 것처럼.<br><br>단추가 손바닥에서 굴러 떨어진다. 일행 다리 사이로. 바닥에서 사라진다.<br>손가락이 한참 펴진 채로 굳어 있었다. 주먹이 쥐어지지 않았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A1', t:'접수처 — 분실물 상자',
  x:`접수대 옆에 분실물 상자가 있다. 방청객이 두고 간 것들. 모자, 장갑, 물병, 사탕 봉지.<br><br>
    물건마다 이름표가 붙었다. 크레용 글씨. 찾아가세요.<br>
    아무도 안 찾아갔다. 커튼 밑으로 갈색 털 발이 보인다. 분실물 상자를 지키는 발이다.<br><br>
    손이 저절로 상자로 간다. 주인 없는 물건은 손이 먼저 안다.`,
  o:[
    { l:'① 커튼 쪽 발이 숨 쉴 때만 손을 넣어 쓸 것을 빼 온다.', k:'hide', dc:22, wake:1,
      ok:`커튼 밑 털이 숨에 맞춰 부풀었다 가라앉는다. 가라앉을 때가 내쉴 때다. 내쉴 때는 귀가 반쯤 닫힌다.<br><br>그때마다 손가락 둘을 넣었다. 물병 하나. 마개가 봉해졌다. 사탕 봉지 하나. 이름표는 상자에 남겨 두었다. 이름표만 있으면 물건이 아직 거기 있는 줄 안다.<br>털이 끝까지 고르게 숨을 쉬었다.<br><br>남의 숨을 시계 삼는 손. 지키는 것의 숨을 세면 지키지 않는 틈이 보인다. 손이 훔치는 박자를 남에게서 빌리게 됐다.`,
      ng:`손을 넣는데 상자 안에서 이름표 하나가 손등에 붙었다. 크레용 이름. 이쪽 이름이다.<br><br>커튼이 열린다. 단추 눈. 분실물을 찾으러 온 주인을 반기는 눈이다. 팔이 벌어진다.<br>상자째 엎고 뛰었다. 손등의 이름표가 안 떨어진다. 떼어 내니 살갗이 그 모양으로 벗겨졌다.`,
      win:{ exp:20, dream:3, item:'맑은 물' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 상자 맨 밑에 깔린 것을 무게로 가늠해 하나만 고른다.', k:'luck', dc:22,
      ok:`위의 것들은 가볍다. 맨 밑에 손가락 끝에 묵직한 것이 걸린다. 천에 싸였다.<br><br>천을 풀었다. 꿀 단지. 밀랍 뚜껑. 이름표가 없다. 상자에 넣은 사람이 이름을 안 붙인 것이다. 그러면 분실물이 아니다. 숨겨 둔 것이다.<br>누가 숨긴 건지는 모른다. 고맙게 챙겼다.`,
      ng:`묵직한 것을 쥐었다. 따뜻하다. 천이 아니라 털이다.<br><br>상자 밑에서 털 손이 이쪽 손을 쥐었다. 상자 바닥이 커튼 뒤로 이어져 있다.<br>당겨 뺐다. 손목에 털이 박혀 따끔거린다. 좀약 냄새가 한참 손에서 안 빠졌다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A2', t:'기숙사 — 사감 허리의 열쇠',
  x:`밤 아홉 시 점호. 사감이 복도를 걷는다. 검은 치맛단이 물 위를 미끄러진다. 허리에 열쇠 꾸러미.<br><br>
    찰랑, 찰랑. 호실마다 멈추고 이름을 부른다.<br>
    꾸러미 맨 끝 열쇠가 따로 논다. 고리가 헐겁다. 꼬리표에 강당.<br><br>
    이쪽은 걷는 사람 허리에서 열쇠를 빼 본 적이 있다. 시장통에서. 그 사람들은 살아 있었다.`,
  o:[
    { l:'① 사감이 이름을 부르는 순간 헐거운 열쇠를 뺀다.', k:'hide', dc:23,
      doom:{ title:'찰랑', what:'사감에게 손목을 잡혀 호실 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`문 그늘에 붙어 기다렸다. 사감이 이쪽 앞을 지난다. 이름을 부른다. 그 순간 손을 뻗었다.<br><br>나머지 열쇠를 손바닥으로 눌러 소리를 죽이고 맨 끝 하나를 고리에서 뺐다. 됐다.<br>그런데 찰랑 소리가 났다. 이쪽 손이 아니다. 이쪽 주머니에서. 아까 넣어 둔 열쇠들이 서로 부딪쳤다. 사감 꾸러미와 같은 소리로.<br><br>사감이 멈춘다. 돌아보지 않고 이쪽 손목을 쥔다. 물처럼 차고 단단하다. 점호 시간에 복도에 있으면 안 되지. 호실 문이 열린다. 안으로.`,
        dieText:`점호가 이어졌다. 412호. 인원 하나 추가.<br><br>사감 꾸러미가 다시 찰랑거린다. 맨 끝 열쇠가 제자리에 있다.<br>그 옆에 열쇠가 하나 늘었다. 꼬리표가 없다.` },
      ok:`손을 뻗기 전에 이쪽 주머니를 먼저 비웠다. 아까 주운 열쇠 둘. 부딪치면 같은 소리가 난다.<br><br>빈손으로 문 그늘에 붙었다. 사감이 이름을 부르는 순간 손가락 둘로 헐거운 열쇠를 뺐다. 나머지는 손바닥으로 눌렀다. 찰랑 소리는 꾸러미가 걷는 소리에 섞였다.<br>사감은 다음 호실로 갔다. 손 안의 열쇠가 차다. 강당 열쇠다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 사감이 지나간 뒤 복도에 떨어진 것을 줍는다.', k:'luck', dc:22,
      ok:`사감이 지나간 물 위에 무언가 떠 있다. 손수건. 사감 손수건이다. 수가 놓였다.<br><br>펼쳐 보니 안에 사탕 셋과 작은 쪽지. 아이 글씨. 선생님 이거 드세요.<br>사감은 이걸 오래 품고 다녔다. 손수건은 다시 물에 띄워 두었다. 사탕 하나만 챙겼다. 나머지는 사감 몫이다.`,
      ng:`떠 있는 것을 줍는데 젖은 손수건이 이쪽 손을 감는다.<br><br>수놓인 글씨가 바뀐다. 이쪽 이름으로. 한 땀씩.<br>손수건을 뿌리쳐 물에 던졌다. 손등에 수 자국이 남았다. 바늘에 찔린 듯 따끔했다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 짐에 든 것',
  x:`쉬는 자리에서 일행 짐이 하나 불룩하다. 아까는 안 그랬다.<br><br>
    좀도둑은 짐의 생김새를 다 외운다. 버릇이다. 들어온 것이 있다.<br>
    짐 주인은 잔다. 짐 끈 사이로 물이 배어 나온다. 마른 짐인데.<br><br>
    누가 넣고 갔다. 빼 가는 손이 있으면 넣는 손도 있다. 넣는 쪽이 늘 더 무섭다.`,
  o:[
    { l:'① 짐 주인 모르게 든 것을 빼서 들어온 길로 돌려 둔다.', k:'hide', dc:22, wake:1,
      ok:`짐 끈을 풀지 않고 옆구리 틈으로 손을 넣었다. 젖은 것이 잡힌다. 실내화 한 짝. 작다.<br><br>짐 둘레 바닥을 봤다. 젖은 발자국이 문 쪽에서 왔다. 발자국 끝에 실내화를 놓았다. 왔던 쪽으로 코를 돌려서.<br>밤에 문 쪽에서 아주 작게 신 신는 소리가 났다. 그리고 멀어졌다.<br><br>넣고 간 것을 넣고 간 자리로 돌려놓는 손. 빼는 일만이 아니다. 물건이 원래 있던 자리를 손이 기억한다.`,
      ng:`옆구리 틈으로 손을 넣었는데 든 것이 이쪽 손을 쥔다. 작은 손이다. 짐 안에.<br><br>짐 주인이 잠결에 뒤척인다. 짐 안의 손이 이쪽을 짐 속으로 당긴다. 팔꿈치까지 들어간다. 짐보다 깊다.<br>짐 주인을 깨워 짐째 거꾸로 흔들었다. 물이 쏟아지고 팔이 빠졌다. 팔에 작은 손자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 든 것을 꺼내 무엇인지 확인한다.', k:'gaze', dc:22,
      ok:`짐을 열었다. 맨 위에 젖은 쪽지 한 장. 접혀 있다. 펴 봤다.<br><br>삐뚤빼뚤한 글씨. 이 사람 짐에 숨어도 돼요? 그 밑에 다른 글씨. 안 돼.<br>쪽지 밑에는 아무것도 없다. 숨으려던 것이 쪽지만 남기고 갔다. 쪽지를 접어 문 밖에 두었다.`,
      ng:`꺼냈다. 젖은 명찰이다. 짐 주인 이름. 학년, 반 칸이 채워졌다.<br><br>짐 주인이 잠결에 대답한다. 네.<br>흔들어 깨웠다. 깬 사람이 한참 어디 있는지 몰랐다. 명찰은 불에 넣었다. 잘 안 탔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'의상실 — 앞치마 주머니',
  x:`의상실 옷걸이에 갈색 털 탈이 걸려 있다. 배에 앞치마를 둘렀다. 앞치마 주머니가 불룩하다.<br><br>
    주머니 밖으로 사탕 봉지 끝이 보인다. 그리고 쇠 고리. 열쇠다.<br>
    탈은 비었다. 걸려 있다. 그런데 앞치마 주머니만 따뜻한 김이 난다.<br><br>
    이쪽은 주머니를 보면 손가락이 근질거린다. 이번엔 손가락보다 등이 먼저 근질거린다.`,
  o:[
    { l:'① 주머니 속 열쇠만 손가락 둘로 빼낸다.', k:'hide', dc:23,
      doom:{ title:'앞치마', what:'털 팔에 안겨 탈 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`손가락 둘을 주머니에 넣었다. 따뜻하다. 고리를 걸었다.<br><br>주머니 안에서 무언가 손가락을 쥔다. 털이 난 손가락. 주머니 안쪽에 손이 있다.<br>걸려 있던 털 팔이 움직인다. 천천히 벌어진다. 반갑다는 몸짓이다. 그리고 이쪽을 안는다.<br><br>털이 얼굴을 덮는다. 좀약 냄새. 탈 등 지퍼가 열리는 소리. 안이 어둡다. 안쪽 털이 이쪽을 받아들인다.`,
        dieText:`의상실 옷걸이에 갈색 털 탈이 걸려 있다. 앞치마 주머니가 불룩하다.<br><br>주머니 밖으로 쇠 고리 두 개가 보인다. 하나는 새것이다.<br>탈이 조금 더 무거워 보인다. 지퍼가 끝까지 닫혔다.` },
      ok:`넣기 전에 주머니 밑단을 봤다. 실밥이 탈 안쪽으로 이어진다. 주머니가 탈 속과 붙어 있다.<br><br>주머니에 손을 넣지 않았다. 대신 주머니 밑단 실밥을 손톱으로 뜯었다. 밑이 열린다. 열쇠와 사탕이 바닥으로 떨어진다.<br>탈 팔이 주머니 쪽으로 움찔했다. 넣은 손이 없다. 바닥의 것을 발끝으로 끌어와 주웠다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 무력을 실어 옷걸이째 탈을 끌어 내린다.', k:'break', dc:23, cost:{ might:30 },
      ok:`옷걸이 레일을 두 손으로 잡고 힘을 다 실어 비틀었다. 걸쇠가 빠진다. 탈이 옷걸이째 바닥으로 떨어졌다.<br><br>쓰러진 탈은 일어나지 못한다. 걸려 있어야 움직이는 것이다. 앞치마 주머니를 뒤집었다. 열쇠 하나, 사탕 한 봉지, 말린 고기 한 조각.<br>탈이 바닥에서 팔을 버둥거렸다. 닿지 않았다.`,
      ng:`비트는데 레일이 아니라 탈이 버틴다. 털 손이 레일을 붙잡았다.<br><br>힘이 엉뚱한 데로 빠졌다. 레일이 이쪽 쪽으로 휘며 어깨를 쳤다.<br>쓰러진 이쪽 위로 탈이 기운다. 털이 얼굴에 닿는다. 기어서 빠져나왔다. 어깨가 한참 올라가지 않았다.`,
      win:{ exp:20, dream:2, item:'말린 고기' }, lose:{ hp:-32, mind:-16 } },
    { l:'③ 주머니 무게와 김으로 든 것을 가늠한다.', k:'sense', dc:22,
      ok:`주머니를 건드리지 않고 김을 봤다. 김은 숨이다. 숨이 주머니 왼쪽에서 나온다. 오른쪽은 안 난다.<br><br>오른쪽은 물건이다. 왼쪽은 손이다. 오른쪽 귀퉁이만 손끝으로 눌러 열쇠를 밀어 올렸다. 주머니 입구로 고리가 나온다. 걸어서 뺐다.<br>왼쪽 김이 한 번 크게 났다. 그뿐이었다.`,
      ng:`가늠하다가 김이 이쪽 얼굴로 왔다. 따뜻하고 비리다.<br><br>숨이다. 주머니가 이쪽을 숨으로 더듬는다. 냄새를 맡는다.<br>물러났다. 그 냄새가 옷에 배어 한참 따라왔다. 다른 탈들이 그 냄새 쪽으로 고개를 돌렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'세탁실 — 교복 주머니',
  x:`세탁실 빨랫줄에 교복이 줄지어 걸렸다. 다 젖었다. 물이 뚝뚝 떨어진다.<br><br>
    교복마다 주머니가 있다. 이쪽 눈에는 주머니만 보인다. 동전 무게, 쪽지 무게, 열쇠 무게.<br>
    줄 끝 교복 하나는 소매가 아래로 늘어져 물에 잠겼다. 소매 끝이 아주 조금 움직인다. 손짓하듯.<br><br>
    주머니는 주인이 입고 있을 때 터는 게 제일 어렵다. 이 교복들은 비었다. 겉으로는.`,
  o:[
    { l:'① 교복을 건드리지 않고 주머니 입구만 손끝으로 훑는다.', k:'hide', dc:22, wake:1,
      ok:`옷깃을 안 건드리고 주머니 입구에 손가락 하나만 걸었다. 하나씩. 교복이 흔들리지 않게.<br><br>여섯째 주머니에 쪽지가 있다. 접혔다. 펼쳐 보니 연필로 그린 지도. 세탁실 뒤 배관 통로. 별표 하나. 비상 계단.<br>열째 주머니에 꿀 사탕 한 줌. 그것도 챙겼다. 줄 끝 소매는 끝까지 이쪽이 오는 걸 몰랐다.<br><br>옷을 흔들지 않고 주머니를 터는 손. 입은 사람이 있든 없든. 손끝이 옷보다 가벼워졌다.`,
      ng:`다섯째 주머니에 손가락을 걸었는데 교복이 흔들렸다. 아주 조금.<br><br>줄 전체가 흔들린다. 교복들이 한꺼번에 이쪽으로 돈다. 빈 옷이 몸 모양으로 부푼다. 소매들이 이쪽 팔을 감는다.<br>줄을 끊고 빠져나왔다. 팔에 젖은 소매 자국이 감겼다. 차가움이 뼈까지 갔다.`,
      win:{ exp:20, dream:3, item:'꿀 한 줌' }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 무력으로 빨래 통을 비틀어 밑에 깔린 것을 꺼낸다.', k:'break', dc:23, cost:{ might:28 },
      ok:`큰 빨래 통이 엎어져 있다. 밑에 무엇이 깔렸다. 통 가장자리를 잡고 힘을 다 실어 비틀어 들었다.<br><br>밑에 기름종이 꾸러미. 세탁부 아주머니 도시락이다. 말린 고기와 소금 덩이가 들었다. 젖지 않았다.<br>통을 도로 내려놓았다. 통 안쪽 바닥에 손톱 자국이 많다. 안에서 긁은 자국이다. 안을 보지 않았다.`,
      ng:`들어 올리는데 통 안에서 물이 쏟아진다. 통보다 많은 물이다.<br><br>물과 함께 손이 쏟아진다. 작은 손들. 이쪽 다리를 붙잡는다. 통 안으로 끌어당긴다.<br>통을 놓고 굴러 빠졌다. 정강이에 통 모서리 자국이 깊다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'A', t:'문 — 자물쇠 안의 손가락',
  x:`쇠문에 자물쇠. 철사를 넣었다. 핀을 하나씩 올린다.<br><br>
    셋째 핀에서 철사가 막혔다. 핀이 아니다. 부드럽다. 철사 끝을 무엇이 쥐었다.<br>
    자물쇠 안에 손가락이 있다. 문 저쪽에서 열쇠 구멍에 손가락을 넣고 있다.<br><br>
    좀도둑은 자물쇠와 싸워 본 적이 많다. 자물쇠 안의 사람과는 처음이다.`,
  o:[
    { l:'① 철사를 놓아주고 남은 핀을 손가락 박자에 맞춰 올린다.', k:'fix', dc:22, wake:1,
      ok:`철사를 놓았다. 손가락이 철사를 쥔 채 멈춘다. 쥐는 데 정신이 팔렸다.<br><br>둘째 철사를 아래로 넣었다. 손가락 밑으로. 남은 핀 둘을 올렸다. 손가락이 철사를 쥐려 움찔할 때마다 반대편 핀을 밀었다.<br>자물쇠가 돌았다. 철커덕. 열쇠 구멍 안에서 손가락이 놀라 빠져나갔다.<br><br>자물쇠 안에 누가 있어도 여는 손. 막는 것이 쇠든 살이든 핀은 핀이다. 손끝에 눈이 하나 더 생겼다.`,
      ng:`놓았던 철사가 도로 이쪽으로 밀려 나왔다. 손가락이 밀었다. 철사 끝이 이쪽 손바닥에 박혔다.<br><br>둘째 철사를 넣자 손가락이 그것도 쥐었다. 둘 다 빼앗겼다.<br>열쇠 구멍 안에서 손가락이 이쪽을 향해 까딱인다. 들어오라는 듯이. 손바닥이 한참 욱신거렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 무력을 실어 자물쇠째 문에서 뜯어낸다.', k:'break', dc:23, cost:{ might:30 },
      doom:{ title:'뜯긴 자물쇠', what:'뚫린 구멍으로 팔을 잡혀 문 너머로 끌려갑니다', dc:18, sec:50,
        text:`자물쇠를 두 손으로 쥐고 힘을 다 실어 비틀었다. 나사가 터지며 자물쇠가 빠진다.<br><br>문짝에 주먹만 한 구멍이 뚫렸다. 구멍 너머가 어둡다. 손가락이 구멍 가장자리를 짚는다. 하나, 둘, 열.<br>손 둘이 구멍으로 나와 이쪽 손목을 쥔다. 뜯어낸 자물쇠를 쥔 손을. 제 것을 돌려 달라는 듯이.<br><br>당긴다. 팔이 구멍으로 들어간다. 어깨가 문짝에 붙는다. 구멍이 넓어진다. 문짝이 종이처럼 찢긴다. 머리가 들어간다.`,
        dieText:`쇠문에 자물쇠가 다시 달렸다. 새것이다.<br><br>열쇠 구멍 안에 손가락이 둘 들어 있다. 하나는 크다.<br>철사를 넣으면 이제 두 손가락이 같이 쥔다.` },
      ok:`비틀기 전에 문짝 경첩을 봤다. 경첩 핀이 녹슬어 헐겁다. 자물쇠 말고 경첩을 뜯었다. 힘을 다 실어서.<br><br>문짝이 경첩 쪽에서 기운다. 자물쇠는 그대로 잠겼다. 열쇠 구멍 안 손가락은 여전히 자물쇠를 지킨다. 그 반대편이 열렸다.<br>기운 틈으로 빠져나갔다. 지키는 쪽이 지키는 데만 지킨다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'계단 — 떨어진 지갑',
  x:`계단 한가운데 지갑이 떨어져 있다. 가죽이다. 불룩하다.<br><br>
    발이 먼저 멈춘다. 손이 먼저 뻗는다. 평생 이걸로 먹고살았다.<br>
    지갑 끈이 계단 위로 길게 늘어졌다. 끈 끝이 위층 어둠으로 들어간다.<br><br>
    떨어진 지갑에 끈이 달려 있으면 그건 떨어진 게 아니다. 놓아둔 것이다.`,
  o:[
    { l:'① 줍지 않고 발끝으로 뒤집어 속만 본다.', k:'gaze', dc:22, wake:1,
      ok:`발끝으로 지갑을 툭 뒤집었다. 끈이 팽팽해진다. 위층에서 무엇이 끈을 쥐고 있다.<br><br>지갑이 벌어진다. 안에 돈이 없다. 사진이 가득하다. 다 다른 얼굴. 다 지갑을 주운 손 사진이다. 손등의 흉터, 반지, 손톱 모양까지.<br>지갑을 그대로 두고 계단을 비켜 올랐다. 위층 어둠에서 끈이 아쉬운 듯 한 번 당겨졌다.<br><br>미끼를 줍기 전에 알아보는 눈. 손이 빠른 것보다 손을 안 내는 때를 아는 것이 오래 사는 법이다. 손에 처음으로 고삐가 생겼다.`,
      ng:`뒤집는데 지갑이 발끝을 문다. 가죽이 입처럼 닫힌다. 신발 코를.<br><br>끈이 당겨진다. 위층으로. 발이 계단을 거꾸로 올라간다. 한 칸, 두 칸.<br>신발을 벗어 버리고 빠졌다. 신발이 지갑에 물린 채 위층으로 끌려 올라갔다. 맨발이 계단에 얼었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 끈을 끊고 지갑만 재빨리 챙긴다.', k:'luck', dc:23,
      ok:`칼날로 끈을 끊는 동시에 지갑을 낚아챘다. 위층에서 끈이 휙 거둬진다. 허공을 쥔 소리.<br><br>지갑 속에 사진 여러 장. 그리고 진짜 동전 몇 닢과 쪽지. 이 건물 비상구 위치를 적은 쪽지다. 주인은 미끼에도 진짜를 조금 섞어 두었다.<br>쪽지만 챙기고 지갑은 계단 아래로 던졌다.`,
      ng:`끈을 끊었는데 지갑이 손에서 안 떨어진다. 끊긴 끈이 손목에 감겼다.<br><br>지갑 안 사진들이 쏟아진다. 사진 속 손들이 계단에 떨어져 기어 온다. 이쪽 발목으로.<br>지갑을 내던지고 뛰었다. 발목에 손가락 자국이 남았다. 사진 속 손 모양 그대로.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'무대 옆 — 소품 냉장고',
  x:`무대 옆에 소품 냉장고가 있다. 요리 코너에 쓰던 것. 문에 스티커. 촬영용, 먹지 마세요.<br><br>
    옆 탁자에 무대 감독 카드 뭉치가 놓였다. 감독은 세트 뒤에서 다른 카드를 넘기는 중이다. 박수. 웃어요.<br>
    냉장고 안에서 웅 소리가 난다. 전기가 없는데.<br><br>
    이쪽에게 먹지 말라는 스티커는 먹어도 된다는 뜻이다. 대개는.`,
  o:[
    { l:'① 탁자의 감독 카드 한 장을 슬쩍 빼 간다.', k:'hide', dc:22, wake:1,
      ok:`뭉치 중간에서 한 장. 맨 위나 맨 아래는 티가 난다. 손끝으로 밀어 빼냈다.<br><br>카드에 큰 글씨. 휴식. 방송 중에 한 번도 안 쓴 카드다. 모서리가 새것이다.<br>세트 뒤 감독 손에 그 카드가 들어가게 했다. 감독이 넘기는 카드 뭉치 사이에 슬쩍 끼웠다. 감독이 넘겼다. 휴식.<br><br>방청석 소리가 한꺼번에 멎었다. 무대 위 것들이 다 앉았다. 남의 손에 패를 끼워 넣는 법. 빼는 손이 판을 바꾸는 손이 됐다.`,
      ng:`빼는데 카드 뭉치가 저절로 넘어간다. 맨 위 카드가 이쪽을 향한다. 오늘의 친구.<br><br>세트 뒤에서 감독이 돌아선다. 몸만. 이쪽 쪽으로 걷는다. 카드를 가지러.<br>카드를 던지고 냉장고 뒤로 숨었다. 감독이 카드를 주워 돌아갔다. 숨이 한참 안 돌아왔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 무력으로 냉장고 문을 비틀어 안의 것을 꺼낸다.', k:'break', dc:23, cost:{ might:28 },
      ok:`문이 얼어붙어 안 열린다. 손잡이를 잡고 힘을 다 실어 비틀었다. 쩍.<br><br>안에 소품 음식. 플라스틱 닭, 고무 케이크. 맨 아래 칸에 진짜가 있다. 비닐에 싼 생선 두 마리. 얼었다. 촬영 전날 사 둔 것이다.<br>문을 닫자 웅 소리가 멎었다. 냉장고 안쪽 벽에 작은 손바닥 자국이 하얗게 서려 있었다.`,
      ng:`문이 열리는 순간 냉기가 쏟아진다. 안에서 무언가 숨을 내쉬었다.<br><br>안쪽 칸에 누가 웅크리고 있다. 작다. 서리 낀 눈이 이쪽을 본다. 추워.<br>문을 닫았다. 닫히지 않는다. 안에서 문을 붙잡았다. 어깨로 밀어 겨우 닫았다. 손가락이 얼어 굽지 않는다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-30, spirit:-18 } },
    { l:'③ 탁자 밑 촬영용 바구니에서 진짜를 고른다.', k:'luck', dc:22,
      ok:`바구니에 채소 모형이 가득하다. 하나씩 눌러 봤다. 딱딱한 것, 딱딱한 것. 하나가 무르다.<br><br>진짜 버섯이다. 마르긴 했다. 그 밑에 진짜 나물 한 묶음. 촬영용으로 진짜를 섞어 두었다. 화면에서는 모형보다 진짜가 가짜 같아 보인다.<br>챙겼다. 모형 채소들이 이쪽을 향해 조금 굴렀다.`,
      ng:`무른 것을 쥐었다. 버섯이 아니다. 손가락이다. 작은 손가락. 바구니 밑에서.<br><br>바구니가 이쪽 손을 문다. 모형 채소 사이로 손이 끌려 들어간다.<br>바구니째 엎고 뺐다. 손등에 작은 이빨 자국이 났다.`,
      win:{ exp:16, dream:2, item:'야생 버섯' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A2', t:'탈의실 — 213번 사물함',
  x:`수영장 탈의실 사물함이 번호대로 줄지었다. 1번부터 212번까지 문이 다 열렸다. 비었다.<br><br>
    213번만 잠겼다. 새 자물쇠. 번호 자물쇠다.<br>
    문틈으로 물이 샌다. 안에서 무언가 문을 아주 작게 두드린다. 톡. 톡.<br><br>
    좀도둑은 잠긴 사물함을 그냥 못 지나간다. 버릇이다. 이번엔 버릇이 등을 떠민다.`,
  o:[
    { l:'① 번호 자물쇠 소리를 들어 하나씩 맞춰 연다.', k:'fix', dc:23,
      doom:{ title:'213번', what:'열린 사물함 안으로 끌려 들어가 문이 닫힙니다', dc:18, sec:45,
        text:`자물쇠에 귀를 댔다. 다이얼을 돌린다. 딸깍. 첫째 숫자. 딸깍. 둘째. 셋째. 2, 1, 3.<br><br>열렸다. 문이 스스로 열린다. 안이 비었다. 물만 찰랑하게 찼다. 사물함보다 깊다.<br>안쪽 벽에 이름표 자리가 있다. 비었다. 물속에서 손이 올라와 이쪽 손목을 잡는다. 이름표 자리를 짚게 한다.<br><br>당긴다. 사물함 안으로. 사람 하나 들어갈 크기다. 딱 맞다. 등 뒤에서 문이 닫힌다. 다이얼이 저절로 돈다.`,
        dieText:`213번 사물함이 잠겼다. 번호 자물쇠.<br><br>문틈으로 물이 샌다. 안에서 무언가 문을 두드린다. 톡. 톡.<br>이름표 자리에 이름이 붙었다.` },
      ok:`다이얼을 돌리다 둘째 숫자에서 멈췄다. 딸깍 소리 뒤에 다른 딸깍 소리가 난다. 안쪽에서도 돌린다.<br><br>안에서 여는 것을 이쪽이 돕고 있었다. 다이얼을 거꾸로 한 바퀴 돌려 놓았다. 안쪽 딸깍이 멈춘다. 처음부터 다시 해야 한다.<br>213번 앞을 떠났다. 등 뒤에서 다이얼 도는 소리가 다시 시작됐다. 아주 천천히.`,
      win:{ exp:22, dream:3 } },
    { l:'② 옆 212번 빈칸 틈으로 손을 넣어 213번 안을 더듬는다.', k:'hide', dc:22,
      ok:`212번 안으로 손을 넣었다. 칸 사이 철판이 녹슬어 틈이 났다. 손가락이 213번 안에 닿는다.<br><br>물. 차다. 그리고 천 조각. 끌어당겼다. 수영모다. 안쪽에 이름이 적혔다. 3학년 2반 17번.<br>수영모 안에 작은 열쇠가 하나 꿰매져 있다. 꼬리표에 강당 무대 뒤. 챙겼다. 213번 안의 두드림이 잠깐 멎었다.`,
      ng:`틈으로 손을 넣었는데 213번 안에서 손이 이쪽 손가락을 하나씩 쥔다. 세듯이.<br><br>다섯을 다 세고 당긴다. 틈이 손목 굵기다. 손목이 틈에 끼었다.<br>철판을 발로 차며 뺐다. 손목에 녹 자국과 손자국이 겹쳐 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A', t:'서랍 — 같이 들어오는 손',
  x:`복도 옆 낡은 서랍장. 맨 아래 칸이 반쯤 열렸다. 안에서 종이 바스락거리는 소리가 난다.<br><br>
    손이 들어간다. 손끝에 무엇이 잡힌다. 그때 손등에 다른 손이 닿는다. 같이 서랍 안에.<br>
    다른 손도 무엇을 찾는다. 이쪽 손 옆에서. 이쪽 손가락을 피해 가며.<br><br>
    서랍 안쪽은 벽보다 깊다. 다른 손은 저 깊은 데서 온다.`,
  o:[
    { l:'① 잡은 것을 다른 손에 먼저 쥐여 주고 빈손으로 빠진다.', k:'hide', dc:22, wake:1,
      ok:`잡은 것을 다른 손 손바닥에 살짝 올렸다. 다른 손이 쥔다. 만족한 듯 손가락을 오므린다.<br><br>그 순간 이쪽 손을 뺐다. 다른 손은 쥔 것을 들고 깊은 데로 돌아갔다. 서랍 안에 다른 것이 남았다. 아까는 다른 손이 덮고 있던 자리.<br>다시 넣어 집었다. 봉한 약초 꾸러미다.<br><br>남과 같은 주머니에 손을 넣었을 때 먼저 내주는 법. 내준 자리에 진짜가 남는다. 같이 훔치는 판에서 몫을 가르는 손이 생겼다.`,
      ng:`쥐여 주려는데 다른 손이 쥔 것 대신 이쪽 손목을 쥔다.<br><br>서랍이 깊어진다. 팔꿈치까지 들어간다. 서랍장 나무가 어깨에 닿는다. 안쪽에서 당긴다.<br>서랍장을 발로 차 넘어뜨리며 뺐다. 팔에 손가락 자국이 감겼다. 서랍 속은 비어 있었다.`,
      win:{ exp:20, dream:3, item:'약초 뭉치' }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 무력을 실어 다른 손을 붙잡아 서랍 밖으로 끌어낸다.', k:'break', dc:23, cost:{ might:30 },
      ok:`다른 손 손목을 낚아챘다. 힘을 다 실어 당겼다.<br><br>손이 서랍 밖으로 나온다. 팔꿈치까지. 그 너머는 없다. 팔만 있다. 하얗고 가늘다. 버둥거린다.<br>놓았다. 팔이 서랍 안으로 쑥 들어가 사라졌다. 서랍 안에 그 손이 쥐고 있던 것이 떨어져 있었다. 녹슨 열쇠.`,
      ng:`당겼는데 다른 손이 더 세게 당긴다. 이쪽 몸이 서랍장에 부딪친다.<br><br>서랍이 닫힌다. 이쪽 손목 위로. 쾅.<br>손목뼈가 울렸다. 일행이 서랍을 비틀어 열어 줬다. 손목이 퉁퉁 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A1', t:'기념품 진열장 — 빈 칸',
  x:`로비 기념품 진열장. 노란 해, 갈색 털, 파란 새 인형이 웃는다.<br><br>
    가운데 칸이 비었다. 가격표만 있다. 다 팔렸어요.<br>
    진열장 유리 귀퉁이에 열쇠 구멍. 안에 작은 상자 하나가 인형들 발밑에 숨어 있다. 직원용. 금고 같다.<br><br>
    이쪽은 진열장을 털어 본 적이 많다. 진열된 것들이 털리는 걸 보고 있는 진열장은 처음이다.`,
  o:[
    { l:'① 유리 판을 소리 없이 들어 올려 상자만 빼낸다.', k:'hide', dc:22, wake:1,
      ok:`유리 판 홈에 손톱을 넣었다. 판을 홈에서 반 뼘 들었다. 소리가 안 나게, 숨 쉬는 박자로.<br><br>인형들 발밑으로 손을 넣었다. 웃는 얼굴들이 위에서 내려다본다. 유리에 비친 것만 고개를 돌린다. 진짜는 안 돌린다.<br>상자를 빼고 유리를 내렸다. 홈에 맞게. 상자 안에 꿀 사탕과 직원 출입증 하나.<br><br>보는 눈 앞에서 빼 오는 법. 눈은 움직이는 것을 본다. 손은 움직였지만 유리는 안 움직였다. 손이 판의 소리까지 쥐게 됐다.`,
      ng:`유리 판을 들었는데 홈에서 쇳소리가 났다. 아주 작게.<br><br>유리 안 인형들이 일제히 이쪽을 본다. 진짜 인형이. 박음질한 입이 한 땀씩 올라간다.<br>손을 빼려는데 인형 하나가 손가락을 문다. 이가 있다. 손가락에 작은 이빨 자국이 났다.`,
      win:{ exp:20, dream:3, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 다 팔렸어요 가격표를 다른 칸에 바꿔 붙인다.', k:'fix', dc:22,
      ok:`가격표를 떼어 맨 아래 칸으로 옮겨 붙였다. 다 팔렸어요.<br><br>가운데 빈 칸에는 이제 가격표가 없다. 빈 칸에 가격표가 없으면 채울 것도 없다.<br>맨 아래 칸 인형들이 서로를 본다. 다 팔렸다는데 자기들이 남아 있다. 하나씩 진열장 안쪽 깊이로 숨는다. 진열장 앞이 조용해졌다.`,
      ng:`옮겨 붙이는데 가격표 뒷면에 글씨가 적힌다. 입고 예정. 키와 몸무게. 이쪽 것.<br><br>가운데 빈 칸이 이쪽 쪽으로 넓어진다. 유리문이 열린다.<br>가격표를 찢었다. 찢긴 조각이 손에 붙었다. 털어 내니 손바닥이 솜처럼 감각이 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'조리실 — 저장고 사슬',
  x:`조리실 안쪽에 저장고 문. 쇠사슬이 감겼다. 자물쇠는 녹이 슬었다.<br><br>
    사슬 끝이 바닥 물속으로 들어간다. 사슬이 아주 조금 팽팽해졌다 풀어진다. 물 밑에서 누가 쥐고 있다.<br>
    저장고 안에는 먹을 것이 있다. 학교 사람 이백 명이 겨울을 날 만큼.<br><br>
    좀도둑은 사슬을 풀어 본 적이 있다. 사슬을 쥔 손이 있을 때는 아니다.`,
  o:[
    { l:'① 사슬이 풀어지는 박자에 맞춰 한 고리씩 푼다.', k:'hide', dc:22,
      ok:`사슬이 풀어질 때 한 고리. 팽팽해지면 멈춤. 물 밑 손은 쥐고 있을 뿐 세지 않는다.<br><br>여섯 고리를 풀자 문이 한 뼘 열렸다. 그 틈으로 손을 넣었다. 선반에 소금 자루와 말린 고기 꾸러미.<br>자루 하나만 빼냈다. 나머지는 두었다. 사슬은 원래대로 감아 두었다. 물 밑에서 아무것도 눈치채지 못했다.`,
      ng:`넷째 고리를 풀 때 사슬이 팽팽해졌다. 손이 고리 사이에 끼었다.<br><br>물 밑에서 당긴다. 사슬이 손가락을 감아 조인다. 물 쪽으로 끌린다.<br>손가락을 비틀어 뺐다. 손가락 마디마다 사슬 자국이 시퍼렇다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 무력으로 녹슨 자물쇠를 비틀어 끊는다.', k:'break', dc:23, cost:{ might:30 },
      ok:`자물쇠를 쥐고 힘을 다 실어 비틀었다. 녹슨 쇠가 끊어진다.<br><br>사슬이 풀려 물속으로 빨려 들어간다. 물 밑 손이 사슬만 쥐고 갔다. 문이 활짝 열렸다.<br>저장고 안 선반에 짐승 고기가 소금에 절여 걸렸다. 한 덩이 내렸다. 문을 닫으면서 문 안쪽에 그어진 금을 봤다. 날짜를 센 금이다. 끝이 없다.`,
      ng:`끊었다. 사슬이 풀리며 물속으로 빨려 든다. 이쪽 발목에 감긴 채.<br><br>발이 물 밑으로 끌린다. 저장고 문이 아니라 조리실 바닥 물 쪽으로.<br>일행이 붙잡아 줬다. 사슬을 발로 밀어 벗겨 냈다. 발목에 사슬 자국이 감겼다.`,
      win:{ exp:20, dream:2, item:'짐승 고기' }, lose:{ hp:-32, mind:-16 } },
    { l:'③ 저장고 문 옆 출납 장부를 본다.', k:'gaze', dc:22,
      ok:`장부에 꺼낸 것들이 적혔다. 날짜, 품목, 꺼낸 사람.<br><br>물이 든 날 이후로 꺼낸 사람 칸이 하나다. 사감. 매일 한 줌. 품목은 소금.<br>사감은 소금으로 무엇을 막는다. 저장고 문 아래 선에 소금이 하얗게 그어져 있다. 그 선을 밟지 않고 문 옆 작은 들창으로 손을 넣었다. 마른 나물 한 다발이 걸렸다.`,
      ng:`장부를 보는데 꺼낸 사람 칸에 이쪽 이름이 적힌다. 오늘 날짜. 품목 칸은 비었다.<br><br>무엇을 꺼낼지 아직 안 정했다는 뜻이다. 아니면 무엇이 꺼내질지.<br>장부를 덮었다. 가슴이 무겁게 눌렸다. 그 칸이 채워지기 전에 조리실을 떠났다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 그건 내 거야',
  x:`불이 꺼졌다. 손에 쥔 것이 있다. 아까 주운 작은 방울.<br><br>
    어둠 속에서 목소리. 아이 목소리다. 그건 내 거야.<br>
    또 다른 목소리. 그건 내 거야. 또. 사방에서.<br><br>
    주인이 없는 것은 없다. 다만 지금 없을 뿐. 지금은 주인이 너무 많다.`,
  o:[
    { l:'① 쥔 것을 내려놓고 빈 두 손을 펴 보인다.', k:'steady', dc:23, wake:1,
      ok:`방울을 바닥에 내려놓았다. 소리가 안 나게. 두 손을 펴서 어깨 높이로 들었다. 빈손이다.<br><br>목소리들이 조용해진다. 바닥에서 방울이 굴러간다. 작은 손이 집어 간다. 한 손이.<br>다른 목소리들은 더 말하지 않았다. 주인은 하나였다. 나머지는 빈손을 보려던 것들이다. 빈손에는 할 말이 없다.<br><br>쥔 것을 놓을 줄 아는 손. 이 손은 쥐는 데만 빨랐다. 놓는 손이 있어야 다음 것을 쥔다는 걸 손바닥이 알았다.`,
      ng:`내려놓는데 방울이 울렸다. 딸랑.<br><br>목소리들이 한꺼번에 방울 쪽으로 온다. 이쪽 발밑으로. 작은 손들이 바닥을 더듬는다. 방울을 찾다가 이쪽 발목을 쥔다. 그것도 내 거야.<br>발을 빼며 뒷걸음질 쳤다. 발목에 손가락 자국이 여럿 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 쥔 것을 소매 깊이 감추고 모른 척 버틴다.', k:'hide', dc:22,
      ok:`방울을 소매 안 실밥에 걸어 감췄다. 흔들려도 안 울리게 혀를 손가락으로 눌렀다.<br><br>목소리들이 다가와 이쪽 둘레를 돈다. 그건 내 거야. 이쪽은 아무것도 안 쥐었다. 손바닥을 펴 보였다.<br>목소리들이 하나씩 멀어진다. 불이 다시 켜졌다. 소매 안에 방울이 그대로 있다. 다만 차갑다. 아주.`,
      ng:`감췄는데 소매 안에서 방울이 혼자 울린다. 딸랑, 딸랑.<br><br>목소리들이 웃는다. 거기 있네. 소매 속으로 손들이 들어온다. 차갑다.<br>소매를 찢어 방울을 던졌다. 팔에 손톱 자국이 길게 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 우는 물건들',
  x:`쉬는 자리에 짐을 풀었다. 이쪽 짐에는 이 안에서 주운 것이 많다. 단추, 열쇠, 사탕, 명찰.<br><br>
    밤이 되자 짐 안에서 소리가 난다. 작게. 우는 소리. 물건마다.<br>
    물건이 우는 게 아니다. 물건 주인이 운다. 물건을 통해서.<br><br>
    소리가 커지면 주인들이 찾아온다. 우는 소리를 따라.`,
  o:[
    { l:'① 주운 것을 주운 자리 쪽으로 하나씩 돌려놓는다.', k:'bond', dc:22,
      ok:`짐을 다 쏟았다. 하나씩 집어 어디서 주웠는지 떠올렸다. 좀도둑은 그걸 다 외운다.<br><br>문 밖 복도에 하나씩 놓았다. 주운 쪽을 향해. 단추는 왼쪽, 열쇠는 계단 쪽.<br>밤사이 하나씩 없어졌다. 우는 소리도 하나씩 멎었다. 아침에 짐은 가벼웠다. 문 앞에 사탕 하나가 놓여 있었다. 주인이 돌려준 것이다.`,
      ng:`돌려놓는데 하나를 어디서 주웠는지 모르겠다. 작은 명찰.<br><br>명찰이 계속 운다. 다른 것들이 다 조용해진 뒤에도. 주인이 못 찾는다.<br>밤새 문 밖에서 무엇이 서성였다. 명찰을 쥔 손이 한참 떨렸다. 아침에 명찰 이름이 지워져 있었다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 우는 소리가 큰 것만 골라 멀리 버린다.', k:'sense', dc:22,
      ok:`하나씩 귀에 대 봤다. 단추는 작게, 사탕은 더 작게. 열쇠 하나가 제일 크다. 쇠가 울리듯.<br><br>그것만 들고 복도 끝까지 가서 물속에 던졌다. 우는 소리가 물 밑으로 가라앉았다.<br>나머지는 작게 울다 그쳤다. 그 밤 문 밖에서 물 헤치는 소리가 한 번 났다. 그 열쇠 쪽으로 갔다.`,
      ng:`큰 것을 고르는데 소리가 다 커진다. 이쪽이 귀를 댈수록.<br><br>짐 안에서 한꺼번에 운다. 문 밖에서 발소리가 여럿 다가온다.<br>짐째 복도에 내던졌다. 발소리들이 짐 위로 모였다. 아침에 짐은 텅 비어 있었다. 이쪽 몫까지.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'송출 부스 앞 — 소금 선 안의 출입증',
  x:`송출 부스 앞 바닥에 소금 선이 둥글다. 선 안쪽에 직원 출입증 하나. 송출 담당.<br><br>
    부스 문은 출입증으로 연다. 출입증 없이는 스위치에 손이 안 닿는다.<br>
    선 바깥 어둠에 하얀 장갑들이 모여 있다. 선을 못 넘는다. 이쪽이 선 안으로 손을 넣으면 그 손을 따라 넘어올 수 있다.<br><br>
    이쪽은 줄 친 데 안에서 물건을 빼 오는 일을 많이 했다. 줄은 대개 줄일 뿐이었다.`,
  o:[
    { l:'① 소금 선을 건드리지 않고 손만 넣어 출입증을 집는다.', k:'hide', dc:23,
      doom:{ title:'소금 선', what:'장갑들에게 팔을 잡혀 어둠 속으로 끌려 나갑니다', dc:18, sec:45,
        text:`몸을 낮추고 팔을 뻗었다. 손가락 끝만 선 위로. 선에 안 닿게. 출입증 끈을 걸었다.<br><br>당기는데 끈이 소금 선 위로 끌린다. 소금 몇 알이 흩어진다. 발 하나 너비. 틈이 났다.<br>장갑 하나가 틈으로 들어온다. 이쪽 손목을 쥔다. 손가락 넷. 차다. 다른 장갑들이 틈으로 따라 들어와 팔을, 어깨를 쥔다.<br><br>당긴다. 선 바깥 어둠으로. 출입증이 손에서 떨어져 선 안쪽에 다시 놓인다. 장갑들은 출입증에 관심이 없다.`,
        dieText:`소금 선이 다시 이어졌다. 누가 소금을 부었다.<br><br>선 안쪽에 출입증이 둘. 송출 담당, 그리고 이름 없는 것 하나.<br>선 바깥 장갑 무리 속에 손이 하나 더 섞였다. 맨손이다. 손가락이 다섯이다. 아직은.` },
      ok:`팔을 뻗기 전에 출입증 끈을 봤다. 끈이 길다. 끝이 선 바로 앞까지 와 있다. 일부러 거기 둔 것이다. 바깥에서 끌어당기라고.<br><br>끈을 당기지 않았다. 출입증 쪽 소금 선을 손가락 끝으로 안쪽으로 반 뼘 밀었다. 선을 끊지 않고 둥글게 넓혔다. 출입증이 선 바깥, 이쪽 발밑으로 들어왔다. 선은 하나도 안 끊겼다.<br><br>집었다. 장갑들이 선 앞에서 허공을 쥐었다 폈다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 철사 고리로 출입증 줄을 걸어 끌어온다.', k:'fix', dc:22,
      ok:`철사 끝을 고리로 구부렸다. 선 위 허공으로 넣어 출입증 줄에 걸었다. 철사는 사람 손이 아니다. 장갑들이 따라오지 않는다.<br><br>천천히 끌어왔다. 줄이 선 위를 지난다. 소금이 안 흩어지게 공중으로 들었다.<br>출입증이 손에 들어왔다. 송출 담당 사진이 웃고 있다. 고맙다는 얼굴은 아니다. 지쳤다는 얼굴이다.`,
      ng:`철사로 걸었는데 장갑 하나가 철사 끝을 쥐었다. 바깥에서. 철사를 타고 따라온다.<br><br>철사를 놓았다. 장갑이 철사째 어둠으로 거둬졌다. 출입증은 선 안에 그대로다.<br>손바닥에 철사 자국이 패었다. 장갑이 쥐었던 쪽이 얼음처럼 식었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'강당 — 교탁 서랍',
  x:`강당 무대 위 교탁. 물이 교탁 다리 반까지 찼다. 서랍이 셋.<br><br>
    교탁 뒤에 아무도 없다. 그런데 교탁 위 출석부가 펼쳐졌다. 펜이 놓였다.<br>
    서랍 하나에서 찰랑 소리가 난다. 열쇠. 하교 종 줄을 거는 고리 열쇠다. 강당 벽에 그 고리가 잠겨 있다.<br><br>
    교탁 앞 물이 고요하다. 누가 서 있다. 안 보인다.`,
  o:[
    { l:'① 교탁 앞 것이 출석부를 볼 때 서랍을 소리 없이 연다.', k:'hide', dc:23, wake:1,
      ok:`출석부 장이 넘어간다. 보이지 않는 손이 넘긴다. 넘길 때마다 교탁 앞 물이 아주 조금 기운다. 앞으로. 보는 쪽으로.<br><br>장이 넘어가는 박자에 서랍을 한 칸씩 당겼다. 물에 잠긴 나무가 소리를 먹는다. 손을 넣었다. 열쇠 꾸러미에서 고리 열쇠 하나만.<br>서랍을 닫았다. 출석부가 끝까지 넘어갔다. 교탁 앞 물이 다시 고요해졌다.<br><br>사람이 무엇을 보는 동안 그 앞에서 빼는 손. 보이지 않는 사람도 무엇을 본다. 그 시선의 결을 손이 읽게 됐다.`,
      ng:`둘째 칸에서 서랍이 걸렸다. 덜컥.<br><br>출석부 장이 멈춘다. 교탁 앞 물이 이쪽 쪽으로 기운다. 보이지 않는 손이 서랍을 닫는다. 이쪽 손가락 위로.<br>손가락을 빼는 데 손톱이 두 개 깨졌다. 출석부에 펜이 저절로 무엇을 적었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 무력을 실어 교탁째 뒤집어 서랍을 쏟는다.', k:'break', dc:23, cost:{ might:30 },
      ok:`교탁 모서리를 잡고 힘을 다 실어 뒤집었다. 출석부가 물에 떨어진다. 서랍 셋이 쏟아진다.<br><br>교탁 앞에 있던 것이 출석부 쪽으로 몸을 숙인다. 물이 그쪽으로 몰린다. 출석부를 건지려는 것이다.<br>그사이 물속에서 열쇠를 건졌다. 출석부를 건지는 데 오래 걸렸다. 젖은 출석부는 잘 안 펴진다.`,
      ng:`뒤집으려는데 교탁이 안 움직인다. 앞에서 누가 짚고 있다.<br><br>힘이 다 빠질 때 교탁이 이쪽 쪽으로 넘어왔다. 정강이를 깔았다. 물 밑에서 손들이 다리를 붙잡는다.<br>일행이 교탁을 들어 줬다. 정강이에 피멍이 길게 섰다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-34, mind:-16 } },
    { l:'③ 서랍 밑판 틈으로 손가락만 넣어 무게로 고른다.', k:'luck', dc:22,
      ok:`서랍을 열지 않았다. 교탁 밑으로 손을 넣었다. 서랍 밑판에 틈이 있다. 손가락 두 개 들어간다.<br><br>쇠붙이가 여럿 만져진다. 무게로 골랐다. 제일 작고 제일 무거운 것. 고리 열쇠는 쇠가 두껍다.<br>뽑았다. 맞다. 꼬리표에 종. 교탁은 한 번도 안 흔들렸다.`,
      ng:`손가락으로 고르다가 틈 안에서 다른 손가락이 이쪽 손가락을 짚었다.<br><br>세듯이 하나씩. 다섯. 그리고 쥔다.<br>틈이 좁아 손이 안 빠진다. 교탁째 흔들어 겨우 뺐다. 손가락 마디가 다 까졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 자루를 멘 것',
  x:`복도 저편에서 무엇이 걸어온다. 등에 큰 자루를 멨다. 자루가 꿈틀거린다.<br><br>
    그것은 바닥에서 무엇이든 줍는다. 신발, 모자, 명찰. 자루에 넣는다.<br>
    자루가 지나갈 때 안에서 작은 소리가 난다. 여럿. 숨소리.<br><br>
    이쪽은 남의 자루를 보면 손이 근질거린다. 저 자루 안에는 이 안에서 사라진 것들이 다 들었다.`,
  o:[
    { l:'① 그것이 허리를 숙여 주울 때 자루에서 하나를 빼낸다.', k:'hide', dc:23,
      doom:{ title:'자루', what:'자루 속으로 끌려 들어가 등에 메어집니다', dc:18, sec:45,
        text:`그것이 허리를 숙인다. 신발 한 짝을 줍는다. 자루가 등에서 기운다. 입구가 이쪽을 향한다.<br><br>손을 넣었다. 잡히는 것이 있다. 따뜻하다. 손이다. 자루 안의 손이 이쪽 손을 꼭 쥔다. 놓지 않는다. 같이 나가자는 것인지, 같이 있자는 것인지.<br>그것이 허리를 편다. 자루가 들린다. 이쪽 팔이 자루에 끼인 채 들린다.<br><br>자루 입구가 넓어진다. 어깨가 들어간다. 머리가 들어간다. 안이 따뜻하고 어둡다. 숨소리가 여럿. 가까이.`,
        dieText:`그것이 복도를 걸어간다. 등에 큰 자루를 멨다.<br><br>자루가 조금 더 크다. 꿈틀거림이 하나 늘었다.<br>복도 바닥에 이쪽 신발 한 짝이 남았다. 그것이 돌아와 주울 것이다.` },
      ok:`손을 넣기 직전에 자루 입구를 봤다. 입구 둘레에 손자국이 많다. 안쪽에서 바깥으로 붙든 손자국. 나오려던 손들.<br><br>손을 넣지 않았다. 대신 이쪽 신발 한 짝을 벗어 그것이 줍는 길 앞에 놓았다. 그것이 줍느라 한 번 더 숙인다.<br>그 틈에 자루 아래로 기어 지났다. 그것 뒤로. 자루 안 숨소리들이 이쪽이 지나가는 동안 아주 조용해졌다. 지켜보는 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 무력을 실어 자루 끈을 끊어 떨군다.', k:'break', dc:23, cost:{ might:32 },
      ok:`그것 등 뒤로 다가가 자루 끈을 쥐었다. 힘을 다 실어 한 번에 끊었다.<br><br>자루가 바닥에 떨어진다. 입구가 벌어진다. 안에서 쏟아진다. 신발, 모자, 명찰. 그리고 작은 그림자들이 사방으로 흩어진다. 기어서, 뛰어서.<br>그것이 멈춘다. 흩어진 것들을 보며 오래 서 있었다. 줍지 않았다. 그사이 지나갔다. 발밑에 굴러온 소금 덩이 하나를 챙겼다.`,
      ng:`끈을 쥐었는데 끈이 이쪽 손목에 감긴다. 자루 끈이 아니라 그것의 팔이다.<br><br>그것이 돌아본다. 얼굴이 자루처럼 비었다. 이쪽을 들어 올린다. 자루 쪽으로.<br>손목을 비틀어 뺐다. 손목 살갗이 같이 벗겨졌다. 바닥에 떨어져 한참 일어나지 못했다.`,
      win:{ exp:20, dream:2, item:'소금 덩이' }, lose:{ hp:-34, mind:-16 } }
  ] },

{ at:'A', t:'문 — 저쪽에 꽂힌 열쇠',
  x:`잠긴 문. 열쇠 구멍에 저쪽에서 열쇠가 꽂혀 있다. 열쇠 끝이 구멍 안에 보인다.<br><br>
    좀도둑은 오래된 수를 안다. 문 밑 틈으로 종이를 밀어 넣고, 구멍 안 열쇠를 밀어 떨어뜨리고, 종이째 당긴다.<br>
    문 밑 틈은 종이 한 장 들어갈 만하다.<br><br>
    틈에서 찬 바람이 나온다. 숨 쉬는 박자로.`,
  o:[
    { l:'① 종이를 깔고 열쇠를 밀어 떨어뜨려 끌어온다.', k:'fix', dc:22,
      ok:`벽보 한 장을 뜯어 문 밑으로 밀어 넣었다. 철사로 구멍 안 열쇠를 톡 밀었다. 저쪽에서 쨍그랑.<br><br>종이를 천천히 당겼다. 무겁다. 열쇠가 실렸다. 문 밑을 지나 이쪽으로 나온다.<br>종이 위에 열쇠가 있다. 그리고 젖은 손가락 하나가 종이 끝을 쥐고 있다. 같이 딸려 나왔다. 종이를 찢어 손가락 쪽을 문 밑으로 도로 밀어 넣었다. 열쇠만 남았다.`,
      ng:`종이를 당기는데 저쪽에서도 당긴다. 종이가 팽팽하다.<br><br>찢어졌다. 열쇠는 저쪽에 남았다. 문 밑 틈으로 손가락들이 기어 나와 이쪽 손가락을 더듬는다. 종이를 더 달라는 듯이.<br>손을 뺐다. 손가락 끝이 하얗게 얼었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 문을 건드리지 않고 저쪽 열쇠가 돌기를 기다린다.', k:'steady', dc:22,
      ok:`문 옆 벽에 등을 붙였다. 숨을 죽였다. 저쪽 열쇠를 꽂은 쪽은 언젠가 연다.<br><br>오래. 열쇠가 돈다. 딸깍. 문이 조금 열린다. 아무도 안 나온다. 문만 열렸다. 들어오라는 것이다.<br>들어가지 않았다. 열린 문 안쪽 손잡이에 꽂힌 열쇠만 손을 뻗어 뺐다. 그리고 문을 도로 닫아 이쪽에서 잠갔다. 저쪽에서 한참 손잡이를 돌렸다.`,
      ng:`기다리는데 열쇠가 돌지 않는다. 대신 열쇠 구멍으로 숨이 나온다. 차다. 이쪽 쪽으로.<br><br>숨이 점점 가까워진다. 열쇠 구멍에 눈이 붙는다. 이쪽을 본다. 문 옆에 붙은 이쪽을.<br>자리를 떴다. 등에 그 눈이 오래 붙어 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'깊은 곳 — 모아 둔 것',
  x:`넓은 방 한가운데 무더기가 있다. 신발, 가방, 명찰, 인형, 열쇠. 이 안에서 사라진 것들이 다 쌓였다.<br><br>
    그 위에 그것이 앉아 있다. 무더기를 품에 안았다. 하나도 안 놓친다는 듯이.<br>
    무더기 맨 아래에 출구 열쇠가 깔려 있다. 그것이 깔고 앉은 바로 밑.<br><br>
    주인이 없는 것은 없다. 저 무더기는 다 주인이 있었다. 지금은 저것이 주인이다.`,
  o:[
    { l:'① 무더기 맨 아래에서 열쇠 하나만 빼낸다.', k:'hide', dc:24, wake:1,
      ok:`무더기 그림자로 기어 들어갔다. 지키는 것은 제 발밑을 안 본다. 품에 안은 것만 본다.<br><br>맨 아래로 손을 넣었다. 위의 것들을 손가락으로 받치며. 하나라도 굴러 떨어지면 끝이다. 열쇠가 손끝에 닿았다. 무게가 맞다. 뺐다. 빈 자리에 이쪽 단추 하나를 밀어 넣었다. 무게를 맞추려고.<br>그것은 끝까지 무더기를 꼭 안고 있었다. 하나가 바뀐 것을 몰랐다.<br><br>빼고 채우고 맞추는 손. 빼낸 자리를 아무도 모르게 하는 손. 가져간 흔적까지 가져가는 법을 알았다.`,
      ng:`빼는 순간 무더기가 기울었다. 위에서 신발 하나가 굴러 떨어진다.<br><br>그것이 고개를 숙인다. 떨어진 신발을 본다. 그리고 그 옆의 이쪽 손을.<br>손이 무더기째 잡혔다. 무더기 속으로 끌려 들어간다. 일행이 다리를 잡아 끌어냈다. 팔에 무더기 모서리들이 박혀 피가 났다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26 } },
    { l:'② 무력을 다 실어 무더기째 밑판을 끌어낸다.', k:'break', dc:24, cost:{ might:34 },
      ok:`무더기 밑에 판자가 깔렸다. 판자 끝을 잡고 힘을 다 실어 당겼다.<br><br>무더기가 판자째 미끄러진다. 그것이 앉은 채 뒤로 넘어간다. 품에서 무더기가 쏟아진다.<br>쏟아진 것 사이에서 열쇠를 집었다. 그것은 흩어진 것들을 주워 담느라 이쪽을 안 봤다. 다 주워 담으려면 오래 걸린다.`,
      ng:`판자가 부러졌다. 힘이 허공으로 빠졌다.<br><br>그것이 일어선다. 무더기가 그것 몸에 붙은 채 같이 일어선다. 신발과 가방으로 된 몸이다.<br>팔이 날아왔다. 벽까지 날아갔다. 일행이 끌어내는 동안 등이 다 결렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-38, mind:-18 } },
    { l:'③ 일행이 반대편에서 물건 하나를 흔들어 눈을 돌린다.', k:'bond', dc:23,
      ok:`일행 하나가 반대편에서 자기 모자를 흔들었다. 새 물건이다.<br><br>그것이 고개를 든다. 새 것을 원한다. 무더기에서 몸을 반쯤 일으켜 그쪽으로 팔을 뻗는다.<br>엉덩이가 들린 그 틈에 맨 아래 열쇠를 뺐다. 모자는 던져 줬다. 모자 하나 값이면 싸다.`,
      ng:`그것이 고개를 안 돌린다. 모자에는 관심이 없다. 이쪽 손만 본다.<br><br>훔치려는 손은 훔치는 손이 제일 잘 안다. 그것도 그렇게 모았다.<br>손등을 밟혔다. 손을 빼는 데 손등 뼈가 울렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-30, spirit:-24 } }
  ] }

]);
